// الوحدة الأولى: مفهوم السيرة النبوية ومصادرها، وحال العرب قبل البعثة

// أولاً: تعريف السيرة النبوية
M(1, 7, 'السيرة في اللغة: الطريقة، كما تُطلق ويُراد بها:', ['الهيئة', 'النسب', 'الغاية', 'ليس مما سبق'], 'السيرة في اللغة: الطريقة، كما تُطلق ويُراد بها الهيئة، ومنه قوله تعالى: ﴿سنعيدها سيرتها الأولى﴾.');
M(1, 7, 'السيرة النبوية في الاصطلاح: ذكر أحداث حياة الرسول ﷺ من مولده إلى وفاته، مرتبةً ترتيباً:', ['زمنياً', 'موضوعياً', 'مكانياً', 'ليس مما سبق'], 'السيرة في الاصطلاح: ذكر أحداث حياة الرسول ﷺ من مولده إلى وفاته، مرتبةً ترتيباً زمنياً.');

// ثانياً: مصادر السيرة النبوية
M(1, 7, 'تنقسم مصادر السيرة النبوية إلى:', ['قسمين', 'ثلاثة أقسام', 'أربعة أقسام', 'ليس مما سبق'], 'تنقسم مصادر السيرة النبوية إلى قسمين: مصادر أصلية، ومصادر تكميلية.');
M(1, 7, 'أيٌّ مما يأتي ليس من المصادر الأصلية للسيرة النبوية؟', ['كتب البلدان', 'كتب المغازي', 'كتب الشمائل', 'كتب دلائل النبوة'], 'المصادر الأصلية: القرآن الكريم، وكتب الحديث الشريف، وكتب المغازي، وكتب الشمائل، وكتب دلائل النبوة؛ أما بعض كتب البلدان الخاصة بمكة والمدينة فمن المصادر التكميلية.');
M(1, 7, 'المصادر التكميلية للسيرة النبوية كتبٌ تتحدّث عن أحداث حياة الرسول ﷺ:', ['عَرَضاً', 'قصداً وتخصّصاً', 'بالتفصيل والاستقصاء', 'ليس مما سبق'], 'المصادر التكميلية: بعض كتب البلدان الخاصة بمكة والمدينة، وكتب التراجم والطبقات الخاصة بالصحابة، وغيرها مما يتحدث عَرَضاً عن أحداث حياة الرسول ﷺ.');

// ثالثاً: فوائد دراسة السيرة النبوية
M(1, 8, 'من فوائد دراسة السيرة النبوية: معرفة المنهج السليم في الدعوة إلى الله، وهو:', ['المنهج النبوي', 'منهج الحكماء', 'منهج الفلاسفة', 'ليس مما سبق'], 'من فوائد دراسة السيرة: معرفة المنهج السليم في الدعوة إلى الله، وهو المنهج النبوي.');
M(1, 8, 'من فوائد دراسة السيرة النبوية: معرفة أبعاد مشروعية الجهاد في سبيل الله، و……:', ['دوافع الفتوحات الإسلامية', 'أسباب الحروب القبلية', 'أخبار الأمم السابقة', 'ليس مما سبق'], 'من فوائد دراسة السيرة: معرفة أبعاد مشروعية الجهاد في سبيل الله، ودوافع الفتوحات الإسلامية.');

// حال العرب قبل البعثة النبوية — أولاً: الحالة الدينية
M(1, 8, 'كان العرب قبل الإسلام يستقسمون عند الأصنام بـ:', ['الأزلام', 'النجوم', 'الحصى', 'ليس مما سبق'], 'كانوا يحجّون إلى الأصنام، ويطوفون بها، ويقدّمون لها القرابين، ويستقسمون عندها بالأزلام.');
M(1, 8, 'كان هُبَل - أعظم الأصنام عند العرب - تمثالاً من:', ['ليس مما سبق', 'النحاس', 'الفضة', 'الخشب'], 'كان هبل تمثالاً من العقيق الأحمر على صورة إنسان مكسور اليد اليمنى.');
M(1, 8, 'كان هُبَل موضوعاً:', ['على بئر في جوف الكعبة', 'أمام باب الكعبة', 'على جبل الصفا', 'ليس مما سبق'], 'كان هبل على بئر في جوف الكعبة، وكان أمام البيت صنمان: إساف ونائلة.');
M(1, 8, 'الصنمان اللذان كانا أمام البيت ينحرون ويذبحون عندهما:', ['إساف ونائلة', 'اللات والعزى', 'مناة وهبل', 'ليس مما سبق'], 'كان أمام البيت صنمان: إساف ونائلة، ينحرون ويذبحون عندهما.');
M(1, 8, 'كان أشدَّ إعظاماً لصنم مناة من غيرهم:', ['الأوس والخزرج', 'ثقيف', 'قريش', 'ليس مما سبق'], 'كانت مناة على ساحل البحر لأهل المدينة، وكان الأوس والخزرج أشدّ إعظاماً لها من غيرهم.');
M(1, 8, 'كان صنم العُزّى:', ['ليس مما سبق', 'على ساحل البحر', 'في جوف الكعبة', 'بالطائف'], 'كانت العزى فوق ذات عِرق، أما مناة فعلى ساحل البحر، واللات بالطائف.');
M(1, 9, 'القائل: «كنا نعبد الحجر، فإذا وجدنا حجراً آخر هو أخير منه ألقيناه، وأخذنا الآخر»:', ['أبو رجاء العطاردي', 'زيد بن عمرو بن نفيل', 'قس بن ساعدة الإيادي', 'ليس مما سبق'], 'روى البخاري في صحيحه عن أبي رجاء العطاردي قال: «كنا نعبد الحجر...».');
M(1, 9, 'من الحنفاء، وكان لا يأكل ما ذُبح على الأنصاب:', ['زيد بن عمرو بن نفيل', 'عمرو بن لحي', 'أبو رجاء العطاردي', 'ليس مما سبق'], 'من الحنفاء: قس بن ساعدة الإيادي، ومنهم زيد بن عمرو بن نفيل، وكان لا يأكل ما ذبح على الأنصاب.');
M(1, 9, 'كان للنصرانية وجود قبل البعثة في:', ['جميع ما ذكر', 'نجران', 'الغساسنة', 'قبائل تغلب وطيء'], 'كان للنصرانية وجود في نجران، وفي الغساسنة، وقبائل تغلب وطيء.');
M(1, 9, 'كان لليهودية وجود قبل البعثة في:', ['يثرب وخيبر', 'مكة والطائف', 'نجد وتهامة', 'ليس مما سبق'], 'كان لليهودية وجود في يثرب وخيبر.');

// ثانياً: الحالة السياسية للعرب قبل البعثة
M(1, 9, 'كانت مملكة الحيرة - من الممالك المتحضرة التي نشأت بالجزيرة - في:', ['الشمال الشرقي', 'الجنوب', 'الشمال الغربي', 'ليس مما سبق'], 'لم يجتمع العرب على دولة واحدة حتى في الممالك المتحضرة، كممالك اليمن، ومملكة الحيرة في الشمال الشرقي.');
M(1, 10, 'كان لكل قبيلة قانون عرفي ينظّم العلاقات بين الفرد والجماعة على أساس:', ['التضامن في الحقوق والواجبات', 'المساواة بين القبائل', 'طاعة الكهّان', 'ليس مما سبق'], 'كان لكل قبيلة قانون عرفي ينظّم العلاقات بين الفرد والجماعة، على أساس من التضامن في الحقوق والواجبات.');
M(1, 10, 'كان زعيم القبيلة يُختار بناءً على:', ['صفاته ومنزلته', 'كثرة ماله', 'كبر سنه فقط', 'ليس مما سبق'], 'على رأس القبيلة زعيم يُختار بناءً على صفاته ومنزلته.');
M(1, 10, 'من الحقوق الأدبية لزعيم القبيلة:', ['النزول على حكمه وقضائه', 'المرباع', 'الصفايا', 'ليس مما سبق'], 'حقوقه الأدبية: احترامه، وتبجيله، والاستجابة لأمره، والنزول على حكمه وقضائه؛ أما المرباع والصفايا فحقوق مادية.');
M(1, 10, 'المرباع من الحقوق المادية لزعيم القبيلة، وهو:', ['ليس مما سبق', 'نصف الغنيمة', 'ما أُصيب من مال العدو قبل اللقاء', 'ما لا يقبل القسمة من مال الغنيمة'], 'المرباع هو ربع الغنيمة.');
M(1, 10, 'الصفايا من الحقوق المادية لزعيم القبيلة، وهي:', ['ما يصطفيه لنفسه من الغنيمة قبل القسمة', 'ما أُصيب من مال العدو قبل اللقاء', 'ما لا يقبل القسمة من مال الغنيمة', 'ليس مما سبق'], 'الصفايا: ما يصطفيه لنفسه من الغنيمة قبل القسمة.');
M(1, 10, 'الفضول من الحقوق المادية لزعيم القبيلة، وهي:', ['ما لا يقبل القسمة من مال الغنيمة', 'ما أُصيب من مال العدو قبل اللقاء', 'نصف الغنيمة', 'ليس مما سبق'], 'الفضول: ما لا يقبل القسمة من مال الغنيمة.');
M(1, 10, 'من واجبات زعيم القبيلة في الحرب:', ['يتقدم الصفوف ويعقد الصلح والمعاهدات', 'يبقى في مؤخرة الجيش لحماية الديار', 'يوكل القيادة إلى أشجع فرسان القبيلة', 'ليس مما سبق'], 'زعيم القبيلة في الحرب يتقدم الصفوف، ويعقد الصلح والمعاهدات.');
M(1, 10, 'كان زعيم القبيلة في السِّلم مسؤولاً عن:', ['جميع ما ذكر', 'إكرام الضيوف', 'إغاثة المحتاجين من أبناء القبيلة', 'إجارة المستجير'], 'فهو في السلم مسؤول عن إكرام الضيوف، وإغاثة المحتاجين من أبناء القبيلة، وإجارة المستجير.');
M(1, 10, 'كانت …… تسود النظام القبلي، وتمثّل أخص خصائص العرب الذين يأبون الضيم والذل:', ['الحرية', 'الشورى', 'المساواة', 'ليس مما سبق'], 'كانت الحرية تسود النظام القبلي، وتمثّل أخص خصائص العرب الذين يأبون الضيم والذل.');

// ثالثاً: الحالة الاجتماعية والأخلاقية للعرب قبل البعثة
M(1, 10, 'كانت …… الموروثة عن الآباء والأجداد شريعةً متّبعةً عند العرب:', ['العادات والتقاليد', 'الأشعار والخطب', 'الأموال والأملاك', 'ليس مما سبق'], 'كانت العادات والتقاليد الموروثة عن الآباء والأجداد شريعة متبعة عند العرب.');
M(1, 10, 'كان الفرد من أفراد القبيلة يقف مع أخيه في السلم والحرب والرشد والغي على السواء، وهذا من مظاهر:', ['العصبية القبلية', 'الحرية', 'الكرم', 'ليس مما سبق'], 'العصبية القبلية ركن من أركان حياتهم الاجتماعية، حتى إن الفرد كان يقف مع أخيه في السلم والحرب والرشد والغي على السواء.');
M(1, 11, 'قامت حرب البسوس بين بكر وتغلب من أجل:', ['ناقة', 'بئر ماء', 'زعامة مكة', 'ليس مما سبق'], 'قامت حرب البسوس بين بكر وتغلب من أجل ناقة، حتى أكلت الكثير من أبطالهم ورؤسائهم.');
M(1, 11, 'دامت حرب البسوس:', ['ليس مما سبق', 'عشرين عاماً', 'ثلاثين عاماً', 'خمسين عاماً'], 'قامت حرب البسوس بين بكر وتغلب أربعين عاماً.');
M(1, 11, 'كان العرب في الجاهلية يئدون البنات خشية:', ['العار', 'الحسد', 'المرض', 'ليس مما سبق'], 'بلغت قساوة العرب إلى حد ذبح الأبناء على النصب والأوثان، وقتل الأولاد خشية الفقر، ووأد البنات خشية العار.');
M(1, 11, 'كان شرب الخمر عند العرب في الجاهلية:', ['من المفاخر التي يتسابقون في مجالسها', 'عاراً يتبرؤون منه', 'خاصاً بالعبيد والموالي', 'ليس مما سبق'], 'كان شرب الخمر من المفاخر التي يتسابقون في مجالسها، حتى نسجوا ذلك في كثير من أشعارهم.');
M(1, 11, 'كان الميسر عند العرب في الجاهلية:', ['من شعار أهل الجود والكرم', 'عاراً على من يشارك فيه', 'محرّماً في الأشهر الحرم فقط', 'ليس مما سبق'], 'كان الميسر عندهم من شعار أهل الجود والكرم، وعدم المشاركة فيه عاراً.');
M(1, 11, 'أصدق وأبلغ وصف للحالة الاجتماعية والخلقية لأهل الجزيرة العربية قبل الإسلام قول …… أمام النجاشي: «أيها الملك! كنا قوماً أهل جاهلية...»:', ['جعفر بن أبي طالب', 'عمرو بن العاص', 'زيد بن عمرو بن نفيل', 'ليس مما سبق'], 'من قول جعفر بن أبي طالب رضي الله عنه أمام النجاشي: «أيها الملك! كنا قوماً أهل جاهلية، نعبد الأصنام، ونأكل الميتة...».');

// رابعاً: محاسن العرب
M(1, 12, 'من صفات العربي قبل الإسلام أنه بعيد عن:', ['المداهنة والمصانعة', 'الشجاعة والصراحة', 'الصدق والأمانة', 'ليس مما سبق'], 'العربي يتسم بالصدق والأمانة، يتحلى بالشجاعة والصراحة، بعيد عن المداهنة والمصانعة.');
M(1, 12, 'كان الرجل من العرب يأتيه الضيف، وليس عنده من المال إلا ناقته التي يعيش عليها، فـ:', ['يذبحها لضيفه', 'يعتذر لضيفه', 'يبيعها ليشتري طعاماً لضيفه', 'ليس مما سبق'], 'كان الرجل يأتيه الضيف، وليس عنده إلا ناقته التي يعيش عليها، فيقوم إليها ويذبحها لضيفه.');
M(1, 12, 'كان العرب بمعزل عن أدواء المدنية والترف، والتي قد تحول دون:', ['التحمس للعقيدة والتفاني في سبيلها', 'الصدق والأمانة', 'حماية الجار والمستجير', 'ليس مما سبق'], 'العرب أصحاب جلادة وتقشف في الحياة، بمعزل عن أدواء المدنية والترف، والتي قد تحول دون التحمس للعقيدة والتفاني في سبيلها.');

// شرف مكة ومنزلتها عند العرب — أولاً: عمارة مكة
M(1, 13, 'أمر الله إبراهيم عليه السلام أن يأتي بزوجته هاجر وابنه إسماعيل إلى مكة من:', ['ليس مما سبق', 'العراق', 'الحبشة', 'اليمن'], 'أمر الله إبراهيم عليه السلام أن يأتي بزوجته هاجر وابنه إسماعيل وهو طفل رضيع من الشام حتى يتركهما في مكة.');
M(1, 13, 'امتنّ الله على أهل مكة بأن جعلها حرماً آمناً في قوله تعالى:', ['﴿أولم يروا أنا جعلنا حرما آمنا ويتخطف الناس من حولهم﴾', '﴿ومن يرد فيه بإلحاد بظلم نذقه من عذاب أليم﴾', '﴿سنعيدها سيرتها الأولى﴾', 'ليس مما سبق'], 'امتنّ الله عليهم بذلك فقال: ﴿أولم يروا أنا جعلنا حرما آمنا ويتخطف الناس من حولهم﴾ (العنكبوت: 67).');
M(1, 13, 'شمل أمان الحرم:', ['جميع ما ذكر', 'الطير في الجو', 'الصيد في البر', 'النبات فوق الأرض'], 'هذا الأمان شمل الطير في الجو، والصيد في البر، والنبات فوق الأرض.');
M(1, 14, 'أخبر النبي ﷺ في خطبته يوم فتح مكة أن القتال في مكة لم يحلّ له إلا:', ['ساعة من نهار', 'يوماً كاملاً', 'ثلاثة أيام', 'ليس مما سبق'], 'قال ﷺ: (وإنه لم يحل القتال فيه لأحد قبلي، ولم يحل لي إلا ساعة من نهار).');

// ثانياً: تعظيم العرب لمكة
M(1, 14, 'من مظاهر تعظيم العرب لمكة أن أحدهم إذا لقي فيها قاتل أبيه أو أخيه:', ['لا يتعرض له حتى يخرج من البلد الحرام', 'يقتله عند باب الكعبة', 'يطلب منه الدية في دار الندوة', 'ليس مما سبق'], 'كان أحدهم يلقى قاتل أبيه أو أخيه فيها فلا يتعرض له حتى يخرج من البلد الحرام.');
M(1, 15, 'زادت حادثة الفيل مكانة مكة في نفوس العرب؛ إذ ثبت لهم بما ليس فيه ريب:', ['حفظ الله لبيته وإهلاكه من أراده بسوء', 'قوة قريش وقدرتها على حماية البيت', 'ضعف جيش أبرهة وقلة عدده', 'ليس مما سبق'], 'خير دليل على تعظيم مكة حادثة الفيل؛ فأباد الله جيش أبرهة، فزادت بذلك مكانة مكة في نفوس العرب؛ إذ ثبت لهم بما ليس فيه ريب حفظ الله لبيته، وإهلاكه من أراده بسوء.');
M(1, 15, 'الذي جمع قريشاً في مكة بعد أن تمكّن من إجلاء خزاعة عنها:', ['قصي بن كلاب', 'عبد المطلب', 'هاشم بن عبد مناف', 'ليس مما سبق'], 'جاء قصي بن كلاب فجمع قريشاً في مكة بعد أن تمكّن من إجلاء خزاعة عنها، وأمرهم ببناء دورها حول الكعبة.');
M(1, 15, 'كانت دار الندوة التي بناها قصي بن كلاب:', ['جميع ما ذكر', 'يجتمع فيها كبراء مكة ليتشاوروا في أمور العباد والبلاد', 'لا يُعقد لواء حرب إلا فيها', 'تجري فيها عقود الزواج والمعاملات'], 'يجتمع فيها كبراء أهل مكة ليتشاوروا، فلا يعقدون لواء حرب إلا فيها، وفيها تجري عقود الزواج والمعاملات.');
M(1, 16, 'بعد موت قصي انقسمت المناصب، فكان في بني هاشم:', ['السقاية', 'الحجابة', 'المشورة', 'ليس مما سبق'], 'انقسمت المناصب بعد موت قصي، فكان في بني هاشم السقاية، وكانت الحجابة في بني عبد الدار، والمشورة في بني أسد.');
M(1, 16, 'بعد موت قصي انقسمت المناصب، فكان في بني نوفل:', ['ليس مما سبق', 'العقاب راية قريش', 'اللواء والسدانة', 'المشورة'], 'كان في بني نوفل الرفادة.');

// الدروس المستفادة
M(1, 16, 'القائل: «كنا نُعلَّم مغازي نبي الله ﷺ وسراياه كما نُعلَّم السورة من القرآن»:', ['زين العابدين علي بن الحسين', 'جعفر بن أبي طالب', 'عبد الله بن عباس', 'ليس مما سبق'], 'يقول زين العابدين علي بن الحسين رضي الله عنهما: «كنا نُعلَّم مغازي نبي الله ﷺ وسراياه كما نُعلَّم السورة من القرآن».');
M(1, 17, 'من الدروس المستفادة: أن الاتباع الأعمى للآباء والأجداد في العادات والتقاليد دون تمحيصها:', ['يؤدي إلى الضلال والخسران ويوقع في الخرافات والوثنية', 'يحفظ وحدة القبيلة وتماسكها', 'لا يضر ما دام موروثاً عن الأجداد', 'ليس مما سبق'], 'خطر الاتباع الأعمى للآباء والأجداد في العادات والتقاليد دون تمحيصها، وأن ذلك يؤدي إلى الضلال والخسران في الدنيا والآخرة، ويوقع الإنسان في الخرافات والوثنية.');

/* ═══════════════ u02 ═══════════════ */
// الوحدة الثانية: مراحل حياته ﷺ الأولى، وما سبقها من مبشرات بنبوته

// إرهاصات النبوة — أولاً: بشارات الأنبياء والكتب السماوية بمحمد ﷺ
M(2, 21, 'أخذ الله الميثاق على النبيين إذا جاءهم رسول مصدّق لما معهم أن:', ['يؤمنوا به وينصروه', 'يكتموا أمره عن أقوامهم', 'يهاجروا إلى أرضه', 'ليس مما سبق'], 'قال تعالى: ﴿وإذ أخذ الله ميثاق النبيين لما آتيتكم من كتاب وحكمة ثم جاءكم رسول مصدق لما معكم لتؤمنن به ولتنصرنه﴾ (آل عمران: 81).');
M(2, 21, 'القائل: «ما بعث الله نبيًّا من الأنبياء إلا أخذ عليه الميثاق...»:', ['علي بن أبي طالب وعبد الله بن عباس', 'أبو بكر الصديق وعمر بن الخطاب', 'سلمان الفارسي وكعب الأحبار', 'ليس مما سبق'], 'قال علي بن أبي طالب وعبد الله بن عباس رضي الله عنهم: «ما بعث الله نبيًّا من الأنبياء إلا أخذ عليه الميثاق، لئن بعث محمد وهو حي ليؤمنن به ولينصرنه».');
M(2, 21, 'يدل قوله تعالى: ﴿الذين يتبعون الرسول النبي الأمي الذي يجدونه مكتوبا عندهم في التوراة والإنجيل﴾ على:', ['أن ذكر النبي ﷺ موجود في كتب الأولين', 'أن أهل الكتاب آمنوا به جميعاً', 'أن الأنبياء السابقين أدركوا بعثته', 'ليس مما سبق'], 'أخبر الله تعالى في كتابه الكريم أن ذكر نبيه محمد ﷺ موجود في كتب الأولين، قال تعالى: ﴿الذين يتبعون الرسول النبي الأمي...﴾ (الأعراف: 157).');
M(2, 22, 'بشّر عيسى عليه السلام قومه برسول يأتي من بعده اسمه:', ['أحمد', 'يحيى', 'إلياس', 'ليس مما سبق'], 'قال تعالى: ﴿ومبشرا برسول يأتي من بعدي اسمه أحمد﴾ (الصف: 6).');
M(2, 22, 'من صفات النبي ﷺ في التوراة كما نقلها كعب الأحبار:', ['جميع ما ذكر', 'لا فظ ولا غليظ', 'لا صخّاب في الأسواق', 'لا يجزي بالسيئة السيئة ولكن يعفو ويغفر'], 'قال كعب الأحبار: «نجد مكتوباً في التوراة: محمد رسول الله، عبدي المختار، لا فظ ولا غليظ، ولا صخاب في الأسواق، ولا يجزي بالسيئة السيئة ولكن يعفو ويغفر...».');
M(2, 22, 'جاء في التوراة في وصف النبي ﷺ: «مولده بمكة، وهجرته ……»:', ['بطيبة', 'بالشام', 'بالحبشة', 'ليس مما سبق'], 'قال كعب الأحبار: «نجد مكتوباً في التوراة: ... مولده بمكة؛ وهجرته بطيبة...».');

// 2- إخبار أهل الكتاب بقرب مبعثه ﷺ
M(2, 22, 'كان اليهود يدركون بالعلامات قرب مبعث النبي ﷺ، ويتوعّدون به العرب من:', ['الأوس والخزرج', 'قريش', 'ثقيف', 'ليس مما سبق'], 'كان اليهود يدركون بالعلامات قرب مبعثه ويتوعّدون به العرب من الأوس والخزرج.');
M(2, 22, 'كان اليهود يقولون للعرب: «إنه تقارب زمان نبي يُبعث الآن، نقتلكم معه قتل ……»:', ['ليس مما سبق', 'ثمود', 'فرعون وقومه', 'قوم لوط'], 'كانوا يقولون: «إنه تقارب زمان نبي يبعث الآن، نقتلكم معه قتل عاد وإرم».');
M(2, 22, 'الصحابي الذي روى أن جاراً لهم من يهود أخبرهم بقرب مبعث النبي ﷺ، وقال عنه: «إن يستنفد هذا الغلام عمره يدركه»:', ['سلمة بن سلامة', 'سلمان الفارسي', 'واثلة بن الأسقع', 'ليس مما سبق'], 'روى سلمة بن سلامة رضي الله عنه قال: كان لنا جار من يهود... فنظر إليّ وأنا من أحدثهم سنًّا، فقال: إن يستنفد هذا الغلام عمره يدركه.');
M(2, 22, 'وقف الجار اليهودي الذي أخبر بقرب مبعث النبي ﷺ على مجلس:', ['بني عبد الأشهل', 'بني هاشم', 'بني سعد بن بكر', 'ليس مما سبق'], 'خرج علينا يوماً من بيته قبل مبعث النبي ﷺ بيسير، فوقف على مجلس بني عبد الأشهل.');
M(2, 22, 'لما سأل القومُ جارَهم اليهودي عن آية البعث، قال: نبي يُبعث من نحو هذه البلاد، وأشار بيده نحو:', ['مكة واليمن', 'الشام والعراق', 'مصر والحبشة', 'ليس مما سبق'], 'قالوا له: ويحك، وما آية ذلك؟ قال: نبي يبعث من نحو هذه البلاد، وأشار بيده نحو مكة واليمن.');
M(2, 23, 'طلب سلمان الفارسي رضي الله عنه الوصية من راهب النصارى في …… عندما حضرته الوفاة:', ['ليس مما سبق', 'نجران', 'الحبشة', 'الحيرة'], 'أخبر سلمان الفارسي في قصة إسلامه أن راهب النصارى في عمّورية عندما حضرته الوفاة طلب منه سلمان أن يوصيه.');
M(2, 23, 'من علامات النبي ﷺ التي ذكرها الراهب لسلمان الفارسي:', ['جميع ما ذكر', 'يأكل الهدية', 'لا يأكل الصدقة', 'بين كتفيه خاتم النبوة'], 'قال الراهب: «به علامات لا تخفى: يأكل الهدية، ولا يأكل الصدقة، بين كتفيه خاتم النبوة».');
M(2, 23, 'أخبر الراهب سلمانَ أن النبي ﷺ يخرج بأرض العرب، مهاجراً إلى أرض بين حرّتين بينهما:', ['نخل', 'بئر', 'وادٍ', 'ليس مما سبق'], 'قال الراهب: «يخرج بأرض العرب، مهاجراً إلى أرض بين حرّتين بينهما نخل».');

// ثانياً: من الأحداث العظام التي سبقت ميلاد المصطفى ﷺ
M(2, 23, 'القائل: «وكان أمر الفيل تقدمة قدّمها الله لنبيه وبيته»:', ['ابن القيم', 'كعب الأحبار', 'سلمة بن سلامة', 'ليس مما سبق'], 'قال ابن القيم رحمه الله: «لا خلاف أنه ولد ﷺ بجوف مكة... وكان أمر الفيل تقدمة قدّمها الله لنبيه وبيته».');
M(2, 23, 'كان أصحاب الفيل:', ['نصارى أهل كتاب', 'يهوداً', 'مجوساً', 'ليس مما سبق'], 'قال ابن القيم: «فأصحاب الفيل كانوا نصارى أهل كتاب، وكان دينهم خيراً من دين أهل مكة إذ ذاك؛ لأنهم كانوا عبّاد أوثان».');
M(2, 24, 'كان أبرهة الأشرم:', ['عامل النجاشي على اليمن', 'ملك الحبشة', 'ملك الحيرة', 'ليس مما سبق'], 'لما احتلت الأحباش اليمن، استولى أبرهة الأشرم - عامل النجاشي - على الحكم فيها.');
M(2, 24, 'بنى أبرهة كنيسته العظيمة «القُلَّيس» في:', ['صنعاء', 'نجران', 'الحبشة', 'ليس مما سبق'], 'بنى أبرهة في صنعاء كنيسة عظيمة سمّاها «القُلَّيس».');
M(2, 24, 'أراد أبرهة ببناء كنيسة القُلَّيس:', ['أن يصرف إليها حج العرب بدل الكعبة', 'أن يجمع فيها جنده للقتال', 'أن تكون سوقاً لتجارة العرب', 'ليس مما سبق'], 'غار أبرهة من الكعبة أن تكون مثابة للناس، فبنى القليس، وأراد أن يصرف إليها حج العرب بدل الكعبة.');
M(2, 24, 'الذي دخل القُلَّيس ليلاً وأحدث فيها رجل من:', ['بني كنانة', 'ثقيف', 'خزاعة', 'ليس مما سبق'], 'سمع بذلك رجل من بني كنانة، فدخلها ليلاً، وأحدث فيها، فاستشاط أبرهة غضباً وعزم على هدم الكعبة.');
M(2, 24, 'سار أبرهة لهدم الكعبة ومعه الفيلة التي استقدمها من:', ['الحبشة', 'الهند', 'الشام', 'ليس مما سبق'], 'سار في جيش عظيم، ومعه الفيلة التي استقدمها من الحبشة.');
M(2, 24, 'لما اقترب أبرهة من مكة قام عبد المطلب ومعه نفر من قريش فـ:', ['أخذوا بحلقة باب الكعبة يدعون الله ويستنصرونه', 'خرجوا لقتاله عند وادي محسّر', 'صالحوه على مال يدفعونه له', 'ليس مما سبق'], 'قام عبد المطلب، ومعه نفر من قريش، فأخذوا بحلقة باب الكعبة، يدعون الله، ويستنصرونه على أبرهة وجنده.');
M(2, 24, 'كان جيش أبرهة كلما وجّهوا الفيل إلى مكة:', ['برك', 'قام يهرول', 'رجع نحو اليمن', 'ليس مما سبق'], 'كانوا كلما وجّهوه إلى مكة برك، وإذا وجّهوه إلى سائر الجهات قام يهرول.');

// نسب الرسول ﷺ وولادته ورضاعته — أولاً: نسبه الشريف
M(2, 25, 'كنية النبي ﷺ:', ['ليس مما سبق', 'أبو هاشم', 'أبو طالب', 'أبو المطلب'], 'هو أبو القاسم محمد بن عبد الله بن عبد المطلب بن هاشم...');
M(2, 25, 'النبي ﷺ هو محمد بن عبد الله بن عبد المطلب بن:', ['هاشم', 'نوفل', 'عبد شمس', 'ليس مما سبق'], 'هو أبو القاسم محمد بن عبد الله بن عبد المطلب بن هاشم بن عبد مناف بن قصي.');
M(2, 25, 'من أجداد النبي ﷺ: نزار بن معدّ بن:', ['عدنان', 'قحطان', 'كنانة', 'ليس مما سبق'], 'نسبه ﷺ: ... بن مضر بن نزار بن معد بن عدنان.');
M(2, 25, 'آمنة بنت وهب أم النبي ﷺ من بني:', ['ليس مما سبق', 'هاشم', 'أمية', 'مخزوم'], 'أمه آمنة بنت وهب بن عبد مناف بن زهرة بن كلاب بن مرة.');
M(2, 25, 'كلاب بن مرة هو الجد …… للنبي ﷺ من جهة أبيه:', ['الخامس', 'الرابع', 'السادس', 'ليس مما سبق'], 'يلتقي نسبه ﷺ من جهة أبيه ومن جهة أمه في كلاب بن مرة، وهو الجد الخامس من جهة أبيه، والرابع من جهة أمه.');
M(2, 25, 'أخبر رسول الله ﷺ أنه من «أشرف ولد آدم حسباً، و……»:', ['أفضلهم نسباً', 'أكثرهم عدداً', 'أعزهم داراً', 'ليس مما سبق'], 'أخبر رسول الله ﷺ أنه من «أشرف ولد آدم حسباً، وأفضلهم نسباً».');
M(2, 25, 'راوي حديث: «إن الله اصطفى كنانة من ولد إسماعيل...»:', ['واثلة بن الأسقع', 'أنس بن مالك', 'سلمة بن سلامة', 'ليس مما سبق'], 'عن واثلة بن الأسقع قال: سمعت رسول الله ﷺ يقول: (إن الله اصطفى كنانة من ولد إسماعيل...).');
M(2, 26, 'يدل قوله ﷺ: «خرجت من نكاح، ولم أخرج من سفاح...» على:', ['طهارة نسبه ﷺ', 'أنه ﷺ وُلد بجوف مكة', 'أنه ﷺ نشأ يتيماً', 'ليس مما سبق'], 'لم يزل ﷺ يتنقل من أصلاب الآباء الطيبين إلى أرحام الأمهات الطاهرات، لم يمسّ نسبه من سفاح الجاهلية شيء.');

// ثانياً: ولادته ﷺ
M(2, 26, 'المشهور في تاريخ يوم ولادته ﷺ أنه:', ['الثاني عشر من ربيع الأول', 'الأول من ربيع الأول', 'العشرون من ربيع الأول', 'ليس مما سبق'], 'المشهور أنه ولد في الثاني عشر من ربيع الأول، وقيل: صبيحة يوم الاثنين تاسع ربيع الأول.');
M(2, 26, 'عام ولادته ﷺ على الصحيح الذي عليه الأكثرون:', ['عام الفيل', 'قبل عام الفيل بعشر سنين', 'بعد عام الفيل بعشرين سنة', 'ليس مما سبق'], 'أما عام ولادته فالأكثرون أنه عام الفيل، وهو الصحيح؛ لما روى ابن عباس رضي الله عنهما: «ولد النبي ﷺ عام الفيل».');
M(2, 27, 'لما كان يوم السابع من ولادة رسول الله ﷺ:', ['ذبح عنه جده ودعا له قريشاً', 'خرج به جده في تجارة إلى الشام', 'حملته أمه إلى أخواله بالمدينة', 'ليس مما سبق'], 'روى البيهقي عن أبي الحكم التنوخي أنه لما كان يوم السابع من ولادة رسول الله ﷺ ذبح عنه جده، ودعا له قريشاً.');
M(2, 27, 'سمّى عبد المطلب حفيده محمداً؛ لأنه:', ['أراد أن يحمده الله في السماء وخلقه في الأرض', 'أراد أن يسميه باسم أحد آبائه', 'كان اسماً شائعاً عند العرب', 'ليس مما سبق'], 'قالوا: فلم رغبت به عن أسماء أهل بيته؟ قال: أردت أن يحمده الله تعالى في السماء، وخلقه في الأرض. ولم يكن هذا الاسم شائعاً عند العرب.');

// ثالثاً: رضاعه ﷺ
M(2, 27, 'أرضعت ثويبة النبيَّ ﷺ بلبن ابن لها يقال له:', ['ليس مما سبق', 'سعيد', 'عمرو', 'زيد'], 'أول من أرضعه ﷺ بعد أمه ثويبة مولاة أبي لهب بلبن ابن لها يقال له: مسروح.');
M(2, 28, 'التمس عبد المطلب لحفيده مرضعاً من البادية، فجاءت نسوة من …… يطلبن أطفالاً يرضعنهم، ومن بينهن حليمة:', ['بني سعد بن بكر', 'بني كنانة', 'خزاعة', 'ليس مما سبق'], 'جاءت نسوة من بني سعد بن بكر يطلبن أطفالاً يرضعنهم، ومن بينهن حليمة السعدية.');
M(2, 28, 'كانت المرضعات يأبين أخذ النبي ﷺ إذا قيل لهن:', ['إنه يتيم', 'إنه كثير البكاء', 'إنه ضعيف البنية', 'ليس مما سبق'], 'قالت حليمة: فما منا امرأة إلا وقد عرض عليها رسول الله ﷺ فتأباه، إذا قيل لها: إنه يتيم؛ لأنا كنا نرجو المعروف من أبي الصبي.');
M(2, 28, 'وصفت حليمة السعدية حالها قبل أن تأخذ النبي ﷺ بأنها:', ['جميع ما ذكر', 'خرجت في سنة شهباء لم تُبقِ لهم شيئاً', 'معها شارف لا تبضّ بقطرة', 'لا تنام ليلها من بكاء صبيها من الجوع'], 'قالت حليمة: «في سنة شهباء، لم تبق لنا شيئاً... معنا شارف لنا، والله ما تبضّ بقطرة، وما ننام ليلنا أجمع من صبينا الذي معنا، من بكائه من الجوع».');
M(2, 28, 'من البركات التي رأتها حليمة بعد أن أخذت النبي ﷺ:', ['جميع ما ذكر', 'أقبل عليه ثدياها بما شاء من لبن', 'حلب زوجها من شارفهم فإذا هي حافل', 'قطعت أتانها بالركب حتى ما يقدر عليها شيء من حمرهم'], 'لما وضعته في حجرها أقبل عليه ثدياها بما شاء من لبن، وقام زوجها إلى شارفهم فإذا إنها لحافل، وقطعت أتانها بالركب.');
M(2, 29, 'كانت صواحب حليمة يقلن لها: «يا ابنة ……، ويحك اربعي علينا»:', ['ليس مما سبق', 'أبي طالب', 'أبي بكر', 'أبي سفيان'], 'قالت حليمة: حتى إن صواحبي ليقلن لي: يا ابنة أبي ذؤيب، ويحك اربعي علينا.');

// رابعاً: حادثة شق صدره ﷺ
M(2, 29, 'أتى جبريل رسولَ الله ﷺ فشق عن قلبه وهو:', ['يلعب مع الغلمان', 'نائم في حجر مرضعته', 'في مكة عند جده', 'ليس مما سبق'], 'عن أنس بن مالك رضي الله عنه أن رسول الله ﷺ أتاه جبريل، وهو يلعب مع الغلمان، فأخذه فصرعه، فشق عن قلبه.');
M(2, 30, 'استخرج جبريل من قلب النبي ﷺ علقة، وقال:', ['هذا حظ الشيطان منك', 'هذا أثر الجاهلية فيك', 'هذا خاتم النبوة', 'ليس مما سبق'], 'فاستخرج منه علقة، فقال: هذا حظ الشيطان منك.');
M(2, 30, 'غسل جبريل قلب النبي ﷺ في طست من ذهب بماء:', ['زمزم', 'المطر', 'البحر', 'ليس مما سبق'], 'ثم غسله في طست من ذهب بماء زمزم، ثم لأمه، ثم أعاده في مكانه.');
M(2, 30, 'قال أنس بن مالك رضي الله عنه: «وقد كنت أرى أثر ذلك …… في صدره»:', ['المخيط', 'الطست', 'الكيّ', 'ليس مما سبق'], 'قال أنس: وقد كنت أرى أثر ذلك المخيط في صدره.');
M(2, 30, 'التطهير الذي حدث للنبي ﷺ في حادثة شق الصدر هو:', ['إرهاص مبكر للنبوة وإعداد للعصمة', 'علاج لمرض أصابه ﷺ في البادية', 'تكريم لمرضعته حليمة السعدية', 'ليس مما سبق'], 'لا شك في أن التطهير من حظ الشيطان هو إرهاص مبكر للنبوة، وإعداد للعصمة من الشر وعبادة غير الله.');

// الدروس المستفادة
M(2, 30, 'هيأ الله النفوس لاستقبال بعثة الرسول ﷺ بالآيات العظيمة والبشارات؛ لأن:', ['الأمر المتوقع إذا وقع سهل تقبله', 'العرب كانوا ينتظرون ملكاً منهم', 'أهل الكتاب كانوا يطلبون ذلك', 'ليس مما سبق'], 'هيأ الله النفوس لاستقبال بعثته ﷺ حتى يتطلع الناس إلى ظهوره، ولأن الأمر المتوقع إذا وقع سهل تقبله، وإذا جاء الشيء على غير توقع استنكرته النفوس.');
M(2, 31, 'الإيمان بالأنبياء السابقين يستلزم الإيمان بنبوة خاتم النبيين ﷺ؛ لأن:', ['نبوته ﷺ مقررة في التوراة والإنجيل', 'الأنبياء السابقين أدركوا زمانه', 'أهل الكتاب أسلموا جميعاً', 'ليس مما سبق'], 'الإيمان بالأنبياء السابقين يستلزم الإيمان بنبوة خاتم النبيين ﷺ؛ لأن نبوته مقررة في التوراة والإنجيل، وفي ذلك إقامة للحجة على أهل الكتاب.');
M(2, 31, 'كان من أسباب ضعف العرب أمام أبرهة وجنوده واستسلامهم:', ['تفرقهم وتشتتهم وعداواتهم القبلية', 'قلة أموالهم', 'انشغالهم بالتجارة', 'ليس مما سبق'], 'الفرقة والتنازع سبب للفشل والجبن والضعف، فتفرق العرب وتشتتهم وعداواتهم القبلية كانت سبباً في ضعفهم أمام أبرهة وجنوده، واستسلامهم.');
M(2, 31, 'كان العرب في الجاهلية يسترضعون أطفالهم في البادية:', ['حتى ينشؤوا على اللغة السليمة واللسان الفصيح', 'تخلّصاً من نفقة الرضاعة', 'لكثرة المراضع في البادية', 'ليس مما سبق'], 'من الدروس: عناية العرب باللغة العربية في الجاهلية؛ فقد كانوا يسترضعون أطفالهم في البادية؛ حتى ينشؤوا على اللغة السليمة واللسان الفصيح.');

/* ═══════════════ u03 ═══════════════ */
// نشأته ﷺ يتيمًا
M(3, 35, 'خرج عبد الله بن عبد المطلب والد النبي ﷺ من مكة في تجارة قاصدًا:', ['الشام', 'اليمن', 'الحبشة', 'ليس مما سبق'], 'خرج من مكة قاصدًا الشام في تجارة، فلما قفل منها نزل بالمدينة وهو مريض فتوفي بها.');
M(3, 35, 'لما بلغ النبي ﷺ ست سنين قدمت به أمه إلى يثرب تُزيره أخواله من:', ['بني عدي بن النجار', 'بني عبد مناف', 'بني سعد', 'ليس مما سبق'], 'قدمت به أمه على أخواله من بني عدي بن النجار بمدينة يثرب تُزيره إياهم.');
M(3, 35, 'اسم المكان الذي أدرك فيه الموتُ آمنةَ بنت وهب أم النبي ﷺ وهي عائدة إلى مكة:', ['ليس مما سبق', 'يثرب', 'وادي نخلة', 'الطائف'], 'أدركها الموت بمكان بين مكة والمدينة اسمه: الأبواء.');
M(3, 35, 'بعد وفاة آمنة بنت وهب عادت بالنبي ﷺ إلى مكة وسلّمته إلى جده عبد المطلب:', ['أم أيمن', 'حليمة السعدية', 'خديجة بنت خويلد', 'ليس مما سبق'], 'بعد وفاة أمه ﷺ عادت أم أيمن به إلى مكة، وسلّمته إلى جده عبد المطلب.');
M(3, 35, 'كان عبد المطلب حفيًّا بحفيده ﷺ، يقربه منه ويدنيه، ويُجلسه على فراشه في:', ['ظل الكعبة', 'دار الندوة', 'بيت أبي طالب', 'ليس مما سبق'], 'كان به حفيًّا، يقربه منه ويدنيه، ويجلسه على فراشه في ظل الكعبة، ويلاطفه.');
M(3, 35, 'مات عبد المطلب جد النبي ﷺ وعمر النبي ﷺ:', ['ليس مما سبق', 'ست سنين', 'عشر سنين', 'اثنتا عشرة سنة'], 'لم تدم كفالته طويلًا؛ فما إن بلغ ﷺ ثماني سنين حتى مات جده عبد المطلب.');
M(3, 35, 'كان أبو طالب شديد العطف على النبي ﷺ يحيطه بكل صنوف الرعاية مع:', ['قلة ماله وكثرة عياله', 'كثرة ماله وقلة عياله', 'كثرة ماله وكثرة عياله', 'ليس مما سبق'], 'كفله عمه أبو طالب شقيق والده، وكان شديد العطف عليه مع قلة ماله وكثرة عياله.');
M(3, 36, 'دافع أبو طالب عن النبي ﷺ بعد مبعثه بيده ولسانه، وكان مع ذلك:', ['مستمرًا على شركه إلى أن مات', 'قد أسلم سرًّا قبل موته', 'قد أسلم بعد حصار الشعب', 'ليس مما سبق'], 'ظل يدافع عنه بعد مبعثه بيده ولسانه، مع أنه كان مستمرًا على شركه إلى أن مات.');

// عمله ﷺ بالرعي والتجارة — أولاً: عمله ﷺ بالرعي
M(3, 36, 'رعى النبي ﷺ الغنم في طفولته في بادية بني سعد مع:', ['إخوته من الرضاعة', 'أعمامه', 'أبناء عمه أبي طالب', 'ليس مما سبق'], 'رعى النبي ﷺ الغنم في طفولته في بادية بني سعد مع إخوته من الرضاعة.');
M(3, 36, 'عمل النبي ﷺ في رعي الأغنام لأهل مكة وهو في كنف عمه؛ رغبةً منه في:', ['مساعدة عمه أبي طالب', 'جمع المال للزواج', 'الابتعاد عن مجالس قريش', 'ليس مما سبق'], 'لما رأى قلة مال عمه أبي طالب وكثرة أولاده رغب في مساعدته، فعمل في رعي الأغنام لأهل مكة.');
M(3, 36, 'كان النبي ﷺ يرعى الغنم لأهل مكة مقابل:', ['قراريط', 'دنانير', 'نصيب من الغنم', 'ليس مما سبق'], 'قال ﷺ: (كنت أرعاها على قراريط لأهل مكة)، والقيراط جزء يسير من الدينار أو الدرهم.');
M(3, 36, 'قال النبي ﷺ: (ما بعث الله نبيًّا إلا ......):', ['رعى الغنم', 'عمل بالتجارة', 'عمل بالزراعة', 'ليس مما سبق'], 'قال ﷺ: (ما بعث الله نبيًّا إلا رعى الغنم)، فقال أصحابه: وأنت؟ فقال: (نعم...).');
M(3, 36, 'من الحكمة في اشتغال الأنبياء برعي الغنم أنهم إذا خالطوا الغنم زادهم:', ['حلمًا وشفقة', 'مالًا وجاهًا', 'قوة وشجاعة', 'ليس مما سبق'], 'الحكمة من اشتغال الأنبياء برعي الغنم خاصة أنهم إذا خالطوا الغنم زادهم حلمًا وشفقة.');
M(3, 36, 'من الأمور التي يتعودها الأنبياء في رعي الغنم فتعينهم على مخالطة الناس ودعوتهم:', ['جميع ما ذكر', 'الصبر على مشقة رعيها', 'معرفة اختلاف طباعها', 'الصبر على جمعها مع تفرقها في المرعى'], 'إذا صبروا على مشقة رعيها، وعلموا اختلاف طباعها، وصبروا على جمعها مع تفرقها في المرعى والمشرب... عرفوا مخالطة الناس.');

// ثانياً: عمله ﷺ بالتجارة
M(3, 37, 'ظهرت في شراكة النبي ﷺ مع السائب بن أبي السائب:', ['جميع ما ذكر', 'أمانته ﷺ', 'سماحته ﷺ', 'حسن تعامله ﷺ'], 'أقام شراكة مالية مع السائب بن أبي السائب، وظهرت فيه أمانته ﷺ وسماحته وحسن تعامله.');
M(3, 37, 'شهد السائب بن أبي السائب للنبي ﷺ بأنه كان خير شريك حين قدم عليه:', ['يوم الفتح', 'يوم الحديبية', 'في غزوة بدر', 'ليس مما سبق'], 'شهد له بذلك شريكه السائب حين قدم على النبي ﷺ يوم الفتح، فقال: «كنت شريكي في الجاهلية فكنت خير شريك...».');
M(3, 37, 'لما قدم النبي ﷺ من الشام بتجارة خديجة رضي الله عنها كان قد ربح:', ['ليس مما سبق', 'مثل ما كانت تربح', 'نصف ما كانت تربح', 'ثلاثة أضعاف ما كانت تربح'], 'فلما قدم رسول الله ﷺ بتجارتها كان قد ربح ضعف ما كانت تربح.');
M(3, 38, 'كانت خديجة رضي الله عنها يوم رغبت في الزواج من النبي ﷺ:', ['أرملة', 'لم يسبق لها الزواج', 'مطلقة', 'ليس مما سبق'], 'رغبت خديجة رضي الله عنها في الزواج منه ﷺ، وكانت يومئذ أرملة.');
M(3, 38, 'كان عمر خديجة رضي الله عنها حين تزوجها النبي ﷺ على المشهور:', ['أربعين سنة', 'خمسًا وعشرين سنة', 'خمسًا وثلاثين سنة', 'ليس مما سبق'], 'كانت يومئذ أرملة، بنت أربعين سنة على المشهور، وقيل غير ذلك.');
M(3, 38, 'لما وافق النبي ﷺ على طلب خديجة رضي الله عنها بعث إلى وليها خاطبًا:', ['أعمامه', 'مولاه زيد بن حارثة', 'شريكه السائب بن أبي السائب', 'ليس مما سبق'], 'فوافق النبي ﷺ على طلبها، وبعث بأعمامه إلى وليها خاطبًا.');
M(3, 38, 'كان عمر النبي ﷺ حين تزوج خديجة رضي الله عنها:', ['خمسًا وعشرين سنة', 'أربعين سنة', 'ثلاثين سنة', 'ليس مما سبق'], 'وكان عمره إذ ذاك خمسًا وعشرين سنة.');
M(3, 38, 'كانت خديجة رضي الله عنها أفضل نساء قومها:', ['نسبًا وثروة وعقلًا', 'جمالًا وصغر سن', 'علمًا بالشعر والأدب', 'ليس مما سبق'], 'كانت خديجة رضي الله عنها أفضل نساء قومها نسبًا وثروة وعقلًا.');
M(3, 38, 'كل أولاد النبي ﷺ من خديجة رضي الله عنها سوى:', ['إبراهيم', 'القاسم', 'فاطمة', 'ليس مما سبق'], 'وكل أولاده منها سوى إبراهيم.');

// مشاركته ﷺ في بعض الأحداث والوقائع — أولاً: حرب الفجار
M(3, 38, 'كانت حرب الفجار بين قريش ومعهم كنانة وبين:', ['قيس عيلان', 'الأوس والخزرج', 'بني تميم', 'ليس مما سبق'], 'كانت هذه الحرب بين قريش ومعهم كنانة وبين قيس عيلان.');
M(3, 38, 'كان عمر النبي ﷺ في حرب الفجار على المشهور:', ['ليس مما سبق', 'اثني عشر عامًا', 'عشرين عامًا', 'خمسة وعشرين عامًا'], 'كان عمر الرسول ﷺ خمسة عشر عامًا على المشهور.');
M(3, 39, 'كانت مشاركة النبي ﷺ في حرب الفجار بأنه:', ['كان يرد عن أعمامه نبل عدوهم', 'تقدم للقتال في الصفوف الأولى', 'كان يسقي المقاتلين ويداويهم', 'ليس مما سبق'], 'قال ﷺ: (كنت أنبل عن أعمامي)، أي: أرد عنهم نبل عدوهم، فلم يقدم للقتال بل كان درعًا واقية لأعمامه.');

// ثانياً: حلف الفضول
M(3, 39, 'كان سبب حلف الفضول أن رجلًا قدم مكة ببضاعة فظُلم، وكان هذا الرجل من:', ['زبيد', 'ثقيف', 'خزاعة', 'ليس مما سبق'], 'كان سبب حلف الفضول أن رجلًا من زبيد قدم مكة ببضاعة، فاشتراها منه أحد أشراف قريش، فحبس عنه ثمنها.');
M(3, 39, 'اشترى بضاعة الزبيدي وحبس عنه ثمنها:', ['العاص بن وائل', 'أبو جهل', 'الوليد بن المغيرة', 'ليس مما سبق'], 'اشتراها منه العاص بن وائل أحد أشراف قريش، فحبس عنه ثمنها.');
M(3, 39, 'صعد الزبيدي يستغيث بقريش عند طلوع الشمس على جبل:', ['ليس مما سبق', 'الصفا', 'حراء', 'ثور'], 'رقى الزبيدي على جبل أبي قبيس عند طلوع الشمس، وقريش في أنديتهم حول الكعبة.');
M(3, 39, 'نهض داعيًا إلى نجدة الزبيدي بعد أن استنهض شعرُه أهلَ مكة:', ['الزبير بن عبد المطلب', 'أبو طالب بن عبد المطلب', 'عبد الله بن جدعان', 'ليس مما سبق'], 'فنهض الزبير بن عبد المطلب داعيًا إلى نجدة الزبيدي.');
M(3, 40, 'سمّت قريش الحلف «حلف الفضول»؛ لأنهم قالوا:', ['دخل هؤلاء في فضل من الأمر', 'عقدوه لرد فضول الأموال', 'حضره فضلاء العرب جميعًا', 'ليس مما سبق'], 'قالوا: لقد دخل هؤلاء في فضل من الأمر، أي: قاموا بعمل فاضل.');
M(3, 40, 'قال النبي ﷺ عن حلف الفضول: (لقد شهدت في دار عبد الله بن جدعان حلفًا ما أحب أن لي به ......):', ['حمر النعم', 'الدنيا وما فيها', 'ملء الأرض ذهبًا', 'ليس مما سبق'], 'قال ﷺ: (لقد شهدت في دار عبد الله بن جدعان حلفًا ما أحب أن لي به حمر النعم، ولو أُدعى به في الإسلام لأجبت).');

// ثالثاً: تجديد بناء الكعبة المشرفة
M(3, 40, 'اجتمعت قريش لتجديد بناء الكعبة لما أصابها من:', ['سيل جارف صدّع جدرانها', 'زلزال هدم جدرانها', 'هجوم أبرهة عليها', 'ليس مما سبق'], 'اجتمعت قريش لتجديد بنائها لما أصابها من سيل جارف صدّع جدرانها بعد توهينها من حريق كان أصابها.');
M(3, 40, 'كانت الكعبة قبل تجديد قريش لبنائها قصيرة البناء ولم يكن لها سقف، فكانت:', ['عرضة لانتهاب نفائسها', 'لا تتسع لأصنام العرب', 'لا يراها القادم إلى مكة', 'ليس مما سبق'], 'أرادت قريش هدمها؛ ليعيدوا بناءها ويرفعوها ويسقفوها؛ لأنها كانت قصيرة البناء فوق القامة، ولم يكن لها سقف، فكانت عرضة لانتهاب نفائسها.');
M(3, 40, 'اتفقت قريش ألا يدخل في بناء الكعبة إلا الطيب من أموالهم، فلا يدخل فيها مال من:', ['جميع ما ذكر', 'ربا', 'مهر بغي', 'مظلمة'], 'اتفقوا على ألا يدخل في بنائها إلا الطيب من أموالهم، ولا يدخل فيها مال من ربا أو مهر بغي أو مظلمة.');
M(3, 40, 'الجزء الذي أخرجته قريش من الكعبة لما قصرت بها النفقة الطيبة يسمى:', ['الحجر والحطيم', 'الملتزم', 'مقام إبراهيم', 'ليس مما سبق'], 'أخرجوا من الجهة الشمالية نحوًا من ستة أذرع، وهي التي تسمى بالحجر والحطيم.');
M(3, 40, 'جعلت قريش للكعبة بابًا واحدًا ورفعته من الأرض؛ وذلك:', ['لئلا يدخلها إلا من أرادوا', 'لحمايتها من السيول', 'لتكون أعلى من بيوت مكة', 'ليس مما سبق'], 'جعلوا لها بابًا واحدًا، ورفعوه من الأرض؛ لئلا يدخلها إلا من أرادوا.');
M(3, 40, 'سقفت قريش الكعبة حين جددت بناءها على:', ['ليس مما سبق', 'أربعة أعمدة', 'ثمانية أعمدة', 'ثلاثة أعمدة'], 'وسقفوها على ستة أعمدة.');
M(3, 41, 'لما اختصمت قريش في وضع الحجر الأسود وكادت تنشب بينهم حرب اتفقوا على أن يحكّموا:', ['أول داخل عليهم من باب المسجد', 'أكبرهم سنًّا من أشرافهم', 'سيدًا من سادات بني هاشم', 'ليس مما سبق'], 'اتفقوا على أن يحكّموا أول داخل عليهم من باب المسجد، فكان ﷺ هو أول داخل.');

// حفظ الله تعالى لنبيه ﷺ قبل البعثة
M(3, 41, 'عصم الله نبيه ﷺ قبل البعثة من أقذار الجاهلية وعاداتها، حتى عصمه من:', ['مجالس اللهو التي يقصدها الفتيان', 'العمل بالتجارة في شبابه', 'رعي الغنم في بادية بني سعد', 'ليس مما سبق'], 'عاش بعيدًا عن أقذار الجاهلية وعاداتها، عصمه الله حتى من مجالس اللهو التي يقصدها الفتيان.');
M(3, 42, 'كان النبي ﷺ قبل البعثة مستمسكًا بإرث أبويه إبراهيم وإسماعيل عليهما السلام، فكان في الحج يقف مع الناس:', ['بعرفات', 'بالمزدلفة', 'بمنى', 'ليس مما سبق'], 'كان يقف مع الناس بعرفات، ولا يصنع ما تصنع قريش من وقوفها بالمزدلفة.');
M(3, 42, 'كان يُطلق على قريش ومن دان دينها في الجاهلية اسم:', ['الحُمْس', 'الأحابيش', 'الأحلاف', 'ليس مما سبق'], 'قالت عائشة رضي الله عنها: (كانت قريش ومن دان دينها ... وكانوا يسمون الحُمْس).');
M(3, 42, 'كان النبي ﷺ أفضل قومه مروءة وأحسنهم خلقًا وأشدهم حياء، حتى ما عُرف في قومه إلا بـ:', ['الأمين', 'الحكيم', 'الشجاع', 'ليس مما سبق'], 'كان أصدقهم حديثًا وأعظمهم أمانة، حتى ما عرف في قومه إلا بالأمين.');
M(3, 42, 'من الصفات التي وصفت بها خديجة رضي الله عنها النبيَّ ﷺ:', ['جميع ما ذكر', 'أنه يصل الرحم', 'أنه يقري الضيف', 'أنه يعين على نوائب الحق'], 'قالت: «إنك لتصل الرحم، وتصدق الحديث، وتحمل الكل، وتكسب المعدوم، وتقري الضيف، وتعين على نوائب الحق».');

// الدروس المستفادة
M(3, 43, 'اشتغال الأنبياء عليهم السلام برعي الغنم يدل على أن المؤمن:', ['يعمل بجهده ولا يأنف من عمل مباح', 'يتفرغ للعبادة ويترك العمل', 'يعتمد على ما في أيدي الناس', 'ليس مما سبق'], 'المؤمن يعمل بجهده ويكسب بيده... ولا يأنف من عمل مباح، فالأنبياء عليهم السلام اشتغلوا برعي الغنم.');
M(3, 43, 'استُدل على أن الداعية ينبغي أن يستعفّ عما في أيدي الناس بقوله تعالى:', ['﴿قُل لَّا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا﴾', '﴿وَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ﴾', '﴿فَاصْدَعْ بِمَا تُؤْمَرُ﴾', 'ليس مما سبق'], 'ينبغي للداعية أن يستعف عما في أيدي الناس، ولذلك أمر الله رسوله ﷺ أن يقول: ﴿قل لا أسألكم عليه أجرًا إن هو إلا ذكرى للعالمين﴾ (الأنعام: 90).');
M(3, 43, 'من الدروس المستفادة من زواج النبي ﷺ بخديجة رضي الله عنها أن:', ['الدين والخلق أساسا اختيار الزوجين', 'المال أساس اختيار الزوجة', 'الأفضل الزواج ممن تقاربه في السن', 'ليس مما سبق'], 'الدين والخلق أساسا اختيار أحد الزوجين لصاحبه، فقد تزوج ﷺ من أرملة تكبره في السن لكنها اتصفت بالعفة والشرف.');
M(3, 43, 'عُرفت خديجة رضي الله عنها بين قومها بـ:', ['الطاهرة', 'ذات النطاقين', 'أم المساكين', 'ليس مما سبق'], 'اتصفت بالعفة والشرف، وعرفت بين قومها بالطاهرة.');
M(3, 44, 'مشاركة النبي ﷺ في حلف الفضول تدل على أن المسلم:', ['مطالب بالوقوف مع من أراد إقامة العدل', 'لا يشارك في أي عمل قبل الإسلام', 'يقتصر على نصرة قومه وعشيرته', 'ليس مما سبق'], 'المسلم مطالب بالوقوف مع كل من أراد إقامة العدل ونصرة الحق ودفع الظلم، فقد شارك النبي ﷺ في حلف الفضول.');
M(3, 44, 'امتناع العرب في الجاهلية من إدخال الأموال الخبيثة في بناء البيت الحرام يدل على أن:', ['الإنسان بفطرته السليمة يدرك حرمتها', 'العرب كانوا يعرفون أحكام الشريعة', 'قريشًا كانت أغنى قبائل العرب', 'ليس مما سبق'], 'الإنسان بفطرته السليمة يدرك حرمة الربا والأموال المأخوذة ظلمًا والمكاسب الخبيثة؛ ومن أجل ذلك امتنع العرب في الجاهلية من إدخالها في بناء البيت الحرام.');

/* ═══════════════ u04 ═══════════════ */
// نزول الوحي ومراحل الدعوة — أولاً: نزول الوحي
M(4, 47, 'أول ما بُدئ به رسول الله ﷺ من الوحي:', ['الرؤيا الصادقة في النوم', 'مجيء جبريل عليه السلام في غار حراء', 'سماع صوت مثل صلصلة الجرس', 'ليس مما سبق'], 'قالت عائشة رضي الله عنها: «أول ما بُدئ به رسول الله ﷺ من الوحي الرؤيا الصادقة في النوم».');
M(4, 47, 'جاء جبريل عليه السلام إلى النبي ﷺ بالوحي لما بلغ سن الكمال، وهي:', ['أربعون سنة', 'خمس وثلاثون سنة', 'ثلاثون سنة', 'ليس مما سبق'], 'لما بلغ ﷺ سن الكمال – وهي أربعون سنة – جاءه جبريل عليه السلام.');
M(4, 47, 'كان النبي ﷺ حين جاءه جبريل عليه السلام بالوحي أول مرة في:', ['غار حراء', 'غار ثور', 'جبل الصفا', 'ليس مما سبق'], 'جاءه جبريل عليه السلام وهو في غار حراء.');
M(4, 47, 'نزل جبريل عليه السلام بالوحي على النبي ﷺ أول مرة في يوم:', ['ليس مما سبق', 'الجمعة', 'الخميس', 'الأحد'], 'جاءه جبريل عليه السلام وهو في غار حراء في يوم الاثنين من شهر رمضان المبارك.');
M(4, 47, 'كان أول نزول الوحي على النبي ﷺ في شهر:', ['رمضان', 'رجب', 'ربيع الأول', 'ليس مما سبق'], 'جاءه جبريل عليه السلام وهو في غار حراء في يوم الاثنين من شهر رمضان المبارك.');
M(4, 47, 'غطّ جبريل عليه السلام النبيَّ ﷺ في غار حراء قبل أن يقرأ عليه أول ما نزل:', ['ثلاث مرات', 'مرة واحدة', 'مرتين', 'ليس مما سبق'], 'قال ﷺ: (فأخذني فغطني... فأخذني فغطني الثانية... فأخذني فغطني الثالثة، ثم أرسلني، فقال: اقرأ باسم ربك...).');
M(4, 48, 'أول ما نزل من القرآن على النبي ﷺ قوله تعالى:', ['﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾', '﴿قُلْ يَا أَيُّهَا الْكَافِرُونَ﴾', '﴿فَاصْدَعْ بِمَا تُؤْمَرُ﴾', 'ليس مما سبق'], 'بعد الغطة الثالثة قال جبريل: ﴿اقرأ باسم ربك الذي خلق ۝ خلق الإنسان من علق ۝ اقرأ وربك الأكرم﴾ (العلق: 1–3).');
M(4, 48, 'لما أخبر النبي ﷺ خديجة رضي الله عنها الخبر وقال: (لقد خشيت على نفسي) قالت له:', ['كلا، والله ما يخزيك الله أبدا', 'اذهب إلى عمك أبي طالب فأخبره', 'اكتم أمرك ولا تخبر به أحدًا', 'ليس مما سبق'], 'قالت خديجة رضي الله عنها: كلا، والله ما يخزيك الله أبدا، إنك لتصل الرحم...');
M(4, 48, 'انطلقت خديجة رضي الله عنها بالنبي ﷺ إلى ورقة بن نوفل، وكان ورقة:', ['ابن عمها', 'أخاها', 'عمها', 'ليس مما سبق'], 'انطلقت به حتى أتت به ورقة بن نوفل ابن عم خديجة رضي الله عنها.');
M(4, 48, 'كان ورقة بن نوفل امرأً تنصّر في الجاهلية، وكان يكتب من الإنجيل باللغة:', ['العبرانية', 'اليونانية', 'الفارسية', 'ليس مما سبق'], 'كان امرأ تنصر في الجاهلية، وكان يكتب من الإنجيل بالعبرانية ما شاء الله أن يكتب.');
M(4, 48, 'قال ورقة بن نوفل للنبي ﷺ: «ليتني أكون حيًّا إذ ......»:', ['يخرجك قومك', 'ينزل عليك القرآن', 'تهاجر إلى المدينة', 'ليس مما سبق'], 'قال ورقة: هذا الناموس الذي نزّل الله على موسى، ليتني أكون حيًّا إذ يخرجك قومك.');

// ثانياً: الدعوة السرية
M(4, 49, 'كان من الحكمة أن يدعو النبي ﷺ في أول الأمر سرًّا؛ وذلك:', ['لئلا يفاجئ أهل مكة بما يهيجهم', 'لأنه لم يكن قد أُمر بالدعوة', 'لأن أهل مكة كانوا في غفلة', 'ليس مما سبق'], 'دعا سرًّا لئلا يفاجئ أهل مكة بما يهيجهم وينافي معتقداتهم فيقفون عقبة في طريق الدعوة، فكتم أمره حتى تتكون مجموعة تنتصر للدعوة.');
M(4, 49, 'أول الناس إيمانًا بالله وبرسوله ﷺ:', ['خديجة رضي الله عنها', 'أبو بكر الصديق رضي الله عنه', 'علي بن أبي طالب رضي الله عنه', 'ليس مما سبق'], 'فكانت خديجة رضي الله عنها أول الناس إيمانًا بالله وبرسوله.');
M(4, 49, 'لما آمنت خديجة رضي الله عنها وقفت بجوار النبي ﷺ:', ['جميع ما سبق', 'تؤازره', 'تواسيه', 'تخفف عنه'], 'ووقفت بجواره، تؤازره وتواسيه، وتخفف عنه.');
M(4, 49, 'أسلم علي بن أبي طالب رضي الله عنه وعمره يومئذ:', ['ليس مما سبق', 'ثماني سنين', 'اثنتا عشرة سنة', 'خمس عشرة سنة'], 'أسلم علي بن أبي طالب رضي الله عنه وهو يومئذ ابن عشر سنين، وهو أول من آمن من الصبيان.');
M(4, 49, 'أول من آمن من الموالي:', ['زيد بن حارثة رضي الله عنه', 'عمار بن ياسر رضي الله عنه', 'حمزة بن عبد المطلب رضي الله عنه', 'ليس مما سبق'], 'وأسلم زيد بن حارثة حب رسول الله ﷺ، وهو أول من آمن من الموالي.');
M(4, 49, 'أول من آمن من الرجال:', ['أبو بكر بن أبي قحافة رضي الله عنه', 'عمر بن الخطاب رضي الله عنه', 'عثمان بن عفان رضي الله عنه', 'ليس مما سبق'], 'وأسلم أبو بكر بن أبي قحافة رضي الله عنه، وهو أول من آمن من الرجال.');

// ثالثاً: الجهر بالدعوة
M(4, 49, 'قوله تعالى: ﴿فَاصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ الْمُشْرِكِينَ﴾ الذي انتهت بنزوله مرحلة الدعوة السرية من سورة:', ['الحجر', 'الشعراء', 'المدثر', 'ليس مما سبق'], 'انتهت مرحلة الدعوة السرية بنزول قوله تعالى: ﴿فاصدع بما تؤمر وأعرض عن المشركين﴾ (الحجر: 94).');
M(4, 50, 'لما قال أبو لهب للنبي ﷺ: تبًّا لك سائر اليوم، ألهذا جمعتنا؟ نزل قوله تعالى:', ['﴿تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ﴾', '﴿وَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ﴾', '﴿قُل لَّا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا﴾', 'ليس مما سبق'], 'فقال أبو لهب: تبًّا لك سائر اليوم، ألهذا جمعتنا؟ فنزلت: ﴿تبت يدا أبي لهب وتب ۝ ما أغنى عنه ماله وما كسب﴾ (المسد: 1–2).');
M(4, 50, 'قال النبي ﷺ: (لقد أُخِفت في الله وما يُخاف أحد، ولقد ...... في الله وما يؤذى أحد):', ['أوذيت', 'عذبت', 'حوربت', 'ليس مما سبق'], 'قال ﷺ: (لقد أخفت في الله وما يخاف أحد، ولقد أوذيت في الله وما يؤذى أحد).');
M(4, 51, 'مرّ النبي ﷺ بآل ياسر وهم يُعذَّبون فقال:', ['صبرًا آل ياسر؛ فإن موعدكم الجنة', 'اثبتوا آل ياسر؛ فإن الله معكم', 'اللهم اغفر لآل ياسر وارحمهم', 'ليس مما سبق'], 'فمر بهم النبي ﷺ وهم يعذبون فقال: (صبرًا آل ياسر؛ فإن موعدكم الجنة).');
M(4, 51, 'من الصحابة الذين لاقوا من صناديد قريش أنواعًا من الأذى، حتى ألبسوه أدرع الحديد وصهروه في الشمس المحرقة:', ['بلال بن رباح رضي الله عنه', 'أبو بكر الصديق رضي الله عنه', 'زيد بن حارثة رضي الله عنه', 'ليس مما سبق'], 'ومنهم بلال بن رباح رضي الله عنه، فقد لاقى من صناديد قريش أنواعًا من الأذى، حتى إنهم ألبسوه أدرع الحديد وصهروه في الشمس المحرقة.');
M(4, 51, 'بعثت قريش إلى أبي طالب وفدًا من أشرافهم:', ['ليقنعوه بالتخلي عن إسناد النبي ﷺ', 'ليدعوه إلى الدخول في الإسلام', 'ليعلنوا عليه الحرب', 'ليس مما سبق'], 'بعثوا إليه وفدًا من أشرافهم؛ ليقنعوه بالتخلي عن إسناده وحمايته.');

// المسلمون بين هجران الديار ومرارة الحصار — أولاً: الهجرة إلى الحبشة
M(4, 52, 'قال النبي ﷺ لأصحابه لما اشتد عليهم الأذى: (إن بأرض الحبشة ملكًا ......):', ['لا يُظلم أحد عنده', 'يحب المسلمين وينصرهم', 'على دين الإسلام', 'ليس مما سبق'], 'قال ﷺ: (إن بأرض الحبشة ملكًا لا يظلم أحد عنده، فالحقوا ببلاده حتى يجعل الله لكم فرجًا ومخرجًا مما أنتم فيه).');
M(4, 52, 'خرجت أول جماعة من المسلمين مهاجرة إلى الحبشة في شهر:', ['رجب', 'رمضان', 'محرم', 'ليس مما سبق'], 'فخرجت جماعة من المسلمين إلى أرض الحبشة في رجب من السنة الخامسة من البعثة.');
M(4, 52, 'كان عدد المهاجرين في الهجرة الأولى إلى الحبشة على المشهور:', ['ليس مما سبق', 'عشرة رجال وخمس نسوة', 'اثني عشر رجلًا وثلاث نسوة', 'ثلاثة عشر رجلًا وأربع نسوة'], 'وعددهم أحد عشر رجلًا، وأربع نسوة على المشهور.');
M(4, 52, 'عاد بعض المهاجرين من الحبشة إلى مكة بعد الهجرة الأولى؛ لأنه:', ['بلغهم أن قريشًا أسلمت', 'بلغهم موت النجاشي', 'أمرهم النبي ﷺ بالعودة', 'ليس مما سبق'], 'بلغهم بعد حين أن قريشًا أسلمت، فعاد منهم قوم، فلما قدموا مكة بلغهم أن الخبر كان كذبًا.');
M(4, 52, 'كان عدد المهاجرين في الهجرة الثانية إلى الحبشة:', ['ثلاثة وثمانين رجلًا وثماني عشرة امرأة', 'ثلاثة وسبعين رجلًا وثماني عشرة امرأة', 'ثمانية وثمانين رجلًا وعشر نسوة', 'ليس مما سبق'], 'وكان عدد المهاجرين في هذه المرة ثلاثة وثمانين رجلًا وثماني عشرة امرأة.');

// ثانياً: المقاطعة العامة والحصار الاقتصادي
M(4, 53, 'لما طلب أبو طالب من بني عبد مناف أن يناصروه في منع النبي ﷺ لم يجبه منهم إلا:', ['بنو المطلب', 'بنو عبد شمس', 'بنو نوفل', 'ليس مما سبق'], 'لم يجبه من بني عبد مناف إلا بنو المطلب الذين كانوا مع بني هاشم جاهلية وإسلامًا.');
M(4, 53, 'تحالفت قريش على بني هاشم وبني المطلب حتى يسلموا إليهم النبي ﷺ على أن:', ['جميع ما سبق', 'لا يناكحوهم', 'لا يبايعوهم', 'لا يكلموهم'], 'تحالفت على بني هاشم وبني المطلب أن لا يناكحوهم، ولا يبايعوهم، ولا يكلموهم حتى يسلموا إليهم النبي ﷺ ليقتلوه.');
M(4, 53, 'علّقت قريش صحيفة المقاطعة في:', ['جوف الكعبة', 'دار الندوة', 'سوق عكاظ', 'ليس مما سبق'], 'وكتبوا بذلك صحيفة، وعلقوها في جوف الكعبة.');
M(4, 53, 'كُتبت صحيفة المقاطعة في محرم سنة ...... من البعثة:', ['سبع', 'خمس', 'عشر', 'ليس مما سبق'], 'وذلك في محرم سنة سبع من البعثة.');
M(4, 53, 'مكث بنو هاشم في الحصار لا يصل إليهم شيء إلا سرًّا نحو:', ['ليس مما سبق', 'سنة واحدة', 'سنتين', 'خمس سنوات'], 'وقد مكثوا على ذلك نحو ثلاث سنوات، لا يصل إليهم شيء إلا سرًّا ممن أراد صلتهم من قريش.');
M(4, 53, 'سعى هشام بن عمرو في نقض صحيفة المقاطعة، فمشى في ذلك إلى:', ['ليس مما سبق', 'أبي لهب وجماعة من قريش', 'أبي جهل وجماعة من قريش', 'العاص بن وائل وجماعة من قريش'], 'كان القائم بذلك هشام بن عمرو، فقد مشى في ذلك إلى المطعم بن عدي وجماعة من قريش فأجابوه.');
M(4, 53, 'أرسل الله على صحيفة المقاطعة الأرضة فأكلت جميع ما فيها من جور وقطيعة وظلم إلا:', ['ذكر الله عز وجل', 'أسماء من كتبوها', 'تاريخ كتابتها', 'ليس مما سبق'], 'أرسل عليها الأرضة، فأكلت جميع ما فيها من جور وقطيعة وظلم إلا ذكر الله عز وجل.');

// عام الحزن ومحنة الطائف — أولاً: عام الحزن
M(4, 54, 'توفي أبو طالب في رجب سنة عشر من البعثة، بعد الخروج من الشعب بـ:', ['ستة أشهر', 'شهرين', 'سنة كاملة', 'ليس مما سبق'], 'وافته المنية في رجب سنة عشر من البعثة، بعد الخروج من الشعب بستة أشهر.');
M(4, 54, 'لما أتى النبي ﷺ عمه أبا طالب عند موته يدعوه للإسلام وجد عنده أبا جهل و:', ['عبد الله بن أبي أمية بن المغيرة', 'أبا سفيان بن حرب بن أمية', 'العاص بن وائل السهمي', 'ليس مما سبق'], 'فوجد عنده أبا جهل وعبد الله بن أبي أمية بن المغيرة، فقالا: أترغب عن ملة عبد المطلب؟');
M(4, 54, 'أنزل الله تعالى في أبي طالب فقال لرسوله ﷺ:', ['﴿إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ﴾', '﴿تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ﴾', '﴿فَاصْدَعْ بِمَا تُؤْمَرُ﴾', 'ليس مما سبق'], 'وأنزل الله في أبي طالب، فقال لرسول الله ﷺ: ﴿إنك لا تهدي من أحببت ولكن الله يهدي من يشاء﴾ (القصص: 56).');
M(4, 55, 'توفيت خديجة رضي الله عنها قبل مخرج النبي ﷺ إلى المدينة بـ:', ['ليس مما سبق', 'سنة واحدة', 'سنتين', 'خمس سنين'], '«فتوفيت خديجة رضي الله عنها قبل مخرج النبي ﷺ إلى المدينة بثلاث سنين».');
M(4, 55, 'كانت خديجة رضي الله عنها للنبي ﷺ:', ['وزير صدق على الإسلام', 'عضدًا وحرزًا ومنعة على قومه', 'ناصرًا له بالسيف واللسان', 'ليس مما سبق'], 'كانت خديجة رضي الله عنها له وزير صدق على الإسلام، يشكو إليها فتعينه في أمره وتثبته، وكان أبو طالب عضدًا له وحرزًا ومنعة.');
M(4, 55, 'اشتهر العام العاشر من البعثة عند أهل التاريخ والسير بعام الحزن؛ وذلك:', ['لتوالي الأحزان والآلام فيه على النبي ﷺ', 'لاشتداد الحصار فيه على بني هاشم', 'لكثرة من مات فيه من الصحابة', 'ليس مما سبق'], 'اشتهر هذا العام بعام الحزن؛ لتوالي الأحزان والآلام فيه على رسول الله ﷺ وشدتها عليه.');

// ثانياً: محنة الطائف
M(4, 55, 'لما انتهى النبي ﷺ إلى الطائف عمد إلى نفر من سادتها وأشرافها، وهم من:', ['ثقيف', 'زبيد', 'كنانة', 'ليس مما سبق'], 'عمد إلى نفر من ثقيف هم يومئذ سادتها وأشرافها، فجلس إليهم ودعاهم إلى الله.');
M(4, 56, 'أقام النبي ﷺ بالطائف لا يدع أحدًا من أشرافهم إلا جاء إليه وكلمه:', ['ليس مما سبق', 'ثلاثة أيام', 'سبعة أيام', 'شهرًا كاملًا'], 'فأقام بالطائف عشرة أيام لا يدع أحدًا من أشرافهم إلا جاء إليه وكلمه.');
M(4, 56, 'لما ابتعد النبي ﷺ عن الطائف لجأ إلى حديقة مملوكة لـ:', ['عتبة وشيبة ابني ربيعة', 'أبي سفيان بن حرب', 'الوليد بن المغيرة', 'ليس مما سبق'], 'لجأ إلى حديقة مملوكة لعتبة وشيبة ابني ربيعة، فاحتمى بها وجلس في ظل شجرة من أشجارها.');
M(4, 56, 'كان عدّاس الذي حمل قطف العنب إلى النبي ﷺ:', ['نصرانيًّا من أهل نينوى', 'يهوديًّا من أهل يثرب', 'مجوسيًّا من أهل فارس', 'ليس مما سبق'], 'قال عداس: نصراني، وأنا من أهل نينوى، فقال ﷺ: (من قرية الرجل الصالح يونس بن متى؟).');
M(4, 57, 'في طريق عودة النبي ﷺ من الطائف صُرف إليه نفر من الجن فاستمعوا له وأسلموا، وكان ذلك في:', ['وادي نخلة', 'الأبواء', 'غار ثور', 'ليس مما سبق'], 'وفي الطريق نزل رسول الله ﷺ بوادي نخلة، فقام يصلي من الليل، فصرف إليه نفر من الجن فاستمعوا له وأسلموا.');
M(4, 57, 'أرسل النبي ﷺ إلى المطعم بن عدي ليجيره رجلًا من:', ['خزاعة', 'ثقيف', 'بني هاشم', 'ليس مما سبق'], 'أراد الرجوع إلى مكة، فأرسل رجلًا من خزاعة إلى المطعم بن عدي ليجيره، فأجابه.');

// الدروس المستفادة
M(4, 57, 'العلم شعار الإسلام الأول؛ لأن:', ['أول ما نزل من كتاب الله الأمر بالعلم والقراءة', 'النبي ﷺ كان يكتب ويقرأ قبل البعثة', 'أول من أسلم كانوا من أهل العلم', 'ليس مما سبق'], 'العلم شعار الإسلام الأول، فأول ما نزل من كتاب الله تعالى الأمر بالعلم والقراءة.');
M(4, 57, 'استبشار خديجة رضي الله عنها بنصرة الله لنبيه ﷺ لما عُرف به من محاسن الأخلاق يدل على أن:', ['مكارم الأخلاق سبب للسلامة من المكاره', 'الرؤيا الصادقة سبب لنصرة الأنبياء', 'المال سبب للسلامة من الأذى', 'ليس مما سبق'], 'مكارم الأخلاق سبب للسلامة من مصارع الشر والمكاره، فقد استبشرت خديجة رضي الله عنها بنصرة نبي الله لما عرف به من محاسن الأخلاق.');
M(4, 57, 'لا بد للداعية أن يتحلى بالصبر على الأذى أسوة بنبينا محمد ﷺ وسائر الأنبياء، وحتى:', ['يكسب قلوب العباد ويجعلهم مقبلين عليه', 'يأمن من أذى أعدائه في الدنيا', 'ينال الجاه والمكانة بين قومه', 'ليس مما سبق'], 'لا بد للداعية أن يتحلى بالصبر على الأذى... وحتى يكسب قلوب العباد ويجعلهم مقبلين عليه، راغبين في دعوته.');

/* ═══════════════ u05 ═══════════════ */
// الإسراء والمعراج — أولاً: الإسراء والمعراج
M(5, 61, 'كانت حادثة الإسراء والمعراج منحة ربانية للنبي ﷺ ودفعاً لما ألمّ به من أتراح وآلام؛ إذ كانت بعد:', ['جميع ما ذكر', 'فقد الناصر الحميم أبي طالب', 'فقد زوجته خديجة أم المؤمنين رضي الله عنها', 'ما ناله من سفهاء الطائف وصبيانها من أذى'], 'إذ كانت بعد فقد الناصر الحميم أبي طالب، وفقد زوجته خديجة، وبعد ما ناله من سفهاء الطائف وصبيانها من أذى وابتلاء.');
M(5, 61, 'بدأت رحلة الإسراء والمعراج بـ:', ['شق صدره ﷺ وغسله بماء زمزم', 'صلاته ﷺ بالأنبياء إماماً', 'صعوده ﷺ إلى السماء الدنيا', 'ليس مما سبق'], 'بدأت الرحلة بشق صدره ﷺ وغسله بماء زمزم وإفراغ الحكمة والإيمان في صدره؛ ليتأهب للمناجاة.');
M(5, 61, 'لما انتهى النبي ﷺ ليلة الإسراء إلى باب المسجد في بيت المقدس:', ['ربط الدابة عند الباب ودخله فصلّى فيه ركعتين', 'صعد إلى السماء الدنيا دون أن يدخله', 'ترك الدابة ودخله فصلّى فيه أربع ركعات', 'ليس مما سبق'], 'فلما انتهى إلى باب المسجد ربط الدابة عند الباب، ودخله، فصلّى فيه ركعتين، ثم أتى المعراج.');
M(5, 61, 'وُصف المعراج الذي صعد فيه النبي ﷺ إلى السماء بأنه:', ['كالسلّم ذي الدرج يرقى فيها', 'دابة يركبها مع جبريل عليه السلام', 'سحابة حملته إلى السماء', 'ليس مما سبق'], 'ثم أتى المعراج – وهو كالسُّلّم ذي الدرج يرقى فيها – فصعد فيه إلى السماء الدنيا.');
M(5, 62, 'مرّ النبي ﷺ ليلة المعراج بموسى الكليم عليه السلام في السماء:', ['ليس مما سبق', 'الثانية', 'الخامسة', 'الرابعة'], 'الصحيح: السادسة؛ حتى مرّ بموسى الكليم في السادسة، وإبراهيم الخليل في السابعة.');
M(5, 62, 'انتهى النبي ﷺ ليلة المعراج إلى مستوى يسمع فيه صريف:', ['الأقلام', 'أجنحة الملائكة', 'أبواب السماء', 'ليس مما سبق'], 'حتى انتهى إلى مستوى يسمع فيه صريف الأقلام، أي: أقلام القدَر بما هو كائن.');
M(5, 62, 'غشي سدرةَ المنتهى من أمر الله تعالى عظمة عظيمة، من:', ['فراش من ذهب وألوان متعددة', 'جراد من فضة', 'طيور خضر', 'ليس مما سبق'], 'ورأى سدرة المنتهى، وغشيها من أمر الله تعالى عظمة عظيمة، من فراش من ذهب، وألوان متعددة، وغشيتها الملائكة.');
M(5, 62, 'البيت المعمور يدخله كل يوم من الملائكة يتعبدون فيه ثم لا يعودون إليه:', ['سبعون ألفاً', 'سبعمائة ألف', 'سبعة آلاف', 'ليس مما سبق'], 'ورأى البيت المعمور، يدخله كل يوم سبعون ألفاً من الملائكة يتعبدون فيه، ثم لا يعودون إليه إلى يوم القيامة.');
M(5, 62, 'فرض الله تعالى على النبي ﷺ ليلة المعراج الصلوات أول الأمر:', ['خمسين صلاة', 'خمس صلوات', 'عشر صلوات', 'ليس مما سبق'], 'وفرض الله عليه هنالك الصلوات خمسين، فسأله التخفيف فخففها الله إلى خمس؛ رحمة منه ولطفاً بعباده.');
M(5, 62, 'رجع النبي ﷺ من بيت المقدس إلى مكة على البراق ليلة الإسراء:', ['بغلس', 'ضحى', 'عند الظهيرة', 'ليس مما سبق'], 'ثم خرج من بيت المقدس، فركب البراق، وعاد إلى مكة بغلس.');

// ثانياً: أخبار قريش بالإسراء والمعراج وتكذيبهم
M(5, 63, 'لما سألت قريش النبي ﷺ أن يصف لهم بيت المقدس – ولم يكن رآه قبل تلك الليلة –:', ['جلّاه الله له حتى عاينه فطفق يخبرهم عنه', 'اعتذر بأنه لم يتأمل صفته', 'أحالهم إلى أبي بكر رضي الله عنه ليصفه لهم', 'ليس مما سبق'], 'فجلّاه الله له حتى عاينه، فطفق يخبرهم عنه، ولا يستطيعون أن يردوا عليه شيئاً.');
M(5, 63, 'مما أخبر به النبي ﷺ قريشاً بعد الإسراء ليدلّهم على صدقه:', ['العير التي رآها لهم وأنها تصل يوم كذا', 'أسماء الأنبياء الذين صلّوا خلفه', 'عدد الملائكة الذين رآهم في السماء', 'ليس مما سبق'], 'وأخبرهم بالعير التي رآها وهي لهم وأنها تصل يوم كذا فوصلت كما قال ﷺ.');
M(5, 63, 'من الإشارات الحكيمة التي اشتملت عليها رحلة الإسراء والمعراج أن محمداً ﷺ:', ['جميع ما ذكر', 'نبي الثقلين', 'إمام المشرق والمغرب', 'وارث الأنبياء قبله وإمام الأجيال بعده'], 'فأعلنت أن محمداً ﷺ هو نبي الثقلين، وإمام المشرق والمغرب، ووارث الأنبياء قبله، وإمام الأجيال بعده.');
M(5, 63, 'قال الحافظ ابن رجب في زمن الإسراء والمعراج – وهو الأشهر –: كان قبل الهجرة بـ:', ['ليس مما سبق', 'سنة واحدة', 'سنتين', 'خمس سنين'], 'الصحيح: بثلاث سنين؛ قال الحافظ ابن رجب: كان قبل الهجرة بثلاث سنين، وهو أشهر.');

// عرض الرسول ﷺ الإسلام في المواسم — أولاً: عرض الإسلام في المواسم
M(5, 63, 'كان النبي ﷺ يعرض دينه على قبائل العرب في مواسم الحج وأسواقهم فيقول:', ['يا أيها الناس، قولوا: لا إله إلا الله تفلحوا', 'يا معشر قريش، أنقذوا أنفسكم من النار', 'يا أيها الناس، اتقوا الله وصلوا أرحامكم', 'ليس مما سبق'], 'يتلو عليهم كتاب الله، ويدعوهم إلى الإسلام، فيقول: (يا أيها الناس، قولوا: لا إله إلا الله تفلحوا).');
M(5, 64, 'كان النبي ﷺ يطلب من القبائل في المواسم:', ['النصرة والإيواء', 'المال والسلاح', 'الأمان لأصحابه في الحبشة', 'ليس مما سبق'], 'ويطلب منهم النصرة والإيواء، فيقول: (من يؤويني؟ من ينصرني، حتى أبلّغ رسالة ربي، وله الجنة؟).');
M(5, 64, 'كان يتبع النبي ﷺ في المواسم بالتناوب، يشتمانه ويؤذيانه ويحذّران الناس منه:', ['أبو لهب وأبو جهل', 'أبو جهل وأمية بن خلف', 'أبو سفيان والوليد بن المغيرة', 'ليس مما سبق'], 'وكان أبو لهب وأبو جهل يتبعانه بالتناوب، ويشتمانه ويؤذيانه، ويحذّران الناس منه.');
M(5, 64, 'كان عدد النفر من الخزرج الذين لقيهم النبي ﷺ عند العقبة أول مرة فأجابوه وصدّقوه:', ['ليس مما سبق', 'اثني عشر', 'سبعين', 'أربعين'], 'الصحيح: ستة نفر؛ فأجابوه فيما دعاهم إليه وصدّقوه، وكانوا ستة نفر.');
M(5, 64, 'كان اليهود يقولون للخزرج إذا حصل بينهم شيء: إن نبياً مبعوث الآن قد أظلّ زمانه، نتّبعه فنقتلكم معه قتل:', ['عاد وإرم', 'ثمود', 'قوم فرعون', 'ليس مما سبق'], 'قالوا لهم: إن نبياً مبعوث الآن، قد أظلّ زمانه، نتّبعه، فنقتلكم معه قتل عاد وإرم.');

// ثانياً: بيعتا العقبة
M(5, 65, 'كان الاثنا عشر رجلاً من الأنصار الذين بايعوا النبي ﷺ عند العقبة في العام المقبل:', ['عشرة من الخزرج واثنان من الأوس', 'ستة من الخزرج وستة من الأوس', 'عشرة من الأوس واثنان من الخزرج', 'ليس مما سبق'], 'قدم على النبي ﷺ اثنا عشر رجلاً من الأنصار، عشرة من الخزرج، واثنان من الأوس، فأسلموا وبايعوا.');
M(5, 65, 'من البنود التي بايع عليها الأنصار النبيَّ ﷺ في بيعة العقبة الأولى:', ['جميع ما ذكر', 'ألا يشركوا بالله شيئاً', 'ألا يسرقوا ولا يزنوا', 'ألا يقتلوا أولادهم'], 'قال: (أبايعكم على أن لا تشركوا بالله شيئاً، ولا تسرقوا، ولا تزنوا، ولا تقتلوا أولادكم، ولا تأتوا ببهتان... ولا تعصوني في معروف).');
M(5, 65, 'قال النبي ﷺ في بيعة العقبة الأولى: (ومن أصاب من ذلك شيئاً، فأُخذ به في الدنيا ……):', ['فهو كفارة له وطهور', 'فذلك إلى الله إن شاء عذّبه وإن شاء غفر له', 'فلا بيعة له', 'ليس مما سبق'], '(ومن أصاب من ذلك شيئاً، فأُخذ به في الدنيا فهو كفارة له وطهور، ومن ستره الله فذلك إلى الله، إن شاء عذّبه وإن شاء غفر له).');
M(5, 65, 'أمر النبي ﷺ مصعب بن عمير رضي الله عنه حين بعثه مع الأنصار أن:', ['جميع ما ذكر', 'يقرئهم القرآن', 'يعلّمهم الإسلام', 'يصلّي بهم'], 'بعث رسول الله ﷺ معهم مصعب بن عمير، وأمره أن يقرئهم القرآن، ويعلّمهم الإسلام، ويصلّي بهم.');
M(5, 65, 'السبب الذي جعل الأنصار يجتمعون ويقررون أن يأتوا برسول الله ﷺ إلى المدينة:', ['ما كان يلاقيه ﷺ في مكة من عنت قريش وأذاها', 'رغبتهم في قتال اليهود', 'طلب أبي طالب منهم حمايته', 'ليس مما سبق'], 'وبقي رسول الله ﷺ في مكة يلاقي عنت قريش وأذاها الذي كان يشتد على مر الأيام، وأثّر ذلك في نفوس الأنصار، فاجتمعوا وقرروا أن يأتوا به إلى المدينة.');
M(5, 66, 'كان عدد من قدم من الأنصار إلى مكة للقاء رسول الله ﷺ في بيعة العقبة الثانية:', ['ليس مما سبق', 'اثني عشر رجلاً', 'سبعين رجلاً وثلاث نساء', 'خمسمائة رجل'], 'الصحيح: ثلاثة وسبعون رجلاً وامرأتان؛ فقدم إلى مكة ثلاثة وسبعون رجلاً وامرأتان للقاء رسول الله ﷺ.');
M(5, 66, 'جعل النبي ﷺ جزاء الأنصار إن وفوا بما بايعوه عليه في بيعة العقبة الثانية:', ['الجنة', 'الملك والسيادة', 'الغنائم', 'ليس مما سبق'], 'قال: (...وعلى أن تنصروني، فتمنعوني إذا قدمت عليكم مما تمنعون منه أنفسكم وأزواجكم وأبناءكم، ولكم الجنة).');

// هجرة الرسول ﷺ إلى المدينة — أولاً: مؤامرة دار الندوة
M(5, 66, 'لما رأت قريش أن الإسلام أضحى له في يثرب دار يتحصن بها، خشوا أن يقطع أهل المدينة طريق تجارتهم إلى:', ['الشام', 'اليمن', 'الحبشة', 'ليس مما سبق'], 'توجّست خيفة من خروج رسول الله ﷺ إلى المدينة، وخشوا أن يقطع أهل المدينة طريق تجارتهم إلى الشام.');
M(5, 67, 'حضر اجتماع أشراف قريش في دار الندوة وليُّهم وشيخهم إبليس في صورة:', ['ليس مما سبق', 'غلام من قريش', 'رجل من أهل اليمن', 'راهب من الشام'], 'الصحيح: في صورة شيخ كبير؛ وحضرهم وليهم وشيخهم إبليس في صورة شيخ كبير.');
M(5, 67, 'صاحب الرأي الذي أقرّته قريش في دار الندوة بأن يأخذوا من كل قبيلة غلاماً جلداً يضربون النبي ﷺ ضربة رجل واحد:', ['أبو جهل', 'أبو لهب', 'أبو سفيان', 'ليس مما سبق'], 'إلى أن قال أبو جهل: أرى أن نأخذ من كل قبيلة من قريش غلاماً نهداً جلداً... فيتفرق دمه في القبائل، فأقرّوه.');
M(5, 67, 'نزل في مكر قريش بالنبي ﷺ في دار الندوة قوله تعالى:', ['﴿وَإِذْ يَمْكُرُ بِكَ الَّذِينَ كَفَرُوا لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ﴾', '﴿وَجَعَلْنَا مِنْ بَيْنِ أَيْدِيهِمْ سَدًّا وَمِنْ خَلْفِهِمْ سَدًّا﴾', '﴿سُبْحَانَ الَّذِي أَسْرَى بِعَبْدِهِ لَيْلًا﴾', 'ليس مما سبق'], 'فأقرّوه، فنزل قوله تعالى: ﴿وَإِذْ يَمْكُرُ بِكَ الَّذِينَ كَفَرُوا لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ...﴾ (الأنفال: 30).');
M(5, 67, 'خرج النبي ﷺ وأبو بكر رضي الله عنه ليلة الهجرة من:', ['خوخة في دار أبي بكر', 'باب دار النبي ﷺ', 'دار الأرقم بن أبي الأرقم', 'ليس مما سبق'], 'ومضى رسول الله ﷺ إلى بيت أبي بكر، فخرجا من خوخة في دار أبي بكر ليلاً.');
M(5, 68, 'الهادي الذي استأجره النبي ﷺ وأبو بكر ليدلهما على الطريق في الهجرة كان:', ['من بني الديل وهو على دين كفار قريش', 'من بني الديل وقد أسلم قبل الهجرة', 'من الأنصار وقد شهد بيعة العقبة', 'ليس مما سبق'], 'وكانا قد استأجرا من بني الديل هادياً ماهراً بالهداية – وهو على دين كفار قريش – فأمناه، فدفعا إليه راحلتيهما.');
M(5, 68, 'قال النبي ﷺ: (يا أبا بكر ما ظنك باثنين الله ثالثهما) حين:', ['خاف أبو بكر لما رأى أقدام المشركين فوق رأسه في الغار', 'لحقهما سراقة بن مالك في الطريق', 'خرجا من دار أبي بكر ليلاً', 'ليس مما سبق'], 'ولما رأى أبو بكر أقدام المشركين فوق رأسه خاف على رسول الله ﷺ فقال: لو أن أحدهم نظر إلى قدميه أبصرنا، فقال: (يا أبا بكر ما ظنك باثنين الله ثالثهما).');
M(5, 68, 'بعد خروج النبي ﷺ وأبي بكر من الغار أخذ بهم الدليل طريق:', ['السواحل', 'الجبال', 'نجد', 'ليس مما سبق'], 'وجاء الهادي براحلتيهما، وانطلق معهما عامر بن فهيرة، والدليل، فأخذ بهم طريق السواحل.');

// ثانياً: براهين في طريق الهجرة
M(5, 69, 'في المرة الثالثة من تتبّع سراقة بن مالك أثر النبي ﷺ:', ['ساخت قوائم فرسه في الرمال', 'عثر به الفرس فسقط عنه', 'رجع إلى مكة دون أن يقترب', 'ليس مما سبق'], 'عثر به الفرس فسقط عنه، ثم عثر به مرة ثانية، وفي المرة الثالثة ساخت قوائمها في الرمال، فتصاعد منها دخان كالإعصار.');
M(5, 69, 'طلب سراقة من النبي ﷺ أن يكتب له كتاب أمن، فكتبه في رقعة من أديم بأمر النبي ﷺ:', ['عامر بن فهيرة', 'زيد بن حارثة', 'علي بن أبي طالب', 'ليس مما سبق'], 'فطلب سراقة من النبي ﷺ أن يكتب له كتاب أمن فأمر عامر بن فهيرة فكتب في رقعة من أديم.');
M(5, 69, 'من الآيات والبراهين في طريق الهجرة ما كان في خيمة:', ['أم معبد الخزاعية', 'أم سليم الأنصارية', 'أم العلاء الأنصارية', 'ليس مما سبق'], 'ومن الآيات والبراهين ما كان في خيمة أم معبد الخزاعية حيث مرّ رسول الله ﷺ بها في طريقه إلى المدينة.');
M(5, 69, 'الشاة التي حلبها النبي ﷺ في خيمة أم معبد فروي الجميع من لبنها كانت:', ['شاة خلّفها الجهد عن الغنم', 'أكثر غنمها لبناً', 'شاة أهداها له أبو بكر رضي الله عنه', 'ليس مما سبق'], 'قالت: شاة خلّفها الجهد عن الغنم، قال: (هل بها من لبن؟) قالت: هي أجهد من ذلك... فمسح بيده ضرعها، وسمى الله، وحلب حتى روي الجميع.');

// ثالثاً: استقبال الأنصار لرسول الله ﷺ
M(5, 70, 'لما سمع المسلمون بالمدينة بمخرج النبي ﷺ من مكة كانوا يغدون كل غداة ينتظرونه حتى يردّهم حرّ الظهيرة إلى:', ['الحرّة', 'سوق المدينة', 'جبل أحد', 'ليس مما سبق'], 'كانوا يغدون كل غداة إلى الحرّة، فينتظرونه حتى يردّهم حرّ الظهيرة.');
M(5, 70, 'الذي أبصر النبي ﷺ وأصحابه مقبلين فقال بأعلى صوته: يا معاشر العرب، هذا جدّكم الذي تنتظرون:', ['رجل من يهود', 'البراء بن عازب', 'أبو أيوب الأنصاري', 'ليس مما سبق'], 'أوفى رجل من يهود على أطم من آطامهم... فبصر برسول الله ﷺ وأصحابه، فلم يملك اليهودي أن قال بأعلى صوته: يا معاشر العرب، هذا جدكم الذي تنتظرون.');
M(5, 70, 'نزل النبي ﷺ أول قدومه المدينة في:', ['بني عمرو بن عوف', 'بني سالم بن عوف', 'بني النجار', 'ليس مما سبق'], 'فتلقوا رسول الله ﷺ بظهر الحرة، فعدل بهم ذات اليمين، حتى نزل بهم في بني عمرو بن عوف.');
M(5, 70, 'كان نزول النبي ﷺ في بني عمرو بن عوف عند قدومه المدينة يوم:', ['الاثنين من شهر ربيع الأول', 'الجمعة من شهر ربيع الأول', 'الاثنين من شهر رمضان', 'ليس مما سبق'], 'حتى نزل بهم في بني عمرو بن عوف، وذلك يوم الاثنين من شهر ربيع الأول.');
M(5, 70, 'الصحابي القائل: «ثم جاء النبي ﷺ فما رأيت أهل المدينة فرحوا بشيء فرحهم به»:', ['البراء بن عازب', 'أنس بن مالك', 'عبادة بن الصامت', 'ليس مما سبق'], 'يقول البراء بن عازب رضي الله عنه: «ثم جاء النبي ﷺ فما رأيت أهل المدينة فرحوا بشيء فرحهم به».');
M(5, 70, 'كان في استقبال النبي ﷺ وصاحبه من الأنصار زهاء:', ['ليس مما سبق', 'ثلاثمائة', 'ألف', 'مائة'], 'الصحيح: زهاء خمسمائة؛ وكان في استقبالهما «زهاء خمسمائة من الأنصار».');
M(5, 71, 'أقام النبي ﷺ بقباء أياماً، قيل:', ['أربعة عشر يوماً', 'شهراً كاملاً', 'يوماً واحداً', 'ليس مما سبق'], 'وأقام رسول الله ﷺ بقباء أياماً، قيل: أربعة عشر يوماً، وكان أول عمل أنجزه تأسيس مسجد قباء.');
M(5, 71, 'أدركت النبيَّ ﷺ صلاةُ الجمعة بعد خروجه من قباء فصلّاها في المسجد الذي في بطن الوادي في:', ['بني سالم بن عوف', 'بني عمرو بن عوف', 'بني النجار', 'ليس مما سبق'], 'ثم ركب بأمر الله تعالى فأدركته الجمعة في بني سالم بن عوف، فصلّاها في المسجد الذي في بطن الوادي.');
M(5, 71, 'قال النبي ﷺ لمن أخذوا بخطام راحلته يريدون أن ينزل عليهم:', ['دعوها فإنها مأمورة', 'ارجعوا إلى دياركم', 'بارك الله فيكم وفي داركم', 'ليس مما سبق'], 'فأخذوا خطام راحلته، وقالوا: هلمّ إلى العدد والعدّة والمنعة، فقال: (دعوها فإنها مأمورة).');

// الدروس المستفادة
M(5, 71, 'من دلائل أهمية الصلاة وشرفها أن الله تعالى فرضها على نبيه ﷺ:', ['دون واسطة بينه وبين نبيه', 'بواسطة جبريل عليه السلام في الأرض', 'في المسجد الحرام قبل الإسراء', 'ليس مما سبق'], 'أهمية الصلاة وشرفها؛ فقد أمر الله بها من فوق السماء السابعة، في أعلى مكان وصله بشر، وفرضها دون واسطة بينه وبين نبيه.');
M(5, 71, 'يُستفاد من ذهاب النبي ﷺ إلى الناس في المواسم أن المسلم:', ['ينتهز كل فرصة ويستغل كل مناسبة يجتمع فيها الناس لدعوتهم', 'يقتصر في دعوته على أهله وأقاربه', 'ينتظر الناس حتى يأتوا إليه', 'ليس مما سبق'], 'المسلم ينتهز كل فرصة، ويستغل كل مناسبة يجتمع فيها الناس لدعوتهم إلى الله تعالى؛ فقد كان ﷺ يذهب إلى الناس في المواسم.');
M(5, 72, 'استعانة النبي ﷺ بدليل يدلّه على الطريق في هجرته، واختياره غار ثور للاختباء فيه، تدل على أن:', ['الأخذ بالأسباب المشروعة لا ينافي التوكل على الله', 'التوكل على الله يقتضي ترك الأسباب', 'الهجرة كانت بغير تخطيط', 'ليس مما سبق'], 'الأخذ بالأسباب المشروعة لا ينافي التوكل على الله، فالرسول ﷺ استعان بدليل يدله على الطريق، واختار غار ثور للاختباء فيه ثلاثاً.');

/* ═══════════════ u06 ═══════════════ */
// بناء المجتمع المسلم — أولاً: بناء المسجد النبوي
M(6, 75, 'بُني المسجد النبوي في:', ['المكان الذي بركت فيه الناقة', 'دار أبي أيوب الأنصاري', 'دار أنس بن مالك', 'ليس مما سبق'], 'كانت الخطوة الأولى في المدينة هو بناء المسجد النبوي، وذلك في المكان الذي بركت فيه الناقة.');
M(6, 75, 'كان المكان الذي بُني فيه المسجد النبوي في الأصل حائطاً – بستاناً – لـ:', ['غلامين يتيمين من بني النجار', 'أبي أيوب الأنصاري', 'سعد بن عبادة', 'ليس مما سبق'], 'وكان في الأصل حائطاً – بستاناً – لغلامين يتيمين من بني النجار.');
M(6, 75, 'لما عرض الغلامان اليتيمان أن يهبا أرض المسجد للنبي ﷺ:', ['أبى أن يقبله منهما هبة حتى ابتاعه منهما', 'قبله منهما هبة ودعا لهما', 'قبله منهما وعوّضهما بأرض أخرى', 'ليس مما سبق'], 'فقالا: لا، بل نهبه لك يا رسول الله، فأبى رسول الله أن يقبله منهما هبة حتى ابتاعه منهما، ثم بناه مسجداً.');
M(6, 75, 'كان النبي ﷺ يقول وهو ينقل اللبن في بناء المسجد: (اللهم إن الأجر أجر الآخرة، فارحم ……):', ['الأنصار والمهاجرة', 'أهل المدينة كلهم', 'من بنى هذا المسجد', 'ليس مما سبق'], 'ويقول: اللهم إن الأجر أجر الآخرة ❖ فارحم الأنصار والمهاجرة.');
M(6, 75, 'كان المسجد النبوي في العهد المدني مركزاً للمجتمع المسلم، حيث كان:', ['جميع ما ذكر', 'مؤسسة لقيادة الدولة', 'معهداً للتعليم', 'محكمة للقضاء'], 'حيث كان مؤسسة لقيادة الدولة، ومسجداً للعبادة، ومعهداً للتعليم، ومحكمة للقضاء، وملاذاً لجميع أطياف المجتمع.');

// ثانياً: المؤاخاة بين المهاجرين والأنصار
M(6, 76, 'شرّع النبي ﷺ نظام المؤاخاة، وجعل له من الحقوق والواجبات:', ['ما لأخوة النسب', 'أقل مما لأخوة النسب', 'ما لحق الجوار فقط', 'ليس مما سبق'], 'فشرّع نظام المؤاخاة، وجعل له من الحقوق والواجبات ما لأخوة النسب.');
M(6, 76, 'آخى النبي ﷺ بين المهاجرين والأنصار على المواساة، وكانوا:', ['يتوارثون بعد الموت دون ذوي الأرحام', 'لا يتوارثون مطلقاً', 'يتوارثون مع ذوي الأرحام بالتساوي', 'ليس مما سبق'], 'آخى بينهم على المواساة، يتوارثون بعد الموت، دون ذوي الأرحام.');
M(6, 76, 'لما عرض الأنصار على النبي ﷺ أن يتقاسموا الثروة بينهم وبين إخوانهم المهاجرين:', ['أبى المهاجرون إلا المشاركة في العمل', 'قبل المهاجرون ذلك شاكرين', 'أمرهم النبي ﷺ بقسمة الأموال مناصفة', 'ليس مما سبق'], 'حتى عرضوا على رسول الله ﷺ أن يتقاسموا الثروة بينهم وبين إخوانهم، فأبى المهاجرون إلا المشاركة في العمل.');
M(6, 76, 'كان الواحد من الأنصار يتسابق إلى بذل ما عنده لإخوانه المهاجرين حتى يؤول الأمر إلى:', ['الاقتراع', 'الخصومة', 'ترك الأمر للمهاجرين يختارون', 'ليس مما سبق'], 'وكان الواحد منهم يتسابق إلى بذل ما عنده، حتى يؤول الأمر إلى الاقتراع.');
M(6, 76, 'قالت أم العلاء الأنصارية رضي الله عنها: «لما قدم المهاجرون المدينة اقترعت الأنصار على سكنهم، فطار لنا …… في السكنى»:', ['ليس مما سبق', 'عثمان بن عفان', 'مصعب بن عمير', 'عبد الرحمن بن عوف'], 'الصحيح: عثمان بن مظعون؛ «فطار لنا عثمان بن مظعون في السكنى».');
M(6, 76, 'مدح الله تعالى الأنصار لإيثارهم إخوانهم المهاجرين بقوله:', ['﴿وَيُؤْثِرُونَ عَلَى أَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ﴾', '﴿وَإِذْ يَمْكُرُ بِكَ الَّذِينَ كَفَرُوا﴾', '﴿وَجَعَلْنَا مِنْ بَيْنِ أَيْدِيهِمْ سَدًّا﴾', 'ليس مما سبق'], 'وقد مدحهم الله بذلك، فقال: ﴿وَالَّذِينَ تَبَوَّءُوا الدَّارَ وَالْإِيمَانَ مِنْ قَبْلِهِمْ... وَيُؤْثِرُونَ عَلَى أَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ﴾ (الحشر: 9).');

// تشريعات وأحداث مهمة في الدولة الإسلامية الجديدة
M(6, 77, 'ليس أدلّ على رسوخ الاعتقاد في قلوب الصحابة وتنفيذهم المباشر لأمر الله بعد الهجرة من:', ['تأخر تحريم الخمر حتى رسخ الاعتقاد، فلما نزل تحريمه أراقوها', 'مشاركتهم في بناء المسجد النبوي', 'اقتراعهم على سكنى المهاجرين', 'ليس مما سبق'], 'وليس أدل على ذلك من تأخر تحريم الخمر حتى رسخ الاعتقاد الصحيح في قلوبهم، فلما رسخ ونزل تحريمه فتحوا أبوابهم وأراقوها.');
M(6, 77, 'قالت عائشة رضي الله عنها: (إنما نزل أول ما نزل منه – أي القرآن – سورة من المفصل فيها ذكر ……):', ['الجنة والنار', 'الحلال والحرام', 'تحريم الخمر والزنا', 'ليس مما سبق'], '(إنما نزل أول ما نزل منه سورة من المفصل فيها ذكر الجنة والنار حتى إذا ثاب الناس إلى الإسلام نزل الحلال والحرام).');
M(6, 77, 'قال ابن حجر: أشارت عائشة رضي الله عنها بقولها في أول ما نزل من القرآن إلى:', ['الحكمة الإلهية في ترتيب التنزيل', 'ترتيب سور القرآن في المصحف', 'سبب نزول آية تحريم الخمر', 'ليس مما سبق'], 'قال ابن حجر: «أشارت – يعني عائشة – إلى الحكمة الإلهية في ترتيب التنزيل... فلما اطمأنت النفوس على ذلك أنزلت الأحكام».');

// أولاً: تشريع الأذان
M(6, 77, 'كان المسلمون بعد هجرتهم إلى المدينة وبنائهم المسجد – قبل تشريع الأذان – يجتمعون للصلاة:', ['في مواقيتها من غير نداء لها', 'بضرب الطبول', 'برفع راية على المسجد', 'ليس مما سبق'], 'فلما هاجروا إلى المدينة، وبنوا المسجد، كانوا يجتمعون للصلاة في مواقيتها من غير نداء لها، فشعروا بالحاجة إلى أداة تجمعهم.');
M(6, 78, 'من طرق الإعلان التي اعتادها اليهود والنصارى وكرهها النبي ﷺ:', ['جميع ما ذكر', 'البوق', 'الناقوس', 'النار'], 'وكره رسول الله ﷺ طرق الإعلان التي اعتادها اليهود والنصارى من بوق وناقوس ونار، فأكرم الله المسلمين بالأذان.');
M(6, 78, 'قال النبي ﷺ لعبد الله بن زيد الأنصاري رضي الله عنه لما أخبره برؤيا الأذان:', ['إنها لرؤيا حق إن شاء الله', 'إنها أضغاث أحلام', 'لا تحدّث بها أحداً', 'ليس مما سبق'], 'فقال ﷺ: (إنها لرؤيا حق، إن شاء الله، فقم مع بلال، فألق عليه ما رأيت فليؤذّن به).');
M(6, 78, 'أمر النبي ﷺ عبد الله بن زيد أن يلقي الأذان على بلال ليؤذّن به؛ لأن بلالاً:', ['أندى صوتاً منه', 'أقدم إسلاماً منه', 'أحفظ منه للأذان', 'ليس مما سبق'], '(فقم مع بلال، فألق عليه ما رأيت فليؤذّن به؛ فإنه أندى صوتاً منك).');

// ثانياً: تحويل القبلة
M(6, 78, 'كان النبي ﷺ يصلي بمكة إلى:', ['بيت المقدس والكعبة بين يديه', 'الكعبة فقط', 'بيت المقدس مستدبراً الكعبة', 'ليس مما سبق'], 'كان رسول الله ﷺ يصلي بمكة إلى بيت المقدس، والكعبة بين يديه، فلما هاجر إلى المدينة لم يمكنه أن يجمع بينهما.');
M(6, 78, 'صلّى النبي ﷺ في المدينة إلى بيت المقدس مستدبراً الكعبة:', ['ليس مما سبق', 'ستة أشهر', 'ثلاثة عشر شهراً', 'عشرين شهراً'], 'الصحيح: ستة عشر شهراً أو سبعة عشر شهراً؛ فصلى إلى بيت المقدس أول مقدمه المدينة، واستدبر الكعبة ستة عشر شهراً، أو سبعة عشر شهراً.');
M(6, 78, 'كان النبي ﷺ يحب أن تُصرف قبلته نحو الكعبة؛ لأنها:', ['قبلة إبراهيم عليه السلام', 'أقرب إلى المدينة', 'قبلة اليهود والنصارى', 'ليس مما سبق'], 'وكان ﷺ يحب أن تصرف قبلته نحو الكعبة قبلة إبراهيم عليه السلام، وكان يكثر الدعاء والتضرع إلى الله في ذلك.');
M(6, 78, 'أنزل الله تعالى في تحويل القبلة قوله:', ['﴿قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا﴾', '﴿أُذِنَ لِلَّذِينَ يُقَاتَلُونَ بِأَنَّهُمْ ظُلِمُوا﴾', '﴿وَجَعَلْنَا مِنْ بَيْنِ أَيْدِيهِمْ سَدًّا﴾', 'ليس مما سبق'], 'فأنزل الله: ﴿قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ﴾ (البقرة: 144).');

// ثالثاً: فرض صيام رمضان
M(6, 79, 'لما قدم النبي ﷺ المدينة – قبل فرض صيام رمضان – كان:', ['يصوم من كل شهر ثلاثة أيام ويصوم عاشوراء', 'لا يصوم إلا يوم عاشوراء', 'يصوم الاثنين والخميس فقط', 'ليس مما سبق'], 'لما قدم رسول الله ﷺ المدينة كان يصوم من كل شهر ثلاثة أيام، ويصوم عاشوراء، ويأمر بصيامه.');
M(6, 79, 'فرض الله تعالى صيام رمضان وجعله ركناً من أركان الإسلام في شهر:', ['ليس مما سبق', 'رمضان من السنة الأولى للهجرة', 'رجب من السنة الثانية للهجرة', 'شوال من السنة الثانية للهجرة'], 'الصحيح: في شهر شعبان من السنة الثانية للهجرة فرض الله تعالى الصيام وجعله ركناً من أركان الإسلام.');
M(6, 79, 'بعد أن أصبح الصيام لازماً على المستطيع، شُرع الإطعام لـ:', ['الكبير الذي لا يستطيع الصيام', 'جميع المسلمين على التخيير', 'المسافر فقط', 'ليس مما سبق'], 'وفرض أولاً على وجه التخيير بينه وبين الإطعام، ثم أصبح لازماً على المستطيع، وشرع الإطعام للكبير الذي لا يستطيع الصيام.');

// رابعاً: فرض الزكاة
M(6, 79, 'فُرضت الزكاة المقدّرة بالنصب والمقادير الخاصة في أموال الأغنياء:', ['بعد فرض الصيام', 'قبل فرض الصيام', 'قبل الهجرة', 'ليس مما سبق'], 'ثم فرض الزكاة المقدرة بالنصب والمقادير الخاصة في أموال الأغنياء، وجعلها ركناً من أركان الإسلام، وكان ذلك بعد فرض الصيام.');
M(6, 79, 'أصل الزكاة الذي كان واجباً بمكة على الأرجح كان:', ['من غير تقييد بنصاب أو حول', 'مقيداً بنصاب وحول', 'مقيداً بنصاب دون حول', 'ليس مما سبق'], 'أما أصل الزكاة فكانت واجبة بمكة على الأرجح، من غير تقييد بنصاب أو حول.');

// خامساً: الإذن بالجهاد
M(6, 80, 'بعد هجرة المسلمين إلى المدينة فراراً بدينهم قام كفار قريش بـ:', ['جميع ما ذكر', 'مصادرة أموال المسلمين وعقاراتهم بمكة', 'المبادرة بإعلان الحرب عليهم', 'السعي مع اليهود والمنافقين لإثارة الفتن داخل المدينة'], 'صادر كفار قريش أموال المسلمين وعقاراتهم بمكة، وبادروا بإعلان الحرب عليهم، وسعوا مع اليهود والمنافقين بشتى الطرائق لإثارة الفتن في داخل المدينة.');
M(6, 80, 'استعانت قريش في المدينة بعميلها رأس المنافقين:', ['عبد الله بن أبي بن سلول', 'كعب بن الأشرف', 'حيي بن أخطب', 'ليس مما سبق'], 'واستعانوا بعميلهم عبد الله بن أبي بن سلول رأس المنافقين، فعاش المسلمون في المدينة يحدق بهم الخطر من كل جانب.');
M(6, 80, 'أذن الله تعالى للمسلمين بالجهاد حين عاشوا في المدينة يحدق بهم الخطر من كل جانب:', ['دفاعاً عن النفس والإيمان', 'طلباً للغنائم', 'ثأراً من قريش', 'ليس مما سبق'], 'فحينئذ أذن الله تعالى للمسلمين بالجهاد؛ دفاعاً عن النفس والإيمان.');
M(6, 80, 'قال ابن القيم: لما استقر النبي ﷺ بالمدينة ومنعته أنصار الله، رمتهم ……… عن قوس واحدة:', ['العرب واليهود', 'الفرس والروم', 'قريش وثقيف', 'ليس مما سبق'], 'قال ابن القيم: «...رمتهم العرب واليهود عن قوس واحدة، وشمّروا لهم عن ساق العداوة والمحاربة».');
M(6, 80, 'قال ابن القيم: حتى قويت الشوكة واشتد الجناح، فأذن لهم حينئذ في القتال:', ['ولم يفرضه عليهم', 'وفرضه عليهم قتال المشركين كافة', 'وفرضه عليهم فرض عين', 'ليس مما سبق'], '«حتى قويت الشوكة واشتد الجناح، فأذن لهم حينئذ في القتال ولم يفرضه عليهم»، ثم فرض عليهم القتال لمن قاتلهم.');
M(6, 81, 'لما أُمر المسلمون بقتال جميع المشركين صار حكمه على المشهور:', ['فرض كفاية', 'فرض عين', 'مستحباً', 'ليس مما سبق'], '«ثم مأموراً به لجميع المشركين، إما فرض عين على أحد القولين، أو فرض كفاية على المشهور».');
M(6, 81, 'القتال في الإسلام وسيلة لـ:', ['دفع الظلم والاعتداء والتمكين للدعوة الإسلامية', 'إكراه الناس على الدخول في الإسلام', 'توسيع الملك وجمع الأموال', 'ليس مما سبق'], 'وأما القتال فهو وسيلة لدفع الظلم والاعتداء، والتمكين للدعوة الإسلامية، حتى يدخل الناس في دين الله مختارين من غير فتنة.');

// سادساً: إسلام حبر اليهود عبد الله بن سلام رضي الله عنه
M(6, 81, 'لما سمع عبد الله بن سلام بالنبي ﷺ وعرف صفته وزمانه – قبل قدومه المدينة – كان:', ['مسرّاً صامتاً عليه', 'يحذّر اليهود منه', 'يجاهر بالإيمان به في قومه', 'ليس مما سبق'], 'قال: لما سمعت برسول الله ﷺ، وعرفت صفته واسمه وهيئته وزمانه الذي كنا نتوكف له، فكنت بقباء مسرّاً صامتاً عليه.');
M(6, 82, 'كان عبد الله بن سلام حين أُخبر بقدوم النبي ﷺ:', ['في رأس نخلة له يعمل فيها', 'في مجلس أحبار اليهود', 'في سوق المدينة', 'ليس مما سبق'], 'فأقبل رجل حتى أخبر بقدومه، وأنا في رأس نخلة لي أعمل فيها، وعمتي تحتي جالسة، فلما سمعت الخبر كبّرت.');
M(6, 82, 'اسم عمة عبد الله بن سلام التي كانت جالسة تحته حين كبّر لقدوم النبي ﷺ:', ['ليس مما سبق', 'أم العلاء الأنصارية', 'أم معبد الخزاعية', 'أم سليم الأنصارية'], 'الصحيح: خالدة بنت الحارث؛ «وعمتي خالدة بنت الحارث تحتي جالسة».');
M(6, 82, 'قالت عمة عبد الله بن سلام حين سمعت تكبيره: لو كنت سمعت بـ…… ما زدت:', ['موسى بن عمران', 'عيسى بن مريم', 'إبراهيم الخليل', 'ليس مما سبق'], 'فقالت عمتي: لو كنت سمعت بموسى بن عمران ما زدت، قال: قلت لها: أي عمة، والله هو أخو موسى بن عمران، وعلى دينه.');
M(6, 82, 'أول شيء تكلم به النبي ﷺ لما قدم المدينة – كما حدّث عبد الله بن سلام –:', ['يا أيها الناس، أفشوا السلام، وأطعموا الطعام، وصلّوا والناس نيام', 'يا أيها الناس، قولوا: لا إله إلا الله تفلحوا', 'من يؤويني؟ من ينصرني حتى أبلّغ رسالة ربي؟', 'ليس مما سبق'], 'وكان أول شيء تكلم به أن قال: (يا أيها الناس، أفشوا السلام، وأطعموا الطعام، وصلّوا والناس نيام تدخلوا الجنة بسلام).');
M(6, 82, 'سأل عبد الله بن سلام النبيَّ ﷺ عن ثلاث لا يعلمهن إلا نبي، منها:', ['جميع ما ذكر', 'أول أشراط الساعة', 'أول طعام يأكله أهل الجنة', 'من أي شيء ينزع الولد إلى أبيه أو إلى أخواله'], 'فقال: إني سائلك عن ثلاث لا يعلمهن إلا نبي: ما أول أشراط الساعة؟ وما أول طعام يأكله أهل الجنة؟ ومن أي شيء ينزع الولد إلى أبيه؟ ومن أي شيء ينزع إلى أخواله؟');
M(6, 82, 'قال النبي ﷺ لعبد الله بن سلام: (خبّرني بهن آنفاً ……)، فقال عبد الله: ذاك عدو اليهود من الملائكة:', ['ليس مما سبق', 'ميكائيل', 'إسرافيل', 'ملك الموت'], 'الصحيح: جبريل؛ فقال رسول الله ﷺ: (خبّرني بهن آنفاً جبريل)، فقال عبد الله: ذاك عدو اليهود من الملائكة.');
M(6, 83, 'لما خرج عبد الله بن سلام على اليهود وشهد أن لا إله إلا الله وأن محمداً رسول الله، قالوا:', ['شرّنا وابن شرّنا، ووقعوا فيه', 'أعلمنا وابن أعلمنا', 'صدق، وأسلم بعضهم معه', 'ليس مما سبق'], 'قبل خروجه قالوا: أعلمنا وابن أعلمنا وأخيرنا وابن أخيرنا، فلما خرج وشهد قالوا: شرّنا، وابن شرّنا، ووقعوا فيه.');

// الدروس المستفادة
M(6, 83, 'مشاركة النبي ﷺ أصحابه في بناء المسجد بنفسه، يحمل الحجارة وينقل اللبن، تدل على أن:', ['القدوة العملية أبلغ وأكثر تأثيراً من الأقوال النظرية', 'بناء المساجد لا يكون إلا بيد الإمام', 'العمل اليدوي واجب على كل مسلم', 'ليس مما سبق'], 'الأسوة الحسنة والقدوة العملية أبلغ وأكثر تأثيراً من الأقوال النظرية؛ فالنبي ﷺ شارك في بناء المسجد بنفسه مع أصحابه، لا فرق بين رئيس ومرؤوس.');
M(6, 84, 'أوجب الإسلام الولاء والنصرة بالدين، فكل من كان مؤمناً فهو نصير لجميع المؤمنين؛ قال تعالى:', ['﴿وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ﴾', '﴿وَإِذْ يَمْكُرُ بِكَ الَّذِينَ كَفَرُوا﴾', '﴿وَقَاتِلُوا فِي سَبِيلِ اللَّهِ الَّذِينَ يُقَاتِلُونَكُمْ﴾', 'ليس مما سبق'], 'وأوجب الولاء والنصرة بالدين؛ قال تعالى: ﴿وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ﴾ (التوبة: 71)، فكل من كان مؤمناً فهو نصير لجميع المؤمنين.');
M(6, 84, 'في تشريع الأذان دليل على:', ['أهمية صلاة الجماعة', 'جواز التخلف عن الجماعة لمن سمع النداء', 'مشروعية الإعلان بالناقوس', 'ليس مما سبق'], 'في تشريع الأذان دليل على أهمية صلاة الجماعة، فلما شرع الأذان شدّد في أمر الجماعة، ولم يرخّص في التخلف لمن سمع النداء.');
M(6, 84, 'قال النبي ﷺ للرجل الأعمى الذي استأذنه أن يصلي في بيته لما علم أنه يسمع النداء:', ['فأجب', 'قد رخّصت لك', 'صلّ في بيتك', 'ليس مما سبق'], 'فلما ولّى دعاه، فقال: (هل تسمع النداء بالصلاة؟)، قال: نعم، قال: (فأجب).');
M(6, 84, 'شرّع الإسلام الزكاة مواساة للفقراء والمعوزين، وجعل في أموال الأغنياء حقاً لليتامى والمساكين، وبذلك أرسى قواعد:', ['التكافل الاجتماعي', 'النظام العسكري', 'التجارة الحرة', 'ليس مما سبق'], 'أرسى الإسلام قواعد التكافل الاجتماعي، فشرّع الزكاة مواساة للفقراء والمعوزين... وبذلك تسود الألفة والمودة بين أفراد المجتمع.');
M(6, 84, 'من حكمة الله تعالى التدرج في التشريع والبدء بالأيسر؛ وذلك:', ['حتى تتهيأ النفوس لتلقي الحكم الأشد وتنقاد له', 'تخفيفاً على النبي ﷺ في التبليغ', 'حتى يكثر عدد المسلمين', 'ليس مما سبق'], 'من حكمة الله تعالى التدرج في التشريع شيئاً فشيئاً، والبدء بالأيسر؛ حتى تتهيأ النفوس لتلقي الحكم الأشد، وتنقاد له، كما في تشريع الصيام وتحريم الخمر.');
M(6, 85, 'لم يُؤمر المسلمون بقتال المشركين وهم في مكة؛ لأنهم كانوا بالنسبة للمشركين:', ['ليس مما سبق', 'النصف', 'الثلث', 'الربع'], 'الصحيح: أقل من العشر؛ فلو أمر المسلمون – وهم أقل من العشر – بقتالهم لشق عليهم.');
M(6, 85, 'استدل الكتاب على أن غاية الجهاد أن يكون الدين كله لله بقوله تعالى:', ['﴿وَقَاتِلُوهُمْ حَتَّى لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ لِلَّهِ﴾', '﴿أُذِنَ لِلَّذِينَ يُقَاتَلُونَ بِأَنَّهُمْ ظُلِمُوا﴾', '﴿وَقَاتِلُوا فِي سَبِيلِ اللَّهِ الَّذِينَ يُقَاتِلُونَكُمْ﴾', 'ليس مما سبق'], 'غاية الجهاد أن تكون كلمة الله هي العليا، ويكون الدين كله لله؛ قال تعالى: ﴿وَقَاتِلُوهُمْ حَتَّى لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ لِلَّهِ﴾ (البقرة: 193).');

/* ═══════════════ u07 ═══════════════ */
// الوحدة السابعة: الغزوات الأولى
// غزوة بدر الكبرى (تعريف الغزوة)
M(7, 89, 'الغَزْوَةُ هي:', ['المرّة من الغزو', 'الجماعة من الجند', 'الإقامة في الثغور', 'ليس مما سبق'], 'الغَزْوَةُ: المرَّةُ من الغزو، والاسم: الغَزَاة، والغزو هو الطلب والقصد.');
M(7, 89, 'ما لم يحضره النبي ﷺ بنفسه، بل أرسل بعض أصحابه إلى العدو، يسمّيه المحدّثون وأهل السِّيَر غالبًا:', ['سريةً وبعثًا', 'غزوةً', 'فتحًا', 'ليس مما سبق'], 'قال الزرقاني: جرت عادتهم أن يسمّوا كل عسكر حضره النبي ﷺ بنفسه غزوة، وما لم يحضره سريةً وبعثًا.');
// أولاً: تاريخ الغزوة
M(7, 89, 'كانت غزوة بدر الكبرى في شهر:', ['رمضان من السنة الثانية من الهجرة', 'شوال من السنة الثانية من الهجرة', 'رمضان من السنة الثالثة من الهجرة', 'ليس مما سبق'], 'كانت غزوة بدر في شهر رمضان من السنة الثانية من الهجرة، وهي أول معركة في الإسلام.');
// ثانياً: سبب الغزوة والاستعداد لها
M(7, 89, 'كانت قافلة قريش التي أراد النبي ﷺ اعتراضها قبل غزوة بدر قادمة من:', ['الشام', 'اليمن', 'الحبشة', 'ليس مما سبق'], 'سبب غزوة بدر أن قافلة تجارية لقريش كانت قادمة من الشام، فأراد رسول الله ﷺ أن يعترض طريقها.');
M(7, 89, 'كانت قافلة قريش التي خرج النبي ﷺ لاعتراضها قبل بدر بقيادة:', ['أبي سفيان', 'أبي جهل', 'خالد بن الوليد', 'ليس مما سبق'], 'كانت القافلة قادمة من الشام بقيادة أبي سفيان.');
M(7, 89, 'أراد النبي ﷺ باعتراض قافلة قريش قبل بدر:', ['أن يسترد بعض ما غصبته قريش من أموال المسلمين', 'أن يأخذ بالثأر لمن قُتل من المسلمين بمكة', 'أن يعقد مع قريش صلحًا', 'ليس مما سبق'], 'أراد أن يعترض القافلة لكي يسترد بعض ما غصبته قريش من أموال المسلمين، ويوقف عدوانها؛ فلم يكن خروجه للقتال، وإنما كان قصده القافلة.');
M(7, 90, 'كان عدد المسلمين الذين خرجوا مع النبي ﷺ في غزوة بدر:', ['ثلاثمائة وبضعة عشر رجلًا', 'سبعمائة رجل', 'ألف رجل', 'ليس مما سبق'], 'خرج النبي ﷺ في ثلاثمائة وبضعة عشر رجلًا.');
M(7, 90, 'لم يكن مع المسلمين يوم بدر من الخيل سوى فرسين، هما فرس:', ['الزبير والمقداد', 'طلحة والزبير', 'المقداد وسعد بن معاذ', 'ليس مما سبق'], 'لم يكن معه من الخيل سوى فرس الزبير، وفرس المقداد رضي الله عنهما.');
M(7, 90, 'كان مع المسلمين في غزوة بدر من الإبل:', ['سبعون بعيرًا', 'سبعمائة بعير', 'مائة بعير', 'ليس مما سبق'], 'لم يكن مع المسلمين من الخيل سوى فرسين، ومن الإبل سبعون بعيرًا.');
M(7, 90, 'بلغ جيش قريش الذي خرج لنجدة القافلة يوم بدر:', ['ألف مقاتل', 'ثلاثة آلاف مقاتل', 'سبعمائة مقاتل', 'ليس مما سبق'], 'أجابت قريش أبا سفيان بجيش قوامه ألف مقاتل.');
M(7, 90, 'كان مع جيش قريش في غزوة بدر:', ['مائة فرس وسبعمائة بعير', 'مائتا فرس وسبعمائة دارع', 'فرسان وسبعون بعيرًا', 'ليس مما سبق'], 'جيش قريش في بدر: ألف مقاتل، ومعهم مائة فرس وسبعمائة بعير.');
M(7, 90, 'أبى الرجوع بعد نجاة القافلة، وقال: «والله لا نرجع حتى نرد ماء بدر، ونقيم عليه ثلاثًا… فتهابنا العرب أبدًا»:', ['أبو جهل', 'أبو سفيان', 'خالد بن الوليد', 'ليس مما سبق'], 'تمكن أبو سفيان من الفرار بالقافلة عن طريق الساحل، لكن أبا جهل أبى الرجوع وقال ذلك.');
M(7, 90, 'لما استشار النبي ﷺ أصحابه في القتال قبل بدر قال: «يا رسول الله، امض لما أمرك الله فنحن معك»:', ['المقداد بن عمرو', 'عمر بن الخطاب', 'الزبير بن العوام', 'ليس مما سبق'], 'قال المقداد بن عمرو رضي الله عنه: «يا رسول الله! امض لما أمرك الله، فنحن معك».');
M(7, 90, 'لما استشار النبي ﷺ الأنصار قبل بدر بادر فقال: «لو استعرضت بنا هذا البحر فخضته لخضناه معك»:', ['سعد بن معاذ', 'أنس بن النضر', 'عبد الله بن جبير', 'ليس مما سبق'], 'ثم استشار الأنصار فبادر سعد بن معاذ رضي الله عنه فقال ذلك.');
M(7, 91, 'كانت ليلة معركة بدر ليلة:', ['ليس مما سبق', 'السابع والعشرين من رمضان', 'الخامس عشر من رمضان', 'العاشر من رمضان'], 'الصحيح: ليلة السابع عشر من رمضان، وبات رسول الله ﷺ فيها يصلي ويدعو حتى أصبح.');
M(7, 91, 'لما سقط رداء النبي ﷺ عن منكبيه وهو يدعو يوم بدر أخذه فألقاه على منكبيه، وقال: «يا نبي الله، كفاك مناشدتك ربك»:', ['أبو بكر الصديق', 'عمر بن الخطاب', 'علي بن أبي طالب', 'ليس مما سبق'], 'أتاه أبو بكر رضي الله عنه فأخذ رداءه فألقاه على منكبيه، ثم التزمه من ورائه، وقال: كفاك مناشدتك ربك، فإنه سينجز لك ما وعدك.');
M(7, 91, 'من حال النبي ﷺ ليلة بدر وصبيحتها:', ['جميع ما ذكر', 'بات ليلة المعركة يصلي ويدعو حتى أصبح', 'لجأ إلى الله بالدعاء لما أقبلت قريش في كتائبها', 'ظل يهتف بربه مادًّا يديه مستقبل القبلة'], 'بات ﷺ ليلة المعركة يصلي ويدعو، ولما أقبلت قريش لجأ إلى الله بالدعاء، وما زال يهتف بربه مادًّا يديه مستقبل القبلة حتى سقط رداؤه.');
// ثالثاً: بدء المعركة وتحقق النصر
M(7, 91, 'خرج النبي ﷺ يوم بدر وهو يقول: ﴿سيهزم الجمع ويولون الدبر﴾ من:', ['العريش', 'الشِّعب', 'جبل عينين', 'ليس مما سبق'], 'خرج ﷺ من العريش وهو يقول: ﴿سيهزم الجمع ويولون الدبر﴾ (القمر: 45).');
M(7, 92, 'القائل: «لقد رأيتُنا يوم بدر ونحن نلوذ برسول الله ﷺ، وهو أقربنا إلى العدو»:', ['ليس مما سبق', 'أنس بن مالك', 'جابر بن عبد الله', 'أبو بكر الصديق'], 'الصحيح: علي بن أبي طالب رضي الله عنه، وتمام قوله: «وكان من أشد الناس يومئذ بأسًا».');
M(7, 92, 'قُتل من المشركين يوم بدر وأُسر منهم:', ['سبعون قتيلًا وسبعون أسيرًا', 'سبعون قتيلًا وأربعة عشر أسيرًا', 'أربعة عشر قتيلًا وسبعون أسيرًا', 'ليس مما سبق'], 'أخذ المشركون يتساقطون حتى قُتل منهم سبعون، وأُسر سبعون، وفرّ الباقون تاركين الغنائم خلفهم.');
M(7, 92, 'عدد من استُشهد من المسلمين في غزوة بدر:', ['ليس مما سبق', 'سبعون رجلًا', 'ستة رجال', 'ثلاثة رجال'], 'الصحيح: استُشهد من المسلمين في بدر أربعة عشر رجلًا.');
M(7, 92, 'كانت الغنائم قبل هذه الأمة:', ['لا يحل أخذها لأحد', 'حلالًا لكل الأمم', 'تُقسم بين الأنبياء وأتباعهم', 'ليس مما سبق'], 'أباح الله للمسلمين الغنائم، وقد كانت الغنائم لا يحل أخذها لأحد قبل هذه الأمة.');
M(7, 92, 'أمر النبي ﷺ بقتلى المشركين يوم بدر فأُلقوا في:', ['قليب', 'الخندق', 'الشِّعب', 'ليس مما سبق'], 'وأمر ﷺ بقتلى المشركين، فأُلقوا في قليب.');
M(7, 92, 'علّل عمر بن الخطاب رضي الله عنه إشارته بقتل أسرى بدر بقوله:', ['هؤلاء أئمة الكفر وصناديدها', 'هؤلاء نقضوا العهد مع المسلمين', 'هؤلاء أسرى لا فداء لهم', 'ليس مما سبق'], 'أشار عمر بن الخطاب رضي الله عنه بأن يُقتّلوا، وعلّل ذلك بقوله: هؤلاء أئمة الكفر وصناديدها.');
M(7, 92, 'من حجج أبي بكر رضي الله عنه في أخذ الفدية من أسرى بدر:', ['جميع ما ذكر', 'أنهم بنو العم والعشيرة', 'أن الفدية تكون قوة للمسلمين على الكفار', 'رجاء أن يهديهم الله للإسلام'], 'قال أبو بكر: يا نبي الله، هم بنو العم والعشيرة، أرى أن تأخذ منهم فدية، فتكون لنا قوة على الكفار، فعسى الله أن يهديهم للإسلام.');
M(7, 92, 'نزل في عتاب المسلمين على أخذ الفداء من أسرى بدر قوله تعالى:', ['﴿ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض﴾', '﴿ليس لك من الأمر شيء أو يتوب عليهم﴾', '﴿وما أصابكم من مصيبة فبما كسبت أيديكم﴾', 'ليس مما سبق'], 'أجاز القرآن تصرف النبي ﷺ في أخذ الفداء مع بعض العتاب، فقال تعالى: ﴿ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض…﴾ (الأنفال: 67–68).');
// غزوة أحد — أولاً: المشهد الأول من المعركة
M(7, 93, 'رصدت قريش لتجهيز جيشها لحرب المسلمين في أحد:', ['أموال القافلة التي نجت من المسلمين قبيل بدر', 'فداء أسراها يوم بدر', 'أموالًا جمعتها من يهود المدينة', 'ليس مما سبق'], 'رصدوا أموال القافلة التي تمكن أبو سفيان من الإفلات بها قبيل معركة بدر لتجهيز جيش لحرب المسلمين.');
M(7, 93, 'خرجت قريش بقيادة أبي سفيان لغزوة أحد في:', ['منتصف شوال من السنة الثالثة للهجرة', 'رمضان من السنة الثانية للهجرة', 'ربيع الأول من السنة الرابعة للهجرة', 'ليس مما سبق'], 'خرجت بقيادة أبي سفيان في منتصف شوّال من السنة الثالثة للهجرة.');
M(7, 93, 'كان عدد جيش قريش في غزوة أحد:', ['ليس مما سبق', 'ألف مقاتل', 'عشرة آلاف مقاتل', 'سبعمائة مقاتل'], 'الصحيح: ثلاثة آلاف مقاتل من أبناء قريش وحلفائها من القبائل.');
M(7, 93, 'كان مع جيش قريش في غزوة أحد:', ['مائتا فرس وسبعمائة دارع', 'مائة فرس وسبعمائة بعير', 'فرسان ومائة دارع', 'ليس مما سبق'], 'خرجت قريش في ثلاثة آلاف مقاتل، ومعهم مائتا فرس، وسبعمائة دارع.');
M(7, 93, 'جاءت قريش بنسائها إلى غزوة أحد:', ['لئلا يفروا', 'لمداواة الجرحى', 'لإعداد الطعام للجيش', 'ليس مما سبق'], 'وجاؤوا بنسائهم؛ لئلا يفروا.');
M(7, 93, 'خرج النبي ﷺ لملاقاة المشركين في غزوة أحد في:', ['ألف مقاتل', 'ثلاثة آلاف مقاتل', 'ثلاثمائة وبضعة عشر رجلًا', 'ليس مما سبق'], 'خرج النبي ﷺ لملاقاتهم في ألف مقاتل، ومعه فرسان، ومائة دارع.');
M(7, 93, 'لبس النبي ﷺ يوم أحد درعين:', ['تعليمًا للأمة مشروعية الأخذ بالأسباب', 'لأنه لم يكن مع المسلمين إلا درعان', 'لإرهاب المشركين', 'ليس مما سبق'], 'ولبس ﷺ درعين؛ تعليمًا للأمة على مشروعية الأخذ بالأسباب.');
M(7, 93, 'وضع النبي ﷺ قوة من الرماة يوم أحد على جبل:', ['عينين', 'سلع', 'ثور', 'ليس مما سبق'], 'وضع قوة من الرماة على جبل عينين الذي عُرف فيما بعد بجبل الرماة.');
M(7, 94, 'كان عدد الرماة الذين وضعهم النبي ﷺ على الجبل يوم أحد:', ['ليس مما سبق', 'سبعين رجلًا', 'مائة رجل', 'أربعة عشر رجلًا'], 'الصحيح: خمسون رجلًا، وأمّر عليهم عبد الله بن جبير رضي الله عنه.');
M(7, 94, 'أمر النبي ﷺ الرماة يوم أحد أن يلزموا مركزهم، وقال لأميرهم:', ['ادفع الخيل عنّا بالنّبل، لا يأتونا من خلفنا', 'إذا انهزم المشركون فانزلوا واجمعوا الغنائم', 'احموا النساء والأطفال في الحصون', 'ليس مما سبق'], 'قال: ادفع الخيل عنّا بالنّبل، لا يأتونا من خلفنا، وأمرهم بأن يلزموا مركزهم.');
// ثانياً: المشهد الثاني من المعركة
M(7, 94, 'لما رأى أن الجبل قد خلا من الرماة إلا القليل يوم أحد كرّ بالخيل على من بقي منهم:', ['خالد بن الوليد', 'أبو سفيان', 'وحشي بن حرب', 'ليس مما سبق'], 'لما رأى خالد بن الوليد أن الجبل قد خلا من الرماة إلا القليل كرّ بالخيل، وتبعه عكرمة بن أبي جهل وآخرون.');
M(7, 94, 'لما اضطرب أمر المسلمين يوم أحد صاح الشيطان:', ['قُتل محمد', 'انهزم المسلمون', 'جاء المدد للمشركين', 'ليس مما سبق'], 'وصاح الشيطان عند ذلك: قُتل محمد، فلم يشك أحد أنه حق، فخارت قوى المسلمين.');
M(7, 95, 'مرّ بالقاعدين عن القتال يوم أحد فقال: «ما تصنعون في الحياة بعده؟ قوموا فموتوا على ما مات عليه»:', ['ليس مما سبق', 'أنس بن مالك', 'طلحة بن عبيد الله', 'أبو طلحة الأنصاري'], 'الصحيح: أنس بن النضر رضي الله عنه، قالها لما قالوا له: قُتل رسول الله ﷺ.');
M(7, 95, 'من الآيات التي أنزلها الله في غزوة أحد تحذيرًا من عاقبة المخالفة والمنازعة:', ['﴿ولقد صدقكم الله وعده إذ تحسونهم بإذنه﴾', '﴿سيهزم الجمع ويولون الدبر﴾', '﴿فكلوا مما غنمتم حلالًا طيبًا﴾', 'ليس مما سبق'], 'أنزل الله قرآنًا يحذر من عاقبة المخالفة والمنازعة ويبين شؤم المعصية: ﴿ولقد صدقكم الله وعده إذ تحسونهم بإذنه حتى إذا فشلتم وتنازعتم في الأمر…﴾ (آل عمران: 152).');
M(7, 95, 'لما قال النبي ﷺ يوم أحد: «كيف يفلح قوم شجّوا نبيهم، وكسروا رباعيته، وهو يدعوهم إلى الله؟» أنزل الله:', ['﴿ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون﴾', '﴿ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض﴾', '﴿سيهزم الجمع ويولون الدبر﴾', 'ليس مما سبق'], 'فأنزل الله عز وجل: ﴿ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون﴾ (آل عمران: 128).');
M(7, 96, 'نزع حلقتي المغفر من وجه النبي ﷺ يوم أحد حتى سقطت ثنيتاه:', ['ليس مما سبق', 'أبو طلحة الأنصاري', 'طلحة بن عبيد الله', 'علي بن أبي طالب'], 'الصحيح: أبو عبيدة بن الجراح رضي الله عنه، نزع إحدى الحلقتين فسقطت ثنيته، ثم نزع الأخرى فسقطت ثنيته الأخرى.');
// ثالثاً: حب الصحابة رضي الله عنهم وفداؤهم للرسول ﷺ
M(7, 96, 'أُفرد رسول الله ﷺ يوم أحد كما قال أنس بن مالك رضي الله عنه في:', ['سبعة من الأنصار ورجلين من قريش', 'سبعة من المهاجرين ورجلين من الأنصار', 'خمسين من الرماة', 'ليس مما سبق'], 'قال أنس: «أُفرد رسول الله ﷺ يوم أحد في سبعة من الأنصار ورجلين من قريش… فلم يزل كذلك حتى قُتل السبعة».');
M(7, 97, 'قال النبي ﷺ لطلحة رضي الله عنه حين ضُربت يده فقُطعت أصابعه فقال: «حَسِّ»:', ['لو قلت بسم الله لرفعتك الملائكة والناس ينظرون', 'أنت رفيقي في الجنة', 'ارمِ فداك أبي وأمي', 'ليس مما سبق'], 'قال رسول الله ﷺ: (لو قلتَ بسم الله لرفعتك الملائكة والناس ينظرون).');
// رابعاً: الاستبسال في صد المشركين
M(7, 98, 'كفّ المشركون عن القتال يوم أحد وانصرفوا لأنهم:', ['يئسوا من إنهاء المعركة بنصر حاسم وخافوا أن تكون الجولة الثالثة للمسلمين', 'أسروا عددًا كبيرًا من المسلمين', 'علموا بوصول مدد للمسلمين من المدينة', 'ليس مما سبق'], 'لما رأوا استماتة المسلمين يئسوا من إنهاء المعركة بنصر حاسم، وخافوا أن تكون الجولة الثالثة للمسلمين، فكفّوا وانصرفوا ولم يأخذوا أسيرًا ولا غنيمة.');
M(7, 98, 'أعطت هند بنت عتبة قلائدها وأقراطها وحشيَّ بن حرب جزاءً له على:', ['قتله حمزة رضي الله عنه', 'قتله عبد الله بن جبير رضي الله عنه', 'قتله أنس بن النضر رضي الله عنه', 'ليس مما سبق'], 'أعطت هند قلائدها الحقيقية وأقراطها وحشيَّ بن حرب؛ جزاء له على قتله حمزة رضي الله عنه.');
M(7, 98, 'أمر النبي ﷺ في شهداء أحد:', ['أن يُدفنوا بدمائهم، ولم يُغسّلوا، ولم يُصلَّ عليهم', 'أن يُغسّلوا ويُصلّى عليهم', 'أن يُغسّلوا ولا يُصلّى عليهم', 'ليس مما سبق'], 'قال جابر رضي الله عنه: وأمر بدفنهم في دمائهم، ولم يُغسلوا، ولم يُصلَّ عليهم.');
// الدروس المستفادة
M(7, 99, 'من الدروس المستفادة أن النصر على الأعداء:', ['لا يكون إلا من عند الله، والعبد يأخذ بالأسباب ولا يتكل عليها', 'يكون بكثرة العَدد والعُدد', 'لا يحتاج معه إلى الأخذ بالأسباب', 'ليس مما سبق'], 'النصر على الأعداء لا يكون إلا من عند الله، وليس بكثرة العدد والعدد: ﴿وما النصر إلا من عند الله العزيز الحكيم﴾، فالعبد يأخذ بالأسباب ولا يتكل عليها.');
M(7, 99, 'شؤم المعصية كما في الدروس المستفادة:', ['قد يتعدّى إلى من حول من قارفها فيصيب الصالح والطالح', 'يقتصر على من قارفها وحده', 'لا يظهر أثره في الدنيا أبدًا', 'ليس مما سبق'], 'شؤم المعصية لا يقتصر على من قارفها، بل قد يتعدّى إلى من حوله، فيصيب الصالح والطالح جميعًا في الدنيا.');
M(7, 99, 'من الدروس المستفادة الحذر من الإشاعات؛ لأنها:', ['جميع ما ذكر', 'تهدّ كيان الأمة وتفرّق الكلمة', 'تزعزع الأمن والاستقرار', 'تكون سببًا في تثبيط الهمم'], 'أهمية التثبت في نقل الأخبار، والحذر من الإشاعات التي تهدّ كيان الأمة، وتفرّق الكلمة، وتزعزع الأمن والاستقرار، وتكون سببًا في تثبيط الهمم.');

/* ═══════════════ u08 ═══════════════ */
// الوحدة الثامنة: غزوات: بني النضير، والخندق، وبني قريظة
// غزوة بني النضير — أولاً: من هم بنو النضير؟
M(8, 103, 'كان بنو النضير وبنو ……… نزولًا بظاهر المدينة في حدائق وحصون لهم:', ['قريظة', 'قينقاع', 'عامر', 'ليس مما سبق'], 'النضير قبيلة من اليهود كانوا بالمدينة، وكانوا هم وبنو قريظة نزولًا بظاهر المدينة في حدائق وحصون لهم.');
M(8, 103, 'تُسمّى منازل بني النضير التي غزاهم النبي ﷺ فيها:', ['وادي بطحان', 'جبل سلع', 'الشِّعب', 'ليس مما سبق'], 'منازلهم التي غزاهم النبي ﷺ فيها تُسمّى وادي بطحان، وموضع آخر يقال له البويرة.');
// ثانياً: سبب الغزوة
M(8, 103, 'خرج النبي ﷺ إلى بني النضير قبل الغزوة:', ['ليستعين بهم في دية الرجلين من بني عامر', 'ليدعوهم إلى الإسلام', 'ليجدد العهد معهم', 'ليس مما سبق'], 'كان سبب الغزوة أن رسول الله ﷺ خرج إلى بني النضير ليستعين بهم في دية الرجلين من بني عامر، وكان بين بني النضير وبني عامر عقد وحلف.');
M(8, 103, 'قتل الرجلين من بني عامر اللذين خرج النبي ﷺ يستعين ببني النضير في ديتهما:', ['ليس مما سبق', 'محمد بن مسلمة', 'حيي بن أخطب', 'عبد الله بن أبي'], 'الصحيح: عمرو بن أمية الضمري.');
M(8, 103, 'أضمر بنو النضير الغدر بالنبي ﷺ حين قعد إلى جدار من جدرهم، بأن:', ['يصعد رجل على ظهر البيت فيلقي عليه صخرة', 'يضعوا له السم في الطعام', 'يطعنه رجل منهم من خلفه', 'ليس مما سبق'], 'قالوا: من رجل يصعد على ظهر البيت فيلقي على محمد ﷺ صخرة فيقتله فيريحنا منه؟ فأوحى الله إلى رسوله بما ائتمروا به، فرجع إلى المدينة.');
// ثالثاً: موقف الرسول ﷺ من غدر بني النضير
M(8, 104, 'أرسله النبي ﷺ إلى بني النضير يقول لهم: اخرجوا من بلدي فلا تساكنوني بها:', ['محمد بن مسلمة', 'علي بن أبي طالب', 'سعد بن معاذ', 'ليس مما سبق'], 'لما استبان لرسول الله ﷺ غدر اليهود أرسل إليهم محمد بن مسلمة أن اخرجوا من بلدي فلا تساكنوني بها.');
M(8, 104, 'أمهل النبي ﷺ بني النضير للخروج من المدينة:', ['عشرة أيام', 'ثلاثة أيام', 'شهرًا', 'ليس مما سبق'], 'ثم أمهلهم ﷺ عشرة أيام للخروج.');
M(8, 104, 'وعد عبد الله بن أبيّ رأس المنافقين بني النضير بإرسال ……… من جماعته يدافعون عنهم:', ['ألفين', 'ألف', 'ثلاثة آلاف', 'ليس مما سبق'], 'أرسل إليهم ينهاهم عن الخروج، ويعدهم بإرسال ألفين من جماعته يدافعون عنهم، ثم لم يصل إليهم المدد.');
M(8, 104, 'كانت غزوة بني النضير في:', ['ربيع الأول سنة أربع من الهجرة', 'شوال سنة ثلاث من الهجرة', 'شوال سنة خمس من الهجرة', 'ليس مما سبق'], 'وكان ذلك في شهر ربيع الأول سنة أربع من الهجرة.');
M(8, 104, 'حاصر المسلمون بني النضير في حصونهم:', ['ليس مما سبق', 'عشر ليال', 'خمسًا وعشرين ليلة', 'شهرًا'], 'الصحيح: حاصرهم المسلمون ستّ ليال.');
M(8, 104, 'أمر النبي ﷺ بقطع نخيل بني النضير وتحريقها لأنها:', ['كانت عونًا لهم في الحصار', 'كانت تحجب الرؤية عن المسلمين', 'كانت مغصوبة من المسلمين', 'ليس مما سبق'], 'كانت نخيلهم وبساتينهم عونًا لهم في ذلك، فأمر رسول الله ﷺ بقطعها وتحريقها، فقذف الله في قلوبهم الرعب.');
M(8, 104, 'أجلى النبي ﷺ بني النضير وكفّ عن دمائهم على أن لهم:', ['ما حملت الإبل من أموالهم إلا السلاح', 'أموالهم كلها مع السلاح', 'نصف أموالهم', 'ليس مما سبق'], 'سألوا رسول الله ﷺ أن يجليهم ويكفّ عن دمائهم على أن لهم ما حملت الإبل من أموالهم إلا السلاح، فقبل منهم ذلك.');
M(8, 104, 'هدم بنو النضير بيوتهم بأيديهم عند خروجهم:', ['ليحملوا منها ما أمكن ولكيلا يستفيد منها المسلمون', 'خوفًا من أن يسكنها المنافقون', 'لأن النبي ﷺ أمرهم بذلك', 'ليس مما سبق'], 'هدموا بيوتهم بأيديهم؛ ليحملوا منها ما أمكن من العتبة ونحوها؛ ولكيلا يستفيد منها المسلمون.');
M(8, 104, 'نزل أشراف بني النضير بعد إجلائهم في:', ['خيبر', 'مكة', 'الطائف', 'ليس مما سبق'], 'نزل أشرافهم في خيبر، ومنهم من سار إلى الشام.');
M(8, 104, 'عدد من أسلم من بني النضير:', ['ليس مما سبق', 'لم يُسلم منهم أحد', 'واحد', 'عشرة'], 'الصحيح: لم يُسلم منهم إلا اثنان.');
// غزوة الخندق — أولاً: موقف كفار قريش وغيرهم من المسلمين قبل غزوة الخندق
M(8, 105, 'أصابت قريشًا نكسة قبل غزوة الخندق بسبب نكوصها عن الخروج في:', ['بدر الآخرة', 'أحد', 'بني النضير', 'ليس مما سبق'], 'كانت قريش تود القضاء على النبي ﷺ، ولا سيما بعد ما أصابها من نكسة بسبب نكوصها عن الخروج في بدر الآخرة.');
M(8, 106, 'من اليهود الذين أجلاهم النبي ﷺ عن المدينة فخرجوا مغيظين محنقين:', ['بنو قينقاع وبنو النضير', 'بنو قريظة وبنو النضير', 'بنو قريظة وبنو قينقاع', 'ليس مما سبق'], 'كان اليهود من بني قينقاع وبني النضير الذين أجلاهم النبي ﷺ عن المدينة مغيظين محنقين، ونسوا عفوه عنهم، وكان يمكنه أن يبيدهم بدل إجلائهم.');
// ثانياً: تأليب اليهود على محاربة المسلمين
M(8, 106, 'كان في وفد يهود بني النضير الذي خرج إلى مكة يحرّض قريشًا على حرب المسلمين:', ['سلام بن أبي الحقيق وحيي بن أخطب', 'عبد الله بن أبي وحيي بن أخطب', 'عمرو بن أمية وسلام بن أبي الحقيق', 'ليس مما سبق'], 'خرج وفد منهم إلى مكة، فيهم سلام بن أبي الحقيق، وحيي بن أخطب، فحرّضوا قريشًا على حرب المسلمين.');
M(8, 106, 'بعد أن أجابت قريشٌ وفدَ اليهود خرجوا إلى ……… فاستجابوا لهم:', ['غطفان', 'بني عامر', 'الأوس', 'ليس مما سبق'], 'فأجابتهم قريش، ثم خرجوا إلى غطفان فاستجابوا لهم، ثم طافوا في قبائل العرب.');
// ثالثاً: موقف المسلمين من جموع المتحزبين
M(8, 106, 'اختير حفر الخندق من الجهة الشمالية للمدينة لأنها:', ['الجهة الوحيدة المكشوفة أمام الأعداء', 'أقرب الجهات إلى مكة', 'جهة مساكن بني قريظة', 'ليس مما سبق'], 'أشار سلمان رضي الله عنه بحفر خندق من الجهة الشمالية للمدينة؛ إذ هي الجهة الوحيدة المكشوفة أمام الأعداء.');
M(8, 106, 'لما أمر النبي ﷺ بحفر الخندق قسّمه بين:', ['المهاجرين والأنصار', 'الأوس والخزرج', 'الرماة والفرسان', 'ليس مما سبق'], 'فأمر رسول الله ﷺ بحفره، وقسّمه بين المهاجرين والأنصار، فاجتهدوا في حفره مع شدة البرد والجوع.');
M(8, 106, 'كان المسلمون أثناء حفر الخندق مع شدة البرد والجوع يلبثون:', ['ثلاثة أيام لا يذوقون طعامًا', 'عشرة أيام لا يذوقون طعامًا', 'شهرًا لا يذوقون طعامًا', 'ليس مما سبق'], 'فقد كانوا يلبثون ثلاثة أيام لا يذوقون طعامًا، وكان ﷺ يدعو لهم، ويحمّسهم.');
M(8, 107, 'لما رأى النبي ﷺ ما بأصحابه من النصب والجوع وهم يحفرون الخندق قال: «اللهم إن العيش عيش الآخرة …»:', ['فاغفر للأنصار والمهاجرة', 'فانصر الأنصار والمهاجرة', 'فارحم الأنصار والمهاجرة', 'ليس مما سبق'], 'قال: (اللهم إن العيش عيش الآخره، فاغفر للأنصار والمهاجره)، فقالوا مجيبين له: نحن الذين بايعوا محمدا، على الجهاد ما بقينا أبدا.');
M(8, 107, 'بلغ طول الخندق الذي حفره المسلمون:', ['ليس مما سبق', 'ثلاثة آلاف ذراع', 'ألف ذراع', 'عشرة آلاف ذراع'], 'الصحيح: بلغ طوله خمسة آلاف ذراع.');
// رابعاً: آيات النبوة أثناء حفر الخندق
M(8, 108, 'معنى قول جابر رضي الله عنه في الكُدية التي ضربها النبي ﷺ بالمعول: «فعاد كثيبًا أهيل»:', ['صارت الصخرة الصلبة رملًا لينًا سائلًا', 'انشقت الصخرة نصفين', 'لم تتأثر الصخرة بالضرب', 'ليس مما سبق'], 'فأخذ النبي ﷺ المعول فضرب، فعاد كثيبًا أهيل، أي صارت الصخرة الصلبة رملًا لينًا سائلًا.');
M(8, 108, 'لما ضرب النبي ﷺ الحجر في الخندق الضربة الأولى فكسر ثلثه قال: «الله أكبر، أُعطيت مفاتيح …»:', ['الشام', 'فارس', 'اليمن', 'ليس مما سبق'], 'قال: (الله أكبر، أعطيت مفاتيح الشام، والله إني لأبصر قصورها الحمر من مكاني هذا).');
M(8, 108, 'لما نزلت قريش وغطفان ومن تابعهم أمام المدينة راعهم ما رأوا من أمر الخندق؛ لأنه:', ['لا عهد للعرب بمثله', 'كان مملوءًا بالماء', 'أحاط بالمدينة من جميع جهاتها', 'ليس مما سبق'], 'وأقبلت قريش وغطفان ومن تابعهم حتى نزلوا أمام المدينة، وراعهم ما رأوا من أمر الخندق؛ إذ لا عهد للعرب بمثله.');
// خامساً: بين الابتلاء والمن بالنصر
M(8, 108, 'أمر النبي ﷺ في غزوة الخندق بوضع النساء والأطفال في:', ['أحد الحصون', 'المسجد', 'الشِّعب', 'ليس مما سبق'], 'أمر النبي ﷺ بوضع النساء والأطفال في أحد الحصون، ثم خرج بالمسلمين وجعل الخندق أمامه.');
M(8, 108, 'خرج النبي ﷺ في غزوة الخندق في:', ['ليس مما سبق', 'ألف مقاتل', 'سبعمائة مقاتل', 'عشرة آلاف مقاتل'], 'الصحيح: خرج في ثلاثة آلاف من المسلمين.');
M(8, 108, 'جعل النبي ﷺ ظهره في غزوة الخندق إلى جبل:', ['سلع', 'أحد', 'عينين', 'ليس مما سبق'], 'فجعل ظهره إلى جبل سلع، والخندق أمامه.');
M(8, 109, 'مضى في غزوة الخندق ……… دون حرب بين الفريقين سوى الرمي بالنبل والحجارة من وراء الخندق:', ['قريب من شهر', 'أسبوع واحد', 'قريب من ثلاثة أشهر', 'ليس مما سبق'], 'ومضى قريب من شهر دون حرب بين الفريقين سوى الرمي بالنبل والحجارة من وراء الخندق.');
M(8, 109, 'كانت مساكن بني قريظة:', ['جنوب المدينة', 'شمال المدينة', 'في خيبر', 'ليس مما سبق'], 'حملهم حيي بن أخطب على نقض العهد ليضربوا المسلمين من الخلف، حيث كانت مساكنهم جنوب المدينة.');
M(8, 109, 'أرسل الله على الأحزاب ريحًا باردة في ليلة مظلمة شاتية:', ['جميع ما ذكر', 'كفأت قدورهم', 'أطفأت نيرانهم', 'قلعت خيامهم'], 'أرسل على أعدائه ريحًا باردة في ليلة مظلمة شاتية، كفأت قدورهم، وأطفأت نيرانهم، وقلعت خيامهم، وأرسل الملائكة فزلزلتهم.');
M(8, 110, 'من الآيات التي ذكرت نعمة الله على المؤمنين بإرسال الريح والملائكة على الأحزاب قوله تعالى:', ['﴿فأرسلنا عليهم ريحًا وجنودًا لم تروها﴾', '﴿إذ تستغيثون ربكم فاستجاب لكم﴾', '﴿وما النصر إلا من عند الله﴾', 'ليس مما سبق'], 'وفي ذلك يقول الله تعالى: ﴿يا أيها الذين آمنوا اذكروا نعمة الله عليكم إذ جاءتكم جنود فأرسلنا عليهم ريحًا وجنودًا لم تروها﴾ (الأحزاب: 9).');
M(8, 110, 'أرسله النبي ﷺ ليلة رحيل الأحزاب ليأتيه بخبرهم:', ['ليس مما سبق', 'سلمان الفارسي', 'محمد بن مسلمة', 'أنس بن مالك'], 'الصحيح: حذيفة بن اليمان رضي الله عنه، فوجدهم في خوف وذعر وقد تهيؤوا للرحيل.');
M(8, 110, 'استُشهد من المسلمين يوم الخندق، وقُتل من المشركين:', ['ستة من المسلمين، وثلاثة نفر من المشركين', 'أربعة عشر من المسلمين، وسبعون من المشركين', 'سبعون من المسلمين، وثلاثة نفر من المشركين', 'ليس مما سبق'], 'واستشهد من المسلمين يوم الخندق ستة، وقُتل من المشركين ثلاثة نفر.');
// غزوة بني قريظة — أولاً: سبب الغزوة
M(8, 110, 'من أسباب غزوة بني قريظة:', ['جميع ما ذكر', 'ما انطوت عليه نفوسهم من اللؤم والغدر', 'تحزّبهم مع قريش وحلفائها', 'نقضهم عهدهم مع النبي ﷺ إبّان اشتداد معركة الأحزاب'], 'بعد أن رأى ﷺ ما انطوت عليه نفوس يهود بني قريظة من اللؤم والغدر والتحزب مع قريش وحلفائها، وبعد أن أعلنت له إبّان اشتداد معركة الأحزاب أنها نقضت عهدها معه.');
M(8, 111, 'لما رجع النبي ﷺ من الخندق ووضع السلاح واغتسل أتاه يأمره بالخروج إلى بني قريظة:', ['جبريل عليه السلام', 'سعد بن معاذ', 'حذيفة بن اليمان', 'ليس مما سبق'], 'أتاه جبريل عليه السلام وهو ينفض رأسه من الغبار، فقال: قد وضعت السلاح؟ والله ما وضعته، اخرج إليهم، فأشار إلى بني قريظة.');
M(8, 111, 'نادى النبي ﷺ في الناس: «لا يصلّينّ أحد ……… إلا في بني قريظة»:', ['العصر', 'الفجر', 'المغرب', 'ليس مما سبق'], 'ونادى في الناس: (لا يصلين أحد العصر إلا في بني قريظة)، فراح المسلمون أرسالًا.');
M(8, 111, 'استخلف النبي ﷺ على المدينة في غزوة بني قريظة:', ['ليس مما سبق', 'علي بن أبي طالب', 'سعد بن معاذ', 'أبو بكر الصديق'], 'الصحيح: كان خليفته على المدينة عبد الله بن أم مكتوم رضي الله عنه.');
M(8, 111, 'حمل لواء النبي ﷺ في غزوتي بني النضير وبني قريظة:', ['علي بن أبي طالب', 'سعد بن معاذ', 'الزبير بن العوام', 'ليس مما سبق'], 'في بني النضير خرج إليهم ﷺ يحمل لواءه علي بن أبي طالب (ص104)، وفي بني قريظة كان لواؤه بيد علي بن أبي طالب رضي الله عنه.');
// ثانياً: الجزاء من جنس العمل
M(8, 111, 'حاصر النبي ﷺ بني قريظة:', ['خمسًا وعشرين ليلة', 'ست ليال', 'عشرة أيام', 'ليس مما سبق'], 'فحاصرهم رسول الله ﷺ خمسًا وعشرين ليلة حتى جهدهم الحصار، وقذف الله في قلوبهم الرعب.');
M(8, 112, 'كان بنو قريظة حلفاء:', ['الأوس', 'الخزرج', 'بني عامر', 'ليس مما سبق'], 'فحكّم فيهم سعد بن معاذ رضي الله عنه سيد الأوس، وكان بنو قريظة حلفاء الأوس.');
M(8, 112, 'حكم سعد بن معاذ رضي الله عنه في بني قريظة بـ:', ['قتل المقاتلة وسبي ما سواهم وتوزيع أموالهم', 'إجلائهم إلى خيبر بما حملت الإبل', 'أخذ الفدية منهم', 'ليس مما سبق'], 'فحكم فيهم رضي الله عنه بقتل المقاتلة وسبي ما سواهم وتوزيع أموالهم.');
M(8, 112, 'كان جزاء بني قريظة من جنس عملهم؛ لأنهم:', ['عرّضوا بخيانتهم أرواح المسلمين للقتل', 'منعوا المسلمين من الماء', 'قتلوا رسل النبي ﷺ', 'ليس مما سبق'], 'كان جزاء بني قريظة من جنس عملهم حين عرّضوا بخيانتهم أرواح المسلمين للقتل، فعوقبوا بذلك جزاءً وفاقًا.');
// الدروس المستفادة
M(8, 112, 'يؤكد سبب غزوتي بني النضير وبني قريظة أن اليهود:', ['جميع ما ذكر', 'قوم بهت', 'أهل خداع وخيانة', 'ما إن يجدوا سبيلًا إلى إضرار المسلمين إلا استغلوه'], 'سبب غزوة بني النضير إرادة قتل النبي ﷺ وخيانته، وكذا سبب غزوة بني قريظة، مما يؤكد أن اليهود قوم بهت وأهل خداع وخيانة، وما أن يجدوا سبيلًا إلى إضرار المسلمين إلا استغلوه.');
M(8, 112, 'الكفر ملّة واحدة في كل زمان ومكان في مواجهة الإسلام، ويظهر ذلك جليًّا من:', ['تحزّب المشركين من شتى القبائل واليهود لحرب المسلمين', 'خروج قريش وحدها يوم بدر', 'إجلاء بني النضير إلى خيبر', 'ليس مما سبق'], 'الكفر ملّة واحدة؛ ويظهر ذلك جليًّا من تحزّب المشركين من شتى القبائل واليهود لحرب المسلمين.');
M(8, 113, 'تبشير النبي ﷺ أصحابه بانتصار الإسلام في غزوة الأحزاب رغم ما هم فيه من الشدة يدل على أن:', ['المؤمن لا ييأس عند المحنة ولا يفقد الثقة بالله', 'النصر يكون بكثرة العدد', 'الخندق يغني عن القتال', 'ليس مما سبق'], 'المؤمن لا ييأس عند المحنة، ولا يفقد الثقة بالله مهما اشتد الكرب، فالنبي ﷺ في غزوة الأحزاب كان يبشّر أصحابه بانتصار الإسلام.');
M(8, 113, 'القاعدة في العقوبة كما في الدروس المستفادة من غزوة بني قريظة:', ['العقوبة بقدر الجرم', 'العفو مقدّم في كل جريمة', 'العقوبة واحدة في كل الجرائم', 'ليس مما سبق'], 'عظم جريمة الغدر والخيانة، وخاصة في الأمور الأمنية العامة… فكانت عقوبتهم من أشد أنواع العقوبات، والقاعدة أن العقوبة بقدر الجرم.');
M(8, 113, 'من الدروس المستفادة من غزوة بني قريظة:', ['جواز تحكيم أهل العلم والفضل في أمور المسلمين ومهماتهم العظام', 'وجوب إجلاء ناقضي العهد دون عقوبة', 'جواز مهادنة الكفار عند الحاجة', 'ليس مما سبق'], 'جواز تحكيم أهل العلم والفضل في أمور المسلمين وفي مهماتهم العظام، كما حكّم رسول الله ﷺ سعد بن معاذ في أمر بني قريظة، وقبل حكمه فيهم.');

/* ═══════════════ u09 ═══════════════ */
// الوحدة التاسعة: صلح الحديبية، ومراسلة الملوك والأمراء

// صلح الحديبية — أولاً: الخروج إلى الحديبية
M(9, 117, 'سبب خروج النبي ﷺ إلى مكة معتمرًا عام الحديبية:', ['رؤيا رآها في المنام', 'استنجاد خزاعة به', 'نقض قريش للعهد', 'ليس مما سبق'], 'رأى النبي ﷺ في المنام بالمدينة أنه يدخل هو وأصحابه المسجد الحرام آمنين، فأخبر أصحابه وأمرهم أن يتجهزوا للخروج إلى مكة معتمرين.');
M(9, 117, 'خرج النبي ﷺ إلى الحديبية معتمرًا في شهر:', ['ليس مما سبق', 'رمضان', 'شوال', 'ذي الحجة'], 'الصحيح: ذو القعدة؛ «فخرج في ذي القعدة».');
M(9, 117, 'ساق النبي ﷺ الهدي معه في خروجه إلى الحديبية:', ['تعظيمًا للبيت وتكريمًا', 'ليفتدي به من القتال', 'ليقدمه هدية لقريش', 'ليس مما سبق'], 'وساق ﷺ الهدي؛ تعظيما للبيت وتكريما.');
M(9, 117, 'أشعر النبي ﷺ الهدي فجرحه في أحد جانبي السنام وأزال الشعر منه؛ وذلك:', ['ليعلم الناس أنها مهداة إلى البيت', 'ليسهل نحرها عند البيت', 'ليعرف كل صحابي هديه', 'ليس مما سبق'], 'أشعره… ليعلم الناس أنها مُهداة إلى البيت، فلا يتعرّضوا لها.');
M(9, 117, 'أحرم النبي ﷺ بالعمرة عام الحديبية من:', ['ليس مما سبق', 'التنعيم', 'الجحفة', 'الجعرانة'], 'الصحيح: ذو الحليفة؛ «وأحرم بالعمرة من ذي الحليفة».');
M(9, 117, 'لم يحمل المسلمون معهم في خروجهم إلى الحديبية إلا سلاح المسافر، وهو:', ['السيوف في أغمادها', 'الرماح والدروع', 'القسيّ والنبال', 'ليس مما سبق'], 'ولم يحملوا معهم إلا سلاح المسافر، وهو السيوف في أغمادها.');
M(9, 117, 'لما وصل النبي ﷺ قريبًا من …… جاءه الخبر أن قريشًا قد جمعوا الجموع يريدون قتاله:', ['عسفان', 'ذي الحليفة', 'مر الظهران', 'ليس مما سبق'], 'ولما وصل رسول الله ﷺ قريبا من عسفان جاء الخبر أن قريشا قد جمعوا الجموع.');
M(9, 117, 'لما استشار النبي ﷺ أصحابه قال له: «يا رسول الله، خرجت عامدًا لهذا البيت، لا تريد قتل أحد ولا حرب أحد، فتوجّه له»:', ['أبو بكر الصديق', 'عمر بن الخطاب', 'عثمان بن عفان', 'ليس مما سبق'], 'فاستشار النبي ﷺ أصحابه، فقال أبو بكر رضي الله عنه: يا رسول الله، خرجت عامدا لهذا البيت…');
M(9, 118, 'أخبر النبي ﷺ أصحابه أن خالد بن الوليد في خيل لقريش طليعةً بـ:', ['الغميم', 'ذي الحليفة', 'وادي العقيق', 'ليس مما سبق'], 'قال ﷺ: (إن خالد بن الوليد بالغميم في خيل لقريش طليعة).');
M(9, 118, 'الطليعة في قول النبي ﷺ: (في خيل لقريش طليعة) معناها:', ['مقدمة الجيش', 'مؤخرة الجيش', 'ميمنة الجيش', 'ليس مما سبق'], 'قال: (…في خيل لقريش طليعة) – أي: مقدمة الجيش.');
M(9, 118, 'قال النبي ﷺ: (من يصعد الثنية، ثنية المرار؛ فإنه يُحطّ عنه ما حُطّ عن بني إسرائيل)، فكان أول من صعدها:', ['خيل بني الخزرج', 'خيل بني الأوس', 'المهاجرون', 'ليس مما سبق'], 'فكان أولَ من صعدها خيل بني الخزرج، ثم تتامّ الناس.');

// ثانياً: بيعة الرضوان
M(9, 118, 'لما دخل مبعوث النبي ﷺ مكة في الحديبية لقيه ابن عمه فأجاره وحمله على دابته، وهو:', ['أبان بن سعيد بن العاص', 'سهيل بن عمرو', 'عروة بن مسعود الثقفي', 'ليس مما سبق'], 'فلقيه ابن عمّه أبان بن سعيد بن العاص، فأجاره، وحمله على دابته.');
M(9, 118, 'عرضت قريش على مبعوث النبي ﷺ في الحديبية أن يطوف بالبيت، فكان موقفه:', ['رفض حتى يطوف به رسول الله ﷺ', 'طاف بالبيت ثم رجع إلى المسلمين', 'وافق بشرط أن يطوف المسلمون معه', 'ليس مما سبق'], 'فقال عثمان رضي الله عنه: ما كنت لأفعل حتى يطوف به رسول الله ﷺ.');
M(9, 119, 'بايع الصحابة النبيَّ ﷺ بيعة الرضوان تحت الشجرة على:', ['الموت وألا يفروا', 'النصرة والإيواء', 'الهجرة إلى المدينة', 'ليس مما سبق'], 'فبايعوه تحت الشجرة بيعة الرضوان على الموت وعلى أن لا يفروا.');
M(9, 119, 'لم يبايع بيعة الرضوان، واختبأ تحت بطن بعير، وكان منافقًا:', ['الجد بن قيس', 'عبد الله بن أبي بن سلول', 'حكيم بن حزام', 'ليس مما سبق'], 'فبايعه المسلمون كلهم «إلا الجد بن قيس اختبأ تحت بطن بعير»، وكان منافقا.');
M(9, 119, 'قال النبي ﷺ في أهل بيعة الرضوان:', ['(لا يدخل النار أحد ممّن بايع تحت الشجرة)', '(اذهبوا فأنتم الطلقاء)', '(قد نصرت يا عمرو بن سالم)', 'ليس مما سبق'], 'وقال فيهم الرسول ﷺ: (لا يدخل النار أحد ممّن بايع تحت الشجرة).');

// ثالثاً: انبهار المشركين بحب الصحابة للرسول ﷺ
M(9, 119, 'من المشركين الذين فاوضوا النبي ﷺ في الحديبية، وجعل يرمق أصحابه ويتعجّب من تعظيمهم له:', ['عروة بن مسعود الثقفي', 'أبو سفيان بن حرب', 'عكرمة بن أبي جهل', 'ليس مما سبق'], 'حتى جاء عروة بن مسعود الثقفيّ، فتفاوض مع رسول الله ﷺ، وجعل يرمق أصحاب النبي ﷺ… ويتعجّب منهم.');
M(9, 119, 'قال أحد مفاوضي قريش بعد رجوعه من الحديبية: «والله لقد وفدت على الملوك، ووفدت على ……»:', ['جميع ما ذكر صحيح', 'قيصر', 'النجاشي', 'ليس مما سبق'], 'قال عروة: «والله لقد وفدت على الملوك، ووفدت على قيصر وكسرى والنجاشي».');
M(9, 119, 'من الأحوال التي وصف بها مفاوض قريش تعظيم الصحابة للنبي ﷺ:', ['إذا توضأ كادوا يقتتلون على وضوئه', 'إذا جلس قاموا له صفوفًا', 'إذا مشى مشوا خلفه حفاة', 'ليس مما سبق'], 'قال عروة: «…وإذا توضأ كادوا يقتتلون على وضوئه، وإذا تكلّم خفضوا أصواتهم عنده، وما يحدّون إليه النظر تعظيما له».');

// رابعاً: إبرام الصلح وشروطه
M(9, 120, 'أرسلته قريش لإبرام الصلح، فلما رآه النبي ﷺ قال متفائلًا: (قد سهل لكم من أمركم):', ['سهيل بن عمرو', 'عروة بن مسعود الثقفي', 'صفوان بن أمية', 'ليس مما سبق'], 'ثم أرسلت قريش سهيل بن عمرو، فلما رآه النبي ﷺ قال متفائلا: (هذا سهيل، قد سهل لكم من أمركم).');
M(9, 120, 'لما أملى النبي ﷺ «بسم الله الرحمن الرحيم» في كتاب الصلح، طلب مندوب قريش أن يُكتب بدلها:', ['باسمك اللهم', 'بسم الله', 'بسم الله الرحيم', 'ليس مما سبق'], 'قال سهيل: «اكتب باسمك اللهم، كما كنت تكتب»، فقال النبي ﷺ: (اكتب باسمك اللهم).');
M(9, 120, 'كُتب في كتاب صلح الحديبية بدل «محمد رسول الله»:', ['محمد بن عبد الله', 'محمد بن عبد المطلب', 'أبو القاسم محمد', 'ليس مما سبق'], 'قال النبي ﷺ: (والله، إني لرسول الله، وإن كذّبتموني، اكتب محمد بن عبد الله).');
M(9, 120, 'من شروط صلح الحديبية أن يكفّ الفريقان عن الحرب مدة:', ['ليس مما سبق', 'خمس سنين', 'سنتين', 'ثلاث سنين'], 'الصحيح: عشر سنين؛ «أن يكف الفريقان عن الحرب عشر سنين، يأمن فيهن الناس».');
M(9, 121, 'من شروط صلح الحديبية أن يأتي المسلمون مكة معتمرين العام القادم فيقيمون بها:', ['ثلاثة أيام', 'سبعة أيام', 'عشرة أيام', 'ليس مما سبق'], 'على أن يأتوها معتمرين العام القادم، ليس معهم إلا سلاح المسافر، فيقيمون بها ثلاثة أيام.');
M(9, 121, 'من شروط صلح الحديبية فيمن أحب أن يدخل في عهد محمد ﷺ أو في عهد قريش:', ['يدخل في أيهما شاء', 'لا يدخل إلا بإذن الطرفين', 'لا يدخل إلا في عهد قريش', 'ليس مما سبق'], 'أن من أحب أن يدخل في عهد محمد وعقده دخل فيه، ومن أحب أن يدخل في عهد قريش وعقدها دخل فيه.');
M(9, 121, 'ليس من شروط صلح الحديبية:', ['أن يدفع المسلمون لقريش ديات قتلاها', 'أن يكف الفريقان عن الحرب', 'أن يرجع المسلمون هذا العام دون أن يدخلوا مكة', 'ليس مما سبق'], 'شروط الصلح: الكف عن الحرب، وردّ من جاء من قريش، ورجوع المسلمين هذا العام، والدخول في عهد أي الطرفين؛ ولم يُذكر دفع ديات.');
M(9, 121, 'قال النبي ﷺ لما اشتد على الصحابة ردّ المسلمين الفارين من قريش إليها: (إنه من ذهب منّا إليهم فأبعده الله، ومن جاءنا منهم ……):', ['سيجعل الله له فرجًا ومخرجًا', 'فهو آمن', 'رددناه إليهم راضين', 'ليس مما سبق'], 'قال: (نعم، إنه من ذهب منّا إليهم، فأبعده الله، ومن جاءنا منهم سيجعل الله له فرجا ومخرجا).');
M(9, 121, 'لم يتحمّل شروط الصلح، فراجع النبي ﷺ قائلًا: «ألست نبي الله حقًا؟… فلم نعطي الدنيّة في ديننا إذًا؟»:', ['عمر بن الخطاب', 'أبو بكر الصديق', 'علي بن أبي طالب', 'ليس مما سبق'], 'ولم يتحمّل ذلك عمر رضي الله عنه فراجع الرسول ﷺ…');
M(9, 122, 'بعد صلح الحديبية نزل القرآن على رسول الله ﷺ:', ['بالفتح', 'بلوم المسلمين على الصلح', 'بالأمر بقتال قريش', 'ليس مما سبق'], 'فنزل القرآن على رسول الله ﷺ بالفتح، فأرسل إلى عمر فأقرأه إياه، فقال: أوَفتح هو؟ قال: (نعم).');

// خامساً: بركة صلح الحديبية
M(9, 122, 'من بركات صلح الحديبية:', ['جميع ما ذكر صحيح', 'تهيأ للنبي ﷺ أن يراسل الملوك ويدعوهم إلى الإسلام', 'أتاح للمشركين أن يختلطوا بالمسلمين ويتعرفوا على الإسلام', 'ليس مما سبق'], 'إذ تهيأ بسببه لرسول الله ﷺ أن يراسل الملوك… وأتاح هذا الصلح الفرصة للمشركين أن يختلطوا بالمسلمين في ظلّ الأمن والسلام.');
M(9, 122, 'ممن دخل في الإسلام بعد صلح الحديبية:', ['جميع ما ذكر صحيح', 'خالد بن الوليد', 'عمرو بن العاص', 'ليس مما سبق'], 'ودخل في دين الله أضعاف ما دخل من قبل؛ منهم خالد بن الوليد، وعمرو بن العاص رضي الله عنهما.');
M(9, 122, 'حارس الكعبة الذي دخل في الإسلام بعد صلح الحديبية:', ['عثمان بن طلحة', 'عثمان بن عفان', 'سهيل بن عمرو', 'ليس مما سبق'], 'منهم… وحارس الكعبة عثمان بن طلحة رضي الله عنه.');
M(9, 122, 'خرج النبي ﷺ عام فتح مكة بعد صلح الحديبية بـ:', ['سنتين', 'سنة واحدة', 'ثلاث سنين', 'ليس مما سبق'], 'قال ابن هشام: خرج إلى الحديبية في ألف وأربعمائة، ثمّ خرج في عام فتح مكّة بعد ذلك بسنتين في عشرة آلاف.');

// سادساً: الفعل أبلغ من القول
M(9, 123, 'لما فرغ النبي ﷺ من كتاب الصلح وقال لأصحابه: (قوموا فانحروا، ثم احلقوا):', ['لم يقم منهم أحد من شدة الهم والغم', 'قاموا فنحروا وحلقوا مباشرة', 'نحروا ولم يحلقوا', 'ليس مما سبق'], 'فلم يقم منهم أحد، وبقوا واجمين من شدة الهم والغم.');
M(9, 123, 'أشارت على النبي ﷺ أن يخرج فلا يكلّم أحدًا حتى ينحر بُدنه ويدعو حالقه فيحلقه:', ['ليس مما سبق', 'عائشة رضي الله عنها', 'حفصة رضي الله عنها', 'زينب بنت جحش رضي الله عنها'], 'الصحيح: أم سلمة رضي الله عنها؛ دخل عليها فذكر لها ما لقي من الناس فأشارت عليه بذلك.');
M(9, 123, 'لما رأى الصحابة النبي ﷺ نحر بُدنه ودعا حالقه فحلقه قاموا فنحروا، وجعل بعضهم يحلق بعضًا حتى كاد بعضهم يقتل بعضًا غمًّا، ومعنى «غمًّا»:', ['ازدحامًا', 'خطأً', 'غضبًا', 'ليس مما سبق'], 'حتى كاد بعضهم يقتل بعضا غمًّا. أي: ازدحاما.');

// مكاتبة الملوك والأمراء، ودعوتهم إلى الإسلام
M(9, 123, 'كانت مراسلة النبي ﷺ للملوك والزعماء ودعوتهم إلى الإسلام خلال عامي:', ['ست وسبع للهجرة', 'سبع وثمان للهجرة', 'خمس وست للهجرة', 'ليس مما سبق'], 'كتب إلى كسرى وقيصر والنجاشي وإلى كل جبّار يدعوهم إلى الله تعالى، وذلك خلال عامي ست وسبع للهجرة.');
M(9, 124, 'لما قيل للنبي ﷺ إن ملوك العجم لا يقبلون كتابًا إلا بخاتم، اتخذ خاتمًا من:', ['ليس مما سبق', 'ذهب', 'حديد', 'نحاس'], 'الصحيح: من فضة؛ «فاتخذ النبي ﷺ خاتمًا من فضّة نقشه: محمد رسول الله».');
M(9, 124, 'لقي أبو سفيان بن حرب هرقل مع أصحابه في:', ['القدس', 'دمشق', 'القسطنطينية', 'ليس مما سبق'], 'ولما قدم عليه أبو سفيان مع أصحابه في القدس قال هرقل لترجمانه…');
M(9, 124, 'اختار هرقل أبا سفيان من بين أصحابه ليسأله عن النبي ﷺ؛ لأنه كان:', ['أقربهم نسبًا إلى النبي ﷺ', 'أكبرهم سنًّا', 'يعرف لغة الروم', 'ليس مما سبق'], 'قال هرقل لترجمانه: سلهم أيّهم أقرب نسبًا إلى هذا الرجل الذي يزعم أنه نبي؟ فقال أبو سفيان: أنا.');
M(9, 125, 'اعترف هرقل بنبوة النبي ﷺ لكنه لم يسلم؛ لأنه:', ['غلب عليه حب الرئاسة لما رأى مخالفة قومه', 'لم يصدّق ما أخبره به أبو سفيان', 'لم تبلغه رسالة النبي ﷺ كاملة', 'ليس مما سبق'], 'ولكنه لما رأى مخالفة قومه له غلب عليه حبّ الرّئاسة، فلم يسلم، فباء بإثمه وإثم رعيّته.');
M(9, 125, 'بعث النبي ﷺ بكتابه إلى كسرى ملك الفرس مع:', ['ليس مما سبق', 'دحية الكلبي', 'عمرو بن أمية الضمري', 'حاطب بن أبي بلتعة'], 'الصحيح: عبد الله بن حذافة السهمي رضي الله عنه، وأمره أن يدفعه إلى عظيم البحرين.');
M(9, 125, 'أمر النبي ﷺ حامل كتابه إلى كسرى أن يدفعه إلى:', ['عظيم البحرين', 'عظيم اليمن', 'عظيم الحيرة', 'ليس مما سبق'], 'فأمره أن يدفعه إلى عظيم البحرين، فدفعه عظيم البحرين إلى كسرى.');
M(9, 125, 'لما مزّق كسرى كتاب النبي ﷺ دعا عليهم النبي ﷺ:', ['أن يُمزَّقوا كل ممزّق', 'بالقحط والجوع', 'أن يسلّط عليهم الروم', 'ليس مما سبق'], 'فدعا عليهم رسول الله ﷺ أن يمزّقوا كلّ ممزّق. فقُتل كسرى، وتمزقت المملكة الفارسية، ثم زالت من الوجود.');
M(9, 125, 'بعث النبي ﷺ إلى المقوقس ملك الإسكندرية:', ['حاطب بن أبي بلتعة', 'عبد الله بن حذافة السهمي', 'دحية الكلبي', 'ليس مما سبق'], 'وبعث حاطب بن أبي بلتعة رضي الله عنه إلى المقوقس ملك الإسكندرية، فقال خيرا، ولم يسلم.');
M(9, 125, 'أهدى المقوقس للنبي ﷺ جاريتين هما مارية وشيرين، وبغلة تسمى:', ['دلدل', 'القصواء', 'العضباء', 'ليس مما سبق'], 'وأهدى للنبي ﷺ جاريتين؛ هما مارية، وشيرين، وبغلة تسمى دلدل.');

// الدروس المستفادة
M(9, 126, 'في صلح الحديبية دليل على:', ['جواز مهادنة الكفار عند الحاجة', 'وجوب مهادنة الكفار في كل حال', 'تحريم مهادنة الكفار مطلقًا', 'ليس مما سبق'], 'في صلح الحديبية دليل على جواز مهادنة الكفار عند الحاجة إذا رأى الإمام المصلحة فيها.');
M(9, 126, 'استُدل على أن الخيرة فيما يختاره الله لعباده المؤمنين وإن كرهوه في الظاهر بقوله تعالى:', ['﴿فعسى أن تكرهوا شيئا ويجعل الله فيه خيرا كثيرا﴾', '﴿فمن نكث فإنما ينكث على نفسه﴾', '﴿إن أكرمكم عند الله أتقاكم﴾', 'ليس مما سبق'], 'الخيرة فيما يختاره الله لعباده المؤمنين…؛ قال تعالى: ﴿فعسى أن تكرهوا شيئا ويجعل الله فيه خيرا كثيرا﴾ (النساء: 19).');
M(9, 126, 'من الدروس المستفادة من امتثال الصحابة للنحر والحلق بعد أن فعله النبي ﷺ بنفسه:', ['أن القدوة العملية تؤثر في النفوس أكثر من الكلام', 'أن الكلام البليغ يغني عن الفعل', 'أن الحلق يكون قبل النحر', 'ليس مما سبق'], 'القدوة العملية تؤثر في النفوس أكثر من الكلام مهما كان مؤثّرا وبليغا.');
M(9, 126, 'استُدل على عالمية الإسلام في مكاتبة النبي ﷺ للملوك بقوله تعالى:', ['جميع ما ذكر صحيح', '﴿قل يا أيها الناس إني رسول الله إليكم جميعا﴾', '﴿وما أرسلناك إلا رحمة للعالمين﴾', 'ليس مما سبق'], 'في مكاتبة الرسول ﷺ للملوك دليل على عالمية الإسلام؛ قال تعالى: ﴿قل يا أيها الناس إني رسول الله إليكم جميعا﴾، وقال: ﴿وما أرسلناك إلا رحمة للعالمين﴾.');

/* ═══════════════ u10 ═══════════════ */
// الوحدة العاشرة: غزوة الفتح

// سبب غزوة فتح مكة، والاستعداد لها — أولاً: نقض قريش لصلح الحديبية وما ترتّب عليه من أحداث
M(10, 129, 'أراد بنو بكر أن ينتهزوا فرصة الهدنة بعد صلح الحديبية؛ ليصيبوا من خزاعة:', ['الثأر القديم', 'الأموال والإبل', 'الماء والمرعى', 'ليس مما سبق'], 'وكان بين خزاعة وبني بكر ثارات قديمة، فأراد بنو بكر أن ينتهزوا فرصة الهدنة؛ ليصيبوا من خزاعة الثأر القديم.');
M(10, 129, 'بيّت نفر من بني بكر لخزاعة وهم على ماء لهم يدعى:', ['ليس مما سبق', 'بدر', 'الحديبية', 'ذي الحليفة'], 'الصحيح: الوتير؛ «فبيّت نفر من بني بكر لخزاعة، وهم على ماء لهم يدعى الوتير».');
M(10, 129, 'كان نقض قريش لصلح الحديبية بأن:', ['أعانت بني بكر على خزاعة بالسلاح والرجال', 'أغارت على المدينة', 'قتلت رسول النبي ﷺ إليها', 'ليس مما سبق'], 'وأعانت قريش بني بكر بالسّلاح، وقاتل معهم رجال من قريش مستخفين ليلا.');
M(10, 129, 'انحازت خزاعة لما اشتد عليها القتال إلى:', ['الحرم', 'المدينة', 'شعاب مكة', 'ليس مما سبق'], 'حتّى انحازت خزاعة إلى الحرم؛ إذ لم تكن متأهبة لحرب.');
M(10, 129, 'رئيس بني بكر الذي قال كلمة عظيمة: «لا إله اليوم! يا بني بكر، أصيبوا ثأركم»:', ['نوفل بن معاوية', 'صفوان بن أمية', 'حماس بن قيس', 'ليس مما سبق'], 'قالت بنو بكر لرئيسهم نوفل بن معاوية: إنّا قد دخلنا الحرم، إلهك! إلهك! فقال نوفل كلمة عظيمة: لا إله اليوم!');
M(10, 129, 'قدم إلى المدينة فأنشد أبياتًا من الشعر أمام النبي ﷺ يستنصره فيها لخزاعة:', ['ليس مما سبق', 'نوفل بن معاوية', 'حماس بن قيس', 'حكيم بن حزام'], 'الصحيح: عمرو بن سالم الخزاعي؛ فقال له الرسول ﷺ: (قد نصرت يا عمرو بن سالم).');
M(10, 129, 'بعث النبي ﷺ إلى قريش رجلًا يخيّرهم بعد نقض العهد، فاختارت قريش:', ['القتال', 'دفع دية قتلى خزاعة', 'البراءة من حلف بني بكر', 'ليس مما سبق'], 'يخيّرهم بين دفع دية قتلى خزاعة أو البراءة من حلف بكر أو القتال، فاختارت القتال، وبذلك أعذر ﷺ وأنذر.');
M(10, 129, 'لما ندمت قريش وشعرت بخطورة الأمر أرسلت أبا سفيان إلى المدينة يطلب:', ['تجديد المعاهدة والزيادة في المدة', 'الصلح على ترك العمرة', 'إطلاق أسرى قريش', 'ليس مما سبق'], 'ثم ندمت قريش، وشعرت بخطورة الأمر، فأرسلت أبا سفيان إلى المدينة يطلب تجديد المعاهدة والزيادة في المدة.');
M(10, 130, 'القائل لأبي سفيان: «فوالله لو لم أجد إلا الذرّ – أي النمل – لجاهدتكم به»:', ['عمر بن الخطاب', 'أبو بكر الصديق', 'علي بن أبي طالب', 'ليس مما سبق'], 'ثم أتى عمر بن الخطاب رضي الله عنه فكلمه، فقال: أنا أشفع لكم إلى رسول الله ﷺ؟ فوالله لو لم أجد إلا الذرّ لجاهدتكم به.');
M(10, 130, 'نصح أبا سفيان أن يقوم هو فيجير بين الناس، بعد أن اشتدت عليه الأمور:', ['علي بن أبي طالب', 'العباس بن عبد المطلب', 'عثمان بن عفان', 'ليس مما سبق'], 'فاستنصح أبو سفيان عليا رضي الله عنه بعد أن اشتدّت عليه الأمور، فنصحه أن يقوم هو، فيجير بين الناس.');
M(10, 130, 'كانت نتيجة قدوم أبي سفيان إلى المدينة لتجديد المعاهدة:', ['لم يُجزه النبي ﷺ فرجع إلى مكة خائبًا', 'جدّد النبي ﷺ المعاهدة وزاد في مدتها', 'أسلم وبقي في المدينة', 'ليس مما سبق'], 'ففعل، ولكن لم يجزه رسول الله ﷺ، فرجع إلى مكة خائبا.');
M(10, 130, 'حرص النبي ﷺ على إخفاء وجهته عند التجهز لفتح مكة؛', ['لئلا تستعد قريش لقتاله', 'خوفًا من المنافقين في المدينة', 'لأنه لم يكن قد عزم على الفتح بعد', 'ليس مما سبق'], 'وحرص على إخفاء أمره؛ لئلا تستعد قريش لقتاله، فتستباح حرمة البلد الحرام.');
M(10, 130, 'سأل النبي ﷺ ربه عز وجل عند التجهز لفتح مكة أن:', ['يعمي على قريش الأخبار', 'يمده بجنود من الملائكة', 'يؤخر خروج قريش للقتال', 'ليس مما سبق'], 'وسأل الله عز وجل، أن يعمي على قريش الأخبار، فاستجاب له ربه تبارك وتعالى.');

// ثانياً: سير المسلمين اتجاه مكة، وما وقع فيها من الأحداث
M(10, 130, 'خرج النبي ﷺ لفتح مكة:', ['لعشر خلون من رمضان', 'لعشر خلون من شوال', 'لعشر خلون من ذي القعدة', 'ليس مما سبق'], 'خرج ﷺ لعشر خلون من رمضان.');
M(10, 130, 'كان خروج النبي ﷺ لفتح مكة على رأس …… من مقدمه المدينة:', ['ثماني سنين ونصف', 'سبع سنين ونصف', 'تسع سنين ونصف', 'ليس مما سبق'], 'وذلك على رأس ثماني سنين ونصف من مقدمه المدينة.');
M(10, 130, 'سار النبي ﷺ ومن معه إلى مكة حتى نزلوا قربها في:', ['ليس مما سبق', 'الحديبية', 'ذي الحليفة', 'الغميم'], 'الصحيح: مر الظهران؛ «حتى نزل بمرّ الظهران قرب مكة».');
M(10, 131, 'خرج من مكة مع أبي سفيان يلتمسون الأخبار ليلة نزول المسلمين قربها:', ['جميع ما ذكر صحيح', 'حكيم بن حزام', 'بديل بن ورقاء', 'ليس مما سبق'], 'وكان قد خرج من مكة أبو سفيان وحكيم بن حزام وبديل بن ورقاء يلتمسون الأخبار.');
M(10, 131, 'لقي أبا سفيان ومن معه في تلك الليلة على بغلة رسول الله ﷺ:', ['العباس بن عبد المطلب', 'علي بن أبي طالب', 'عمر بن الخطاب', 'ليس مما سبق'], 'فلقيهم العباس بن عبد المطلب على بغلة رسول الله ﷺ في تلك الليلة.');
M(10, 131, 'نادى العباس أبا سفيان بكنيته، فقال:', ['ليس مما سبق', 'أبا الفضل', 'أبا الوليد', 'أبا الحكم'], 'الصحيح: أبا حنظلة؛ «فقال: أبا حنظلة! فعرفه أبو سفيان، فقال: أبو الفضل؟».');
M(10, 131, 'لما قال النبي ﷺ لأبي سفيان: (ويحك يا أبا سفيان، ألم يأن لك أن تعلم أنّي رسول الله؟) قال:', ['والله كان في نفسي منها شيء حتى الآن', 'لو كان مع الله غيره لقد أغنى عني شيئًا', 'ما أنا بفاعل', 'ليس مما سبق'], 'قال: بأبي أنت وأمي، ما أحلمك وأكرمك وأوصلك، هذه، والله كان في نفسي منها شيء حتى الآن.');
M(10, 132, 'قال النبي ﷺ يوم الفتح: (من دخل دار أبي سفيان فهو آمن)، ومن الأمان أيضًا:', ['جميع ما ذكر صحيح', 'من أغلق بابه فهو آمن', 'من دخل المسجد فهو آمن', 'ليس مما سبق'], 'قال: (نعم، من دخل دار أبي سفيان فهو آمن، ومن أغلق بابه فهو آمن، ومن دخل المسجد فهو آمن).');
M(10, 132, 'أمر النبي ﷺ العباس أن يحبس أبا سفيان بمضيق الوادي عند خطم الجبل:', ['حتى تمرّ به جنود الله فيراها', 'ليعلّمه شرائع الإسلام', 'حتى ينتهي القتال في مكة', 'ليس مما سبق'], 'قال رسول الله ﷺ: (يا عباس، احبسه بمضيق الوادي عند خطم الجبل، حتى تمرّ به جنود الله فيراها).');
M(10, 132, 'اسم الكتيبة التي مرّ فيها رسول الله ﷺ في المهاجرين والأنصار على أبي سفيان:', ['الخضراء', 'البيضاء', 'السوداء', 'ليس مما سبق'], 'حتى مرّ رسول الله ﷺ في الخضراء، كتيبة فيها المهاجرون والأنصار.');
M(10, 132, 'لما قال أبو سفيان: «لقد أصبح ملك ابن أخيك الغداة عظيمًا» قال له العباس:', ['إنها النبوّة', 'إنها كثرة الجند', 'إنه الملك العظيم', 'ليس مما سبق'], 'فقال العباس رضي الله عنه: يا أبا سفيان، إنها النبوّة. قال: فنعم إذن.');

// ثالثاً: تقسيم الجيش ودخول مكة
M(10, 133, 'جعل النبي ﷺ على المجنّبة اليمنى عند دخول مكة:', ['خالد بن الوليد', 'عمر بن الخطاب', 'علي بن أبي طالب', 'ليس مما سبق'], 'فجعل خالد بن الوليد رضي الله عنه على المجنّبة اليمنى.');
M(10, 133, 'جعل النبي ﷺ على المجنّبة اليسرى عند دخول مكة:', ['ليس مما سبق', 'أسامة بن زيد', 'عمر بن الخطاب', 'علي بن أبي طالب'], 'الصحيح: الزبير بن العوام رضي الله عنه.');
M(10, 133, 'أمر النبي ﷺ جيشه عند دخول مكة:', ['أن يكفّوا أيديهم ولا يقاتلوا إلا من اعترضهم وقاتلهم', 'أن يقاتلوا كل من وجدوه من قريش', 'أن يدخلوها ليلًا', 'ليس مما سبق'], 'وأمرهم أن يكفّوا أيديهم عند دخول مكّة، وأن لا يقاتلوا إلّا من اعترضهم، وقاتلهم.');
M(10, 133, 'جمع عكرمة بن أبي جهل وصفوان بن أمية وسهيل بن عمرو سفهاء قريش ليقاتلوا المسلمين في:', ['الخندمة', 'الحديبية', 'الصفا', 'ليس مما سبق'], 'وجمع عكرمة بن أبي جهل، وصفوان بن أميّة، وسهيل بن عمرو، سفهاء قريش بالخندمة؛ ليقاتلوا المسلمين.');
M(10, 133, 'كان يُعدّ سلاحًا قبل دخول النبي ﷺ مكة، وقال لامرأته مغترًّا: «إني لأرجو أن أُخدمك بعضهم»:', ['حماس بن قيس', 'نوفل بن معاوية', 'عكرمة بن أبي جهل', 'ليس مما سبق'], 'وكان حماس بن قيس يعدّ سلاحاً قبل دخول رسول الله ﷺ… فقال مغترًّا: إني والله لأرجو أن أخدمك بعضهم.');
M(10, 133, 'قُتل من المسلمين يوم الفتح بعد أن شذّا عن الجيش فسلكا طريقًا غير طريقه:', ['كرز بن جابر الفهري وخنيس بن خالد', 'أبو رهم الغفاري ودحية الكلبي', 'حماس بن قيس وبديل بن ورقاء', 'ليس مما سبق'], 'فقُتل كرز بن جابر الفهري، وخنيس بن خالد من المسلمين، وكانا قد شذّا عن الجيش، فسلكا طريقاً غير طريقه.');

// فتح مكة، وإعلان العفو العام — أولاً: دخول مكة
M(10, 134, 'دخل النبي ﷺ مكة يوم الفتح:', ['من أعلى مكة', 'من أسفل مكة', 'من جهة الحديبية', 'ليس مما سبق'], 'دخل النبي ﷺ يوم الفتح من أعلى مكة على راحلته.');
M(10, 134, 'دخل النبي ﷺ مكة يوم الفتح على راحلته مُردفًا:', ['أسامة بن زيد', 'العباس بن عبد المطلب', 'علي بن أبي طالب', 'ليس مما سبق'], 'دخل… على راحلته، مردفًا أسامة بن زيد رضي الله عنه.');
M(10, 134, 'دخل النبي ﷺ مكة يوم الفتح وعلى رأسه:', ['المغفر', 'التاج', 'الإكليل', 'ليس مما سبق'], 'وعلى رأسه المغفر، ورأسه يكاد يمسّ مقدمة الرّحل.');
M(10, 134, 'كان رأس النبي ﷺ يوم دخوله مكة يكاد يمسّ مقدمة الرحل:', ['من تواضعه لربه عز وجل', 'من شدة التعب', 'اتقاءً للسهام', 'ليس مما سبق'], 'ورأسه يكاد يمسّ مقدمة الرّحل من تواضعه لربه عز وجل.');
M(10, 134, 'كان النبي ﷺ يطعن الأصنام التي حول البيت يوم الفتح بـ:', ['عود في يده', 'رمحه', 'سيفه', 'ليس مما سبق'], 'فجعل يطعنها بعود في يده، ويقول: ﴿جاء الحق وزهق الباطل…﴾.');
M(10, 135, 'لما فرغ النبي ﷺ من طوافه يوم الفتح:', ['أتى الصفا فعلا عليه حتى نظر إلى البيت', 'دخل الكعبة مباشرة', 'خطب الناس عند زمزم', 'ليس مما سبق'], 'فلما فرغ من طوافه ﷺ أتى الصفا، فعلا عليه حتى نظر إلى البيت، ورفع يديه، فجعل يحمد الله، ويدعو.');
M(10, 135, 'امتنع النبي ﷺ يوم الفتح من دخول البيت أول الأمر؛ لأن:', ['فيه الآلهة', 'لم يكن قد طاف بالبيت بعد', 'أهل مكة لم يأذنوا له', 'ليس مما سبق'], 'وأبى ﷺ أن يدخل البيت وفيه الآلهة، فأمر بها فأُخرجت.');
M(10, 135, 'أُخرجت من البيت يوم الفتح صورة …… في أيديهما الأزلام:', ['إبراهيم وإسماعيل', 'إسماعيل وإسحاق', 'آدم ونوح', 'ليس مما سبق'], 'فأخرج صورة إبراهيم وإسماعيل في أيديهما الأزلام، فقال النبي ﷺ: (قاتلهم الله، لقد علموا: ما استقسما بها قطّ).');
M(10, 135, 'استثنى النبي ﷺ في خطبته على درج الكعبة من مآثر الجاهلية التي جعلها تحت قدميه:', ['سدانة البيت وسقاية الحاج', 'الرفادة ودار الندوة', 'اللواء والقيادة', 'ليس مما سبق'], '(ألا إن كل مأثرة كانت في الجاهلية، فإنها تحت قدميّ اليوم، إلا ما كان من سدانة البيت، وسقاية الحاج).');
M(10, 136, 'بيّن النبي ﷺ في خطبة الفتح أن دية ما بين العمد والخطأ (القتل بالسوط والحجر):', ['مائة بعير منها أربعون في بطونها أولادها', 'مائة بعير منها خمسون في بطونها أولادها', 'خمسون بعيرًا منها عشرون في بطونها أولادها', 'ليس مما سبق'], '(ألا وإن ما بين العمد والخطأ القتل بالسوط والحجر، فيها مائة بعير، منها أربعون في بطونها أولادها).');
M(10, 136, 'استشهد النبي ﷺ في خطبة الفتح على أن أكرم الناس عند الله أتقاهم بآية من سورة:', ['الحجرات', 'النساء', 'الأعراف', 'ليس مما سبق'], 'قال الله: ﴿يا أيها الناس إنا خلقناكم من ذكر وأنثى… إن أكرمكم عند الله أتقاكم﴾ (الحجرات: 13).');

// ثانياً: إعلان العفو العام
M(10, 136, 'لما قال النبي ﷺ لقريش يوم الفتح: (يا معشر قريش، ما تقولون؟) قالوا:', ['نقول: ابن أخ، وابن عم رحيم كريم', 'نقول: أنت رسول الله حقًّا', 'نقول: افعل بنا ما شئت', 'ليس مما سبق'], 'قالوا: نقول: ابن أخ، وابن عم رحيم كريم، ثم أعاد عليهم القول قالوا مثل ذلك.');
M(10, 136, 'قال النبي ﷺ لأهل مكة يوم الفتح: (فإني أقول كما قال أخي ……: لا تثريب عليكم اليوم):', ['يوسف', 'موسى', 'إبراهيم', 'ليس مما سبق'], 'قال: (فإني أقول كما قال أخي يوسف: ﴿لا تثريب عليكم اليوم يغفر الله لكم وهو أرحم الراحمين﴾).');
M(10, 137, 'خطب النبي ﷺ فبيّن حرمة مكة، وأنها لم تحلّ لأحد قبله ولا تحلّ لأحد بعده، في:', ['اليوم الثاني من الفتح', 'اليوم الثالث من الفتح', 'اليوم السابع من الفتح', 'ليس مما سبق'], 'ولما كان اليوم الثاني من الفتح خطب ﷺ فحمد الله، وأثنى عليه، وبيّن حرمة مكّة.');
M(10, 137, 'قال النبي ﷺ عن مكة: (وإنما أُذن لي فيها ……، ثم عادت حرمتها اليوم كحرمتها بالأمس):', ['ليس مما سبق', 'يومًا واحدًا', 'ثلاثة أيام', 'ليلة واحدة'], 'الصحيح: ساعة من نهار؛ (وإنما أذن لي فيها ساعة من نهار).');
M(10, 137, 'من أحكام حرمة مكة التي بيّنها النبي ﷺ: لا يحلّ لامرئ يؤمن بالله واليوم الآخر:', ['جميع ما ذكر صحيح', 'أن يسفك بها دمًا', 'أن يعضد بها شجرة', 'ليس مما سبق'], '(فلا يحلّ لامرئ يؤمن بالله واليوم الآخر أن يسفك بها دما، ولا يعضد بها شجرة).');

// ثالثاً: مبايعة أهل مكة على الإسلام
M(10, 137, 'بايع النبي ﷺ أهل مكة بعد الفتح على:', ['الإيمان والشهادتين والسمع والطاعة', 'الهجرة إلى المدينة', 'الموت وألا يفرّوا', 'ليس مما سبق'], 'فبايعهم على الإيمان بالله، وشهادة أن لا إله إلا الله، وأن محمدا عبده ورسوله، والسمع والطاعة لله ولرسوله فيما استطاعوا.');
M(10, 138, 'أتت هند زوجة أبي سفيان التي أهدر النبي ﷺ دمها يوم الفتح لتبايع:', ['مع النساء منتقبة متنكّرة', 'مع زوجها أبي سفيان', 'بعد أن استأمن لها العباس', 'ليس مما سبق'], 'حيث إنها أتت مع النساء منتقبة متنكّرة، وبايعت، فلما علم بها، عفا عنها، وقبل بيعتها.');

// الدروس المستفادة
M(10, 138, 'استُدل على أن ضرر نقض العهد راجع إلى صاحبه بقوله تعالى:', ['﴿فمن نكث فإنما ينكث على نفسه﴾', '﴿فعسى أن تكرهوا شيئا ويجعل الله فيه خيرا كثيرا﴾', '﴿وما أرسلناك إلا رحمة للعالمين﴾', 'ليس مما سبق'], 'بيان عاقبة نقض العهد، وأن ضرر ذلك راجع إلى صاحبه؛ قال تعالى: ﴿فمن نكث فإنما ينكث على نفسه﴾ (الفتح: 10).');
M(10, 139, 'من الدروس المستفادة من غزوة الفتح:', ['جميع ما ذكر صحيح', 'تعظيم حرمة مكة', 'أن العاقبة للحق وأهله وإن تطاولت السنين', 'ليس مما سبق'], 'من الدروس: تعظيم حرمة مكة… والعاقبة للحق وأهله وأن الله ناصرهم وإن تطاولت السنين.');

/* ═══════════════ u11 ═══════════════ */
// الوحدة الحادية عشرة: مرض الرسول ﷺ ووفاته (الكتاب ص143–153)

// مقدمات الوفاة
M(11, 143, 'من الأمارات والإشارات التي أشار بها النبي ﷺ إلى دنو أجله:', ['جميع ما سبق', 'تكرار مدارسة القرآن', 'مضاعفة اعتكاف رمضان', 'توديعه للناس في حجة الوداع'], 'من أمارات دنو أجله ﷺ: تكرار مدارسة القرآن، ومضاعفة اعتكاف رمضان، وإخباره معاذا بقرب وفاته، ونزول سورة النصر، وتوديعه للناس في حجة الوداع.');
M(11, 143, 'راوي حديث: «كان النبي ﷺ يعتكف في كل رمضان عشرة أيام، فلما كان العام الذي قُبض فيه اعتكف عشرين يوما»:', ['ليس مما سبق', 'أنس بن مالك رضي الله عنه', 'عبد الله بن عباس رضي الله عنهما', 'معاذ بن جبل رضي الله عنه'], 'الصحيح: أبو هريرة رضي الله عنه؛ يقول أبو هريرة: (كان النبي ﷺ يعتكف في كل رمضان عشرة أيام، فلما كان العام الذي قبض فيه اعتكف عشرين يوما).');
M(11, 143, 'لما خرج النبي ﷺ يوصي معاذ بن جبل رضي الله عنه حين بعثه إلى اليمن كان:', ['معاذ راكبا والنبي ﷺ يمشي تحت راحلته', 'معاذ ماشيا والنبي ﷺ راكبا', 'النبي ﷺ ومعاذ راكبين', 'ليس مما سبق'], 'قال معاذ رضي الله عنه: خرج معه رسول الله ﷺ يوصيه، ومعاذ راكب، ورسول الله ﷺ يمشي تحت راحلته.');
M(11, 144, 'وقع ما أخبر به النبي ﷺ معاذا رضي الله عنه حين بعثه إلى اليمن؛ فإن معاذا:', ['لم يقدم المدينة إلا بعد وفاته ﷺ', 'قدم المدينة قبل وفاته ﷺ بأيام', 'لقي النبي ﷺ في حجة الوداع', 'ليس مما سبق'], 'فإن معاذا أقام باليمن، ولم يقدم المدينة إلا بعد وفاة الرسول ﷺ.');
M(11, 144, 'تُسمّى سورة النصر:', ['سورة التوديع', 'سورة البشارة', 'سورة الرحيل', 'ليس مما سبق'], 'تسمى سورة النصر سورة التوديع؛ لما فيها من الإيماء إلى وفاته ﷺ وتوديعه الدنيا وما فيها.');
M(11, 144, 'سُئل ابن عباس رضي الله عنهما عن قوله تعالى: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ فقال:', ['أجل رسول الله ﷺ أعلمه إياه', 'فتح مكة ودخول الناس في الإسلام', 'نصر الله لنبيه ﷺ على اليهود', 'ليس مما سبق'], 'سُئل ابن عباس رضي الله عنهما عن قوله تعالى: ﴿إذا جاء نصر الله والفتح﴾ فقال: أجل رسول الله ﷺ أعلمه إياه؛ ولهذا تُعدّ سورة النصر من أمارات دنو أجله ﷺ.');
M(11, 144, 'سأل ابنَ عباس رضي الله عنهما عن سورة النصر، فلما فسّرها قال: «ما أعلم منها إلا ما تعلم»:', ['عمر بن الخطاب رضي الله عنه', 'أبو بكر الصديق رضي الله عنه', 'علي بن أبي طالب رضي الله عنه', 'ليس مما سبق'], 'سأل عمر رضي الله عنه ابن عباس عن السورة فقال: أجل رسول الله ﷺ أعلمه إياه، فقال عمر: ما أعلم منها إلا ما تعلم.');

// مرض النبي ﷺ ووفاته — أولاً: بداية المرض
M(11, 144, 'بدأ المرض برسول الله ﷺ في أواخر شهر:', ['ليس مما سبق', 'ربيع الأول', 'محرم', 'ذي الحجة'], 'الصحيح: صفر؛ بدأ المرض برسول الله ﷺ في أواخر شهر صفر حين زار البقيع.');
M(11, 144, 'وُضع السم للنبي ﷺ في طعامه عقب فتح خيبر في السنة:', ['السابعة', 'السادسة', 'الثامنة', 'ليس مما سبق'], 'وضعته زوجة سلام بن مشكم اليهودية في طعامه عقب فتح خيبر في السنة السابعة.');
M(11, 145, 'الأَبْهَر في قوله ﷺ: «فهذا أوان وجدت انقطاع أبهري من ذلك السم» هو:', ['عرق إذا انقطع مات صاحبه', 'عظم في أعلى الصدر', 'عصب يخرج من الدماغ', 'ليس مما سبق'], 'والأبهر: عرق إذا انقطع مات صاحبه.');
M(11, 145, 'يخرج الأبهران من ……، ثم يتشعب منهما سائر الشرايين:', ['القلب', 'الكبد', 'الرئة', 'ليس مما سبق'], 'والأبهر: عرق إذا انقطع مات صاحبه؛ وهما أبهران يخرجان من القلب، ثم يتشعب منهما سائر الشرايين.');
M(11, 145, 'كان أول ما اشتكى رسول الله ﷺ في بيت:', ['ليس مما سبق', 'عائشة رضي الله عنها', 'حفصة رضي الله عنها', 'أم سلمة رضي الله عنها'], 'الصحيح: ميمونة رضي الله عنها؛ كان أول ما اشتكى رسول الله ﷺ في بيت ميمونة.');
M(11, 145, 'استأذن النبي ﷺ أن يُمرَّض في بيت عائشة رضي الله عنها من:', ['أزواجه', 'أبي بكر رضي الله عنه', 'فاطمة رضي الله عنها', 'ليس مما سبق'], 'فاستأذن أزواجه أن يمرض في بيت عائشة رضي الله عنها فأذنّ له.');
M(11, 145, 'لما انتقل النبي ﷺ في مرضه إلى بيت عائشة رضي الله عنها خرج تخطّ رجلاه في الأرض بين:', ['العباس وعلي بن أبي طالب', 'أبي بكر وعمر', 'عثمان والزبير', 'ليس مما سبق'], 'فخرج النبي ﷺ بين رجلين، تخط رجلاه في الأرض، بين عباس، وعلي بن أبي طالب رضي الله عنهما.');
M(11, 145, 'لما اشتد بالنبي ﷺ وجعه قال: «هريقوا عليّ من …… قِرَب لم تُحلل أوكيتهن، لعلي أعهد إلى الناس»:', ['سبع', 'ثلاث', 'خمس', 'ليس مما سبق'], 'قال ﷺ: (هريقوا علي من سبع قرب لم تحلل أوكيتهن، لعلي أعهد إلى الناس).');
M(11, 145, 'أُجلس النبي ﷺ ليُصبّ عليه الماء من القِرَب في مِخْضَب لـ:', ['حفصة رضي الله عنها', 'ميمونة رضي الله عنها', 'سودة رضي الله عنها', 'ليس مما سبق'], 'قالت عائشة رضي الله عنها: فأجلسناه في مخضب لحفصة زوج النبي ﷺ، ثم طفقنا نصب عليه من تلك القرب.');
M(11, 145, 'بعد أن صُبّ على النبي ﷺ الماء من القرب في مرضه خرج إلى الناس:', ['فصلى بهم وخطبهم', 'فأوصاهم ثم رجع دون أن يصلي', 'فودعهم ولم يكلمهم', 'ليس مما سبق'], 'قالت عائشة رضي الله عنها: حتى طفق يشير إلينا بيده أن قد فعلتن، ثم خرج إلى الناس، فصلى بهم وخطبهم.');

// ثانياً: توكيله ﷺ أبا بكر رضي الله عنه ليصلي بالناس
M(11, 146, 'لما اشتد الوجع بالنبي ﷺ وثقُل، جاء يُؤذِنه بالصلاة:', ['بلال رضي الله عنه', 'ابن أم مكتوم رضي الله عنه', 'أبو محذورة رضي الله عنه', 'ليس مما سبق'], 'فلما اشتد به الوجع، وثقل ﷺ جاء بلال يؤذنه بالصلاة فقال: (مروا أبا بكر فليصل بالناس).');
M(11, 146, 'لما دخل النبي ﷺ المسجد في مرضه وأبو بكر رضي الله عنه يصلي بالناس، فسمع أبو بكر حسّه:', ['ذهب يتأخر، فأومأ إليه ﷺ أن قم مكانك', 'خفّف الصلاة، وأسرع في إتمامها', 'قطع الصلاة، حتى وصل النبي ﷺ إليه', 'ليس مما سبق'], 'فلما دخل المسجد سمع أبو بكر رضي الله عنه حسّه، فذهب يتأخر، فأومأ إليه رسول الله ﷺ: قم مكانك.');
M(11, 146, 'لما وجد النبي ﷺ من نفسه خفة فخرج يُهادى بين رجلين وصلى بالناس، كان ﷺ يصلي بهم:', ['جالسا', 'قائما', 'مضطجعا على جنبه', 'ليس مما سبق'], 'فكان رسول الله ﷺ يصلي بالناس جالسا، وأبو بكر رضي الله عنه قائما، يقتدي أبو بكر بصلاة النبي ﷺ ويقتدي الناس بصلاة أبي بكر.');
M(11, 146, 'لما خرج النبي ﷺ إلى المسجد في مرضه وأبو بكر رضي الله عنه يؤم الناس، كان موضعه ﷺ من أبي بكر:', ['عن يساره', 'عن يمينه', 'خلفه', 'ليس مما سبق'], 'فجاء رسول الله ﷺ حتى جلس عن يسار أبي بكر رضي الله عنه، فكان يصلي بالناس جالسا، وأبو بكر قائما.');
M(11, 146, 'لما كان اليوم الذي قُبض فيه النبي ﷺ أحسّ بنشاط فكشف الستر، فلما رأى أصحابه يصلون جماعة في المسجد:', ['تبسّم', 'بكى', 'خرج فأمّهم', 'ليس مما سبق'], 'فطابت نفسه برؤيتهم، وقرت عينه بحالهم حين رآهم يصلون جماعة في المسجد، صفوفهم متراصة، وقلوبهم متحدة، فتبسم.');
M(11, 146, 'لما رأى الصحابة رضي الله عنهم النبي ﷺ حين كشف الستر في اليوم الذي قُبض فيه ظنوا:', ['أنه شُفي من مرضه', 'أنه غضب منهم', 'أنه يأمرهم بالانصراف', 'ليس مما سبق'], 'فتبسم فظنوا أنه شفي من مرضه، وعوفي من آلامه، ففرحوا فرحا شديدا.');

// ثالثاً: كربات الموت، وقبض روحه ﷺ
M(11, 146, 'دخل على عائشة رضي الله عنها وبيده السواك والنبي ﷺ مستند إليها، فأخذته فليّنته فاستنّ به ﷺ:', ['ليس مما سبق', 'عبد الله بن أبي بكر رضي الله عنه', 'أسامة بن زيد رضي الله عنه', 'الفضل بن العباس رضي الله عنه'], 'الصحيح: عبد الرحمن بن أبي بكر رضي الله عنه؛ قالت عائشة: دخل علي عبد الرحمن بن أبي بكر، وبيده السواك، وأنا مسندة رسول الله ﷺ.');
M(11, 147, 'قالت عائشة رضي الله عنها بعد أن ليّنت السواك للنبي ﷺ فاستنّ به: «فجمع الله بين ريقي وريقه في ……»:', ['آخر يوم من الدنيا وأول يوم من الآخرة', 'آخر يوم من رمضان وأول يوم من شوال', 'آخر ليلة من صفر وأول ليلة من ربيع', 'ليس مما سبق'], 'قالت عائشة رضي الله عنها: فجمع الله بين ريقي وريقه في آخر يوم من الدنيا، وأول يوم من الآخرة.');
M(11, 147, 'كان النبي ﷺ يُدخل يديه في الماء فيمسح بهما وجهه ويقول:', ['لا إله إلا الله، إن للموت سكرات', 'إنا لله وإنا إليه راجعون', 'حسبي الله ونعم الوكيل', 'ليس مما سبق'], 'كان بين يديه ﷺ ركوة أو علبة فيها ماء، فجعل يدخل يديه في الماء، فيمسح بهما وجهه ويقول: (لا إله إلا الله، إن للموت سكرات، اللهم أعني على سكرات الموت).');
M(11, 147, 'لما رأت فاطمة رضي الله عنها ما وجد النبي ﷺ من كرب الموت فقالت: «واكرب أبتاه» قال لها ﷺ:', ['لا كرب على أبيك بعد اليوم', 'لا تبكي فإن الموت حق', 'اصبري فإن الله مع الصابرين', 'ليس مما سبق'], 'فقال رسول الله ﷺ: (لا كرب على أبيك بعد اليوم؛ إنه قد حضر من أبيك ما ليس بتارك منه أحدا، الموافاة يوم القيامة).');
M(11, 148, 'كان النبي ﷺ حين اشتد وجعه يطرح خميصة على وجهه، فإذا اغتم كشفها وقال: «لعنة الله على اليهود والنصارى، ……»:', ['اتخذوا قبور أنبيائهم مساجد', 'حرّفوا الكلم عن مواضعه', 'قتلوا أنبياءهم بغير حق', 'ليس مما سبق'], 'قال ﷺ: (لعنة الله على اليهود والنصارى، اتخذوا قبور أنبيائهم مساجد) يحذر مثل ما صنعوا.');
M(11, 148, 'كان النبي ﷺ حين حضره الموت يكرر وصيته «حتى جعل يغرغر بها صدره، وما يكاد يُفيض بها لسانه»، ومعنى «يُفيض بها»:', ['يقدر على الإفصاح بها', 'يرفع بها صوته', 'يُشير بها بيده', 'ليس مما سبق'], 'حتى جعل رسول الله ﷺ يغرغر بها صدره، وما يكاد يفيض بها – أي: ما يقدر على الإفصاح بها – لسانه.');
M(11, 148, 'قالت عائشة رضي الله عنها: سمعت رسول الله ﷺ يقول: «ما من نبي يمرض إلا ……»:', ['خُيّر بين الدنيا والآخرة', 'غُفر له ما تقدم من ذنبه', 'رُفع إلى السماء', 'ليس مما سبق'], 'قال ﷺ: (ما من نبي يمرض إلا خير بين الدنيا والآخرة)، وكان في شكواه الذي قبض فيه أخذته بحة شديدة... فعلمت أنه خير.');
M(11, 149, 'آخر كلمة تكلم بها رسول الله ﷺ:', ['اللهم الرفيق الأعلى', 'حسبي الله ونعم الوكيل', 'اللهم اغفر لأمتي', 'ليس مما سبق'], 'أفاق فأشخص بصره إلى السقف، ثم قال: (اللهم الرفيق الأعلى)... فكانت تلك آخر كلمة تكلم بها.');
M(11, 149, 'لما مات النبي ﷺ قالت فاطمة رضي الله عنها: «يا أبتاه، أجاب ربا دعاه، يا أبتاه من جنة الفردوس مأواه، يا أبتاه إلى …… ننعاه»:', ['ليس مما سبق', 'ميكائيل', 'إسرافيل', 'أهل المدينة'], 'الصحيح: جبريل؛ قالت فاطمة رضي الله عنها: يا أبتاه إلى جبريل ننعاه.');
M(11, 149, 'كانت وفاة النبي ﷺ في يوم:', ['الاثنين', 'الخميس', 'الجمعة', 'ليس مما سبق'], 'وكانت وفاته ﷺ في يوم الاثنين من شهر ربيع الأول سنة إحدى عشرة من الهجرة بلا خلاف.');
M(11, 149, 'قول الجمهور أن وفاة النبي ﷺ كانت في اليوم …… من شهر ربيع الأول:', ['الثاني عشر', 'الخامس عشر', 'العشرين', 'ليس مما سبق'], 'والجمهور أنها في الثاني عشر من الشهر.');

// تجهيز الجسد الشريف ودفنه ﷺ — أولاً: شدة الخبر على الصحابة رضي الله عنهم
M(11, 150, 'اشتدت المصيبة بموت النبي ﷺ واضطرب المسلمون، حتى قال …… : «إن رسول الله ﷺ لم يمت»:', ['عمر بن الخطاب رضي الله عنه', 'عثمان بن عفان رضي الله عنه', 'علي بن أبي طالب رضي الله عنه', 'ليس مما سبق'], 'اشتدت المصيبة بموته ﷺ، واضطرب المسلمون، حتى قال عمر بن الخطاب رضي الله عنه: «إن رسول الله ﷺ لم يمت...».');
M(11, 150, 'قال أحد الصحابة لما توفي النبي ﷺ: «ولكن ربه أرسل إليه كما أرسل إلى موسى، فمكث عن قومه ……»:', ['أربعين ليلة', 'ثلاثين ليلة', 'سبعين ليلة', 'ليس مما سبق'], 'قال عمر رضي الله عنه: «... ولكن ربه أرسل إليه كما أرسل إلى موسى، فمكث عن قومه أربعين ليلة...».');
M(11, 150, 'من القائل: «أما بعد فمن كان منكم يعبد محمدا ﷺ فإن محمدا قد مات، ومن كان منكم يعبد الله فإن الله حي لا يموت»:', ['أبو بكر الصديق رضي الله عنه', 'عمر بن الخطاب رضي الله عنه', 'العباس بن عبد المطلب رضي الله عنه', 'ليس مما سبق'], 'أقبل أبو بكر رضي الله عنه فقال: «أما بعد فمن كان منكم يعبد محمدا ﷺ فإن محمدا قد مات...».');
M(11, 150, 'الآية التي تُليت على الناس حين اضطربوا لموت النبي ﷺ فعلموا أنه قد مات:', ['﴿وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ الرُّسُلُ﴾', '﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾', '﴿الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ﴾', 'ليس مما سبق'], 'قال أبو بكر رضي الله عنه: قال الله: ﴿وما محمد إلا رسول قد خلت من قبله الرسل أفإن مات أو قتل انقلبتم على أعقابكم...﴾ (آل عمران: 144).');
M(11, 150, 'قال أحد الصحابة حين سمع الآية تُتلى بعد وفاة النبي ﷺ: «فعقرت حتى ما تُقلّني رجلاي»، ومعنى «عقرت»:', ['دُهشت وتحيرت', 'غضبت وثُرت', 'بكيت وانتحبت', 'ليس مما سبق'], 'قال عمر رضي الله عنه: والله ما هو إلا أن سمعت أبا بكر تلاها فعقرت – أي: دهشت وتحيرت –، حتى ما تقلني رجلاي.');

// ثانياً: غسل الجسد الشريف ودفنه
M(11, 151, 'لما اختلف الصحابة في غسل النبي ﷺ ألقى الله عليهم النوم، ثم كلمهم مكلم من ناحية البيت لا يدرون من هو:', ['أن اغسلوا النبي ﷺ وعليه ثيابه', 'أن جرّدوا النبي ﷺ من ثيابه', 'أن يغسّله نساؤه دون الرجال', 'ليس مما سبق'], 'ثم كلمهم مكلم من ناحية البيت لا يدرون من هو: أن اغسلوا النبي ﷺ وعليه ثيابه.');
M(11, 151, 'من القائل: «غسّلتُ رسول الله، فذهبتُ أنظر ما يكون من الميت فلم أرَ شيئا، وكان طيبا ﷺ حيا وميتا»:', ['ليس مما سبق', 'العباس بن عبد المطلب رضي الله عنه', 'أسامة بن زيد رضي الله عنه', 'الفضل بن العباس رضي الله عنه'], 'الصحيح: علي بن أبي طالب رضي الله عنه؛ قال: «غسلت رسول الله، فذهبت أنظر ما يكون من الميت فلم أر شيئا...».');
M(11, 151, 'كُفّن رسول الله ﷺ في:', ['ثلاثة أثواب بيض سحولية من القطن', 'ثوبين أبيضين من القطن مع عمامة', 'قميص وإزار ولفافة من الكتان', 'ليس مما سبق'], 'وكفن رسول الله ﷺ في ثلاثة أثواب بيض سحولية، من القطن، ليس فيها قميص، ولا عمامة.');
M(11, 151, 'لما سأل الناسُ أبا بكر رضي الله عنه: كيف نصلي على رسول الله ﷺ؟ قال:', ['يدخل قوم فيصلون ثم ينصرفون ويجيء آخرون', 'يصلي عليه الناس جماعة واحدة يؤمهم أبو بكر', 'يصلي عليه أهل بيته فقط ثم يدفن', 'ليس مما سبق'], 'قال: «يدخل قوم فيكبرون، ويدعون ويصلون، ثم ينصرفون، ويجيء آخرون، حتى يفرغوا».');
M(11, 152, 'من القائل: «لما كان اليوم الذي دخل فيه رسول الله ﷺ المدينة أضاء منها كل شيء، فلما كان اليوم الذي مات فيه أظلم منها كل شيء»:', ['أنس بن مالك رضي الله عنه', 'أبو هريرة رضي الله عنه', 'عبد الله بن مسعود رضي الله عنه', 'ليس مما سبق'], 'قال أنس بن مالك رضي الله عنه: «لما كان اليوم الذي دخل فيه رسول الله ﷺ المدينة أضاء منها كل شيء...».');
M(11, 152, 'فارق رسول الله ﷺ الدنيا وما ترك دينارا ولا درهما ولا عبدا ولا أمة إلا:', ['جميع ما سبق', 'بغلته البيضاء التي كان يركبها', 'سلاحه', 'أرضا جعلها لابن السبيل صدقة'], '(ما ترك دينارا، ولا درهما، ولا عبدا، ولا أمة، إلا بغلته البيضاء التي كان يركبها، وسلاحه، وأرضا جعلها لابن السبيل صدقة).');

// الدروس المستفادة
M(11, 152, 'من الدروس المستفادة أن الموت نهاية كل حي، ويستوي فيه:', ['جميع ما سبق', 'الكبير والصغير', 'الغني والفقير', 'الأنبياء والرسل'], 'الموت نهاية كل حي، ويستوي فيه كل البشر، كبيرهم وصغيرهم، غنيهم وفقيرهم، حتى الأنبياء والرسل عليهم الصلاة والسلام.');
M(11, 153, 'من الدروس المستفادة تعظيم حقوق المماليك والخدم ونحوهم من الضعفاء؛ لأن النبي ﷺ:', ['أوصى بهم وهو يفارق هذه الدنيا', 'أوصى بهم معاذا حين بعثه إلى اليمن', 'أوصى بهم أبا بكر حين أمره بالصلاة', 'ليس مما سبق'], 'تعظيم حقوق المماليك والخدم ونحوهم من الضعفاء، فالنبي ﷺ أوصى بهم، وهو يفارق هذه الدنيا؛ فقد كانت عامة وصيته حين حضره الموت: (الصلاة وما ملكت أيمانكم).');
M(11, 152, 'من الدروس المستفادة أهمية الصلاة وعظم شأنها؛ فهي عمود الإسلام، و:', ['أول ما يحاسب عليه العبد يوم القيامة', 'آخر ما يحاسب عليه العبد يوم القيامة', 'لا يحاسب عليها العبد إلا بعد الزكاة', 'ليس مما سبق'], 'أهمية الصلاة؛ وعظم شأنها، فهي عمود الإسلام، وأول ما يحاسب عليه العبد يوم القيامة.');
M(11, 153, 'في تقديم أبي بكر الصديق رضي الله عنه على غيره في إمامة الصلاة دليل على:', ['أفضليته على جميع الصحابة وأحقيته بالخلافة', 'أنه أكبر الصحابة رضي الله عنهم سنا', 'أنه أحفظ الصحابة رضي الله عنهم للقرآن', 'ليس مما سبق'], 'في تقديم أبي بكر الصديق رضي الله عنه على غيره في إمامة الصلاة دليل على أفضليته على جميع الصحابة، وتنبيه على أنه أحق بخلافة رسول الله ﷺ.');
M(11, 153, 'روي عن النبي ﷺ أنه قال: «إذا أصاب أحدكم مصيبة، فليتذكر ……، فإنه من أعظم المصائب»:', ['مصابه بي', 'ذنوبه', 'مصائب من قبله', 'ليس مما سبق'], 'مصاب المسلم بالنبي ﷺ لا يعدله مصاب؛ فإذا أصيب أحد بمصيبة فليتذكر مصابه بالنبي ﷺ فإن مصيبته تهون عليه.');

/* ═══════════════ u12 ═══════════════ */
// الوحدة الثانية عشرة: حقوق الرسول ﷺ على أمته (الكتاب ص157–165)

// حقوقه ﷺ على أمته
M(12, 157, 'قال تعالى: ﴿لَقَدْ مَنَّ اللَّهُ عَلَى الْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًا مِّنْ ……﴾:', ['أنفسهم', 'العرب', 'قريش', 'ليس مما سبق'], 'قال تعالى: ﴿لقد من الله على المؤمنين إذ بعث فيهم رسولا من أنفسهم يتلو عليهم آياته ويزكيهم...﴾ (آل عمران: 164).');
M(12, 157, 'أيّد الله تعالى نبيه ﷺ بـ:', ['جميع ما سبق', 'الآيات الباهرة', 'البراهين الواضحة', 'الكرامات البينة'], 'وأيده بالآيات الباهرة، والبراهين الواضحة، والكرامات البينة التي شاهدها من عاصره ورآها من أدركه.');
M(12, 157, 'حق النبي ﷺ علينا:', ['أعظم حقوق المخلوقين', 'يأتي بعد حق الوالدين', 'يأتي بعد حق ولي الأمر', 'ليس مما سبق'], 'وحق النبي ﷺ علينا هو أعظم حقوق المخلوقين، فلا حق لمخلوق أعظم من حق رسول الله ﷺ.');
M(12, 157, 'استدل الكتاب على أن حق النبي ﷺ أعظم حقوق المخلوقين بقوله تعالى:', ['﴿إِنَّا أَرْسَلْنَاكَ شَاهِدًا وَمُبَشِّرًا وَنَذِيرًا﴾', '﴿وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ﴾', '﴿وَاتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ﴾', 'ليس مما سبق'], 'فلا حق لمخلوق أعظم من حق رسول الله ﷺ قال الله تعالى: ﴿إنا أرسلناك شاهدا ومبشرا ونذيرا ۝ لتؤمنوا بالله ورسوله وتعزروه وتوقروه﴾ (الفتح: 8–9).');
M(12, 157, 'حقوق النبي ﷺ على أمته عظيمة:', ['لعظم صاحبها ومنزلته عند الله', 'لكثرة عددها وتنوعها', 'لأنها ثابتة بالقرآن دون السنة', 'ليس مما سبق'], 'وإن للنبي ﷺ حقوقا كثيرة على أمته، وهي عظيمة لعظم صاحبها ومنزلته عند الله.');

// أولاً: الإيمان الصادق به ﷺ
M(12, 157, 'أول حق من حقوق النبي ﷺ على أمته في الكتاب:', ['الإيمان الصادق به ﷺ', 'وجوب طاعته والحذر من معصيته', 'اتباعه والاقتداء بهديه ﷺ', 'ليس مما سبق'], 'ومن هذه الحقوق: أولا: الإيمان الصادق به ﷺ، ثانيا: وجوب طاعته والحذر من معصيته، ثالثا: اتباعه والاقتداء بهديه.');
M(12, 157, 'قال تعالى: ﴿فَآمِنُوا بِاللَّهِ وَرَسُولِهِ وَ…… الَّذِي أَنزَلْنَا﴾ (التغابن: 8):', ['ليس مما سبق', 'الهدى', 'الذكر', 'الفرقان'], 'الصحيح: النور؛ قال تعالى: ﴿فآمنوا بالله ورسوله والنور الذي أنزلنا والله بما تعملون خبير﴾ (التغابن: 8).');
M(12, 158, 'قال ﷺ: «أُمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله و……»:', ['يؤمنوا بي وبما جئت به', 'يهاجروا إلى المدينة', 'يدفعوا الجزية عن يد', 'ليس مما سبق'], 'قال ﷺ: (أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله ويؤمنوا بي وبما جئت به).');
M(12, 158, 'الإيمان بالنبي ﷺ هو:', ['جميع ما سبق', 'تصديق نبوته وأن الله أرسله للجن والإنس', 'تصديقه في جميع ما جاء به من الأمور الماضية والمستقبلة', 'مطابقة تصديق القلب بذلك شهادة اللسان'], 'والإيمان به ﷺ هو: تصديق نبوته، وأن الله أرسله للجن والإنس، وتصديقه في جميع ما جاء به وقاله من الأمور الماضية والمستقبلة، ومطابقة تصديق القلب بذلك شهادة اللسان.');

// ثانياً: وجوب طاعته ﷺ، والحذر من معصيته
M(12, 158, 'استدل الكتاب على وجوب طاعة النبي ﷺ والحذر من معصيته بقوله تعالى:', ['﴿وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانتَهُوا﴾', '﴿إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ﴾', '﴿لَقَدْ مَنَّ اللَّهُ عَلَى الْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًا﴾', 'ليس مما سبق'], 'ثانيا: وجوب طاعته ﷺ، والحذر من معصيته: قال تعالى: ﴿وما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا﴾ (الحشر: 7).');
M(12, 158, 'قال تعالى: ﴿فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَن تُصِيبَهُمْ ……﴾:', ['فتنة أو يصيبهم عذاب أليم', 'قارعة أو تحل قريبا من دارهم', 'صاعقة مثل صاعقة عاد وثمود', 'ليس مما سبق'], 'قال تعالى: ﴿فليحذر الذين يخالفون عن أمره أن تصيبهم فتنة أو يصيبهم عذاب أليم﴾ (النور: 63).');
M(12, 158, 'قال ﷺ: «من أطاعني فقد أطاع الله، ومن عصاني ……»:', ['فقد عصى الله', 'فقد ظلم نفسه', 'فلا يلومن إلا نفسه', 'ليس مما سبق'], 'عن أبي هريرة أن رسول الله ﷺ قال: (من أطاعني فقد أطاع الله ومن عصاني فقد عصى الله).');
M(12, 158, 'قال ﷺ: «كل أمتي يدخلون الجنة إلا من أبى»، قالوا: يا رسول الله ومن يأبى؟ قال:', ['ليس مما سبق', 'من لم يصلّ عليّ', 'من لم يهاجر', 'من ترك الجهاد'], 'الصحيح: (من عصاني)؛ قال ﷺ: (من أطاعني دخل الجنة ومن عصاني فقد أبى).');

// ثالثاً: اتباعه والاقتداء بهديه ﷺ
M(12, 159, 'قال تعالى: ﴿قُلْ إِن كُنتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي ……﴾:', ['يحببكم الله ويغفر لكم ذنوبكم', 'يدخلكم جنات تجري من تحتها الأنهار', 'يجعل لكم فرقانا ويكفر عنكم سيئاتكم', 'ليس مما سبق'], 'قال تعالى: ﴿قل إن كنتم تحبون الله فاتبعوني يحببكم الله ويغفر لكم ذنوبكم والله غفور رحيم﴾ (آل عمران: 31).');
M(12, 159, 'قال ﷺ: «من رغب عن سنتي ……»:', ['فليس مني', 'فقد ضل', 'فقد أبى', 'ليس مما سبق'], 'قال ﷺ: (من رغب عن سنتي فليس مني).');
M(12, 159, 'معنى قولنا: «محمد رسول الله»:', ['أن لا متبوع بحق إلا رسول الله ﷺ', 'أن لا معبود بحق إلا الله', 'أن محمدا ﷺ لا يملك لنفسه ضرا ولا نفعا', 'ليس مما سبق'], 'فقولنا: محمد رسول الله، معناه: أن لا متبوع بحق إلا رسول الله ﷺ.');
M(12, 159, 'يجب السير على هدي النبي ﷺ والتزام سنته والحذر من مخالفته، و:', ['لا نقدّم قول أحد على قوله', 'نقدّم قول الصحابي على قوله إذا خالفه', 'نقدّم أقوال العلماء على قوله', 'ليس مما سبق'], 'فيجب السير على هديه والتزام سنته، والحذر من مخالفته، ولا نضع في مقابله أحدا ولا نقدم قول أحد على قوله.');

// رابعاً: أن لا نعبد الله إلا بما شرع ﷺ
M(12, 159, 'قوله ﷺ: «من عمل عملا ليس عليه أمرنا فهو رد» دليل على حق:', ['أن لا نعبد الله إلا بما شرع ﷺ', 'الصلاة والسلام عليه ﷺ', 'نشر دعوته ﷺ', 'ليس مما سبق'], 'رابعا: أن لا نعبد الله إلا بما شرع ﷺ: يقول ﷺ: (من عمل عملا ليس عليه أمرنا فهو رد).');

// خامساً: محبته ﷺ أكثر من الأهل والولد، والوالد، والناس أجمعين
M(12, 160, 'قال ﷺ: «لا يؤمن أحدكم حتى أكون أحب إليه من ……»:', ['والده وولده والناس أجمعين', 'ماله وتجارته ومسكنه', 'زوجه وعشيرته', 'ليس مما سبق'], 'عن أنس قال، قال النبي ﷺ: (لا يؤمن أحدكم حتى أكون أحب إليه من والده وولده والناس أجمعين).');
M(12, 160, 'قال ﷺ: «…… من كن فيه وجد بهن حلاوة الإيمان»:', ['ثلاث', 'أربع', 'خمس', 'ليس مما سبق'], 'قال ﷺ: (ثلاث من كن فيه وجد بهن حلاوة الإيمان: من كان الله ورسوله أحب إليه مما سواهما...).');
M(12, 160, 'من أحب النبي ﷺ من قلبه صدقا:', ['أطاعه ﷺ', 'استغنى بمحبته عن طاعته', 'اكتفى بالصلاة عليه عن اتباعه', 'ليس مما سبق'], 'لأنه رضي به رسولا، وأحبه، ومن أحبه من قلبه صدقا أطاعه ﷺ.');
M(12, 160, 'من علامات محبة النبي ﷺ:', ['جميع ما سبق', 'الاقتداء به واتباع سنته', 'امتثال أوامره واجتناب نواهيه', 'التأدب بآدابه والنصيحة له'], 'وعلامات محبته ﷺ تظهر في الاقتداء به ﷺ، واتباع سنته، وامتثال أوامره، واجتناب نواهيه، والتأدب بآدابه، والنصيحة له.');
M(12, 160, 'قال ﷺ: «الدين النصيحة» قلنا: لمن؟ قال:', ['لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم', 'لله ولرسوله وللوالدين والأقربين', 'لأئمة المسلمين وعلمائهم خاصة', 'ليس مما سبق'], 'قال ﷺ: (الدين النصيحة) قلنا لمن قال: (لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم).');
M(12, 160, 'تكون النصيحة لرسول الله ﷺ بـ:', ['جميع ما سبق', 'التصديق بنبوته', 'مؤازرته ونصرته', 'التخلق بأخلاقه الكريمة وآدابه الجميلة'], 'والنصيحة لرسوله ﷺ تكون بالتصديق بنبوته، وطاعته فيما أمر به، واجتناب ما نهى عنه، ومؤازرته، ونصرته، وإحياء سنته والعمل بها وتعلمها وتعليمها والذب عنها ونشرها، والتخلق بأخلاقه الكريمة وآدابه الجميلة.');

// سادساً: احترامه، وتوقيره، ونصرته ﷺ
M(12, 161, 'قوله تعالى: ﴿لِّتُؤْمِنُوا بِاللَّهِ وَرَسُولِهِ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ﴾ استدل به الكتاب على حق:', ['احترامه وتوقيره ونصرته ﷺ', 'نشر دعوته ﷺ', 'الصلاة والسلام عليه ﷺ', 'ليس مما سبق'], 'سادسا: احترامه، وتوقيره، ونصرته ﷺ: قال تعالى: ﴿لتؤمنوا بالله ورسوله وتعزروه وتوقروه﴾ (الفتح: 9).');
M(12, 161, 'فسّر الشيخ السعدي رحمه الله قوله تعالى: ﴿وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ﴾ بـ:', ['ليس مما سبق', 'تتبعوه وتقتدوا بهديه', 'تكثروا من الصلاة والسلام عليه', 'تنشروا دعوته وتبلغوا عنه'], 'الصحيح: تعظموه وتجلوه وتقوموا بحقوقه؛ قال السعدي: «أي تعزروا الرسول وتوقروه، أي تعظموه، وتجلوه، وتقوموا بحقوقه».');
M(12, 161, 'حرمة النبي ﷺ ونصرته وتوقيره بعد موته:', ['واجب كوجوبه حال حياته', 'مستحب وليس بواجب', 'سقط وجوبه بموته ﷺ', 'ليس مما سبق'], 'وحرمة النبي ﷺ ونصرته وتوقيره بعد موته واجب، كوجوبه حال حياته.');
M(12, 161, 'توقير النبي ﷺ بعد مماته يكون بتوقير:', ['سنته وشرعه القويم', 'أقوال أصحابه دون سنته', 'شخصه دون سنته', 'ليس مما سبق'], 'فتوقيره في حياته توقير سنته وشخصه الكريم، وتوقيره بعد مماته توقير سنته وشرعه القويم.');

// سابعاً: الصلاة والسلام عليه ﷺ
M(12, 161, 'قال تعالى: ﴿إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ ۚ يَا أَيُّهَا الَّذِينَ آمَنُوا ……﴾:', ['صلوا عليه وسلموا تسليما', 'أطيعوا الله وأطيعوا الرسول', 'لا ترفعوا أصواتكم فوق صوت النبي', 'ليس مما سبق'], 'قال الله تعالى: ﴿إن الله وملائكته يصلون على النبي يا أيها الذين آمنوا صلوا عليه وسلموا تسليما﴾ (الأحزاب: 56).');
M(12, 161, 'قال ﷺ: «من صلى عليّ صلاة صلى الله عليه بها ……»:', ['ليس مما سبق', 'ثلاثا', 'مائة', 'خمسا'], 'الصحيح: عشرا؛ قال ﷺ: (من صلى علي صلاة صلى الله عليه بها عشرا).');
M(12, 161, 'قال ﷺ: «البخيل الذي ……»:', ['من ذُكرت عنده فلم يصلّ عليّ', 'من سمع الأذان فلم يُجب', 'من جاءه السائل فردّه', 'ليس مما سبق'], 'قال ﷺ: (البخيل الذي من ذكرت عنده فلم يصل علي).');
M(12, 162, 'من معاني السلام على النبي ﷺ:', ['السلامة من النقائص والآفات لك ومعك', 'الإكثار من ذكره في المجالس', 'رفع الصوت بذكره عند سماع اسمه', 'ليس مما سبق'], 'ومعنى السلام عليه ﷺ: السلامة من النقائص والآفات لك ومعك، وأن الله تعالى مداوم على حفظك ورعايتك.');
M(12, 162, 'ومن معاني السلام على النبي ﷺ: الدعاء بأن يجعل الله تعالى العباد …… له ﷺ ولشريعته:', ['منقادين مذعنين', 'محبين مشتاقين', 'ذاكرين شاكرين', 'ليس مما سبق'], 'ومعنى السلام عليه ﷺ: السلامة من النقائص والآفات لك ومعك، وأن الله تعالى مداوم على حفظك ورعايتك، والدعاء بأن يجعل الله تعالى العباد منقادين مذعنين له – عليه الصلاة والسلام – ولشريعته.');
M(12, 162, 'من صيغ الصلاة على النبي ﷺ التي ذكرها الكتاب: «اللهم صلّ على محمد و……، كما صليت على آل إبراهيم»:', ['أزواجه وذريته', 'أصحابه وأتباعه', 'أنصاره وأعوانه', 'ليس مما سبق'], 'من صيغ الصلاة: (اللهم صل على محمد وأزواجه وذريته كما صليت على آل إبراهيم، وبارك على محمد وأزواجه وذريته كما باركت على آل إبراهيم إنك حميد مجيد).');
M(12, 163, 'صيغة السلام على النبي ﷺ هي قولنا في التشهد:', ['السلام عليك أيها النبي ورحمة الله وبركاته', 'السلام علينا وعلى عباد الله الصالحين', 'السلام على رسول الله وعلى آله', 'ليس مما سبق'], 'وصيغة السلام على النبي ﷺ هو قولنا في التشهد: السلام عليك أيها النبي ورحمة الله وبركاته.');

// ثامناً: وجوب التحاكم إليه، والرضا بحكمه ﷺ
M(12, 163, 'من حق النبي ﷺ: الإيمان بأن هديه أكمل الهدي وشريعته أكمل الشرائع، و:', ['أن لا يُقدّم عليها تشريع أو نظام مهما كان مصدره', 'أن يُقدّم عليها العرف إذا تعارضا', 'أن يُقدّم عليها النظام عند الحاجة', 'ليس مما سبق'], 'والإيمان بأن هديه أكمل الهدي وشريعته أكمل الشرائع وأن لا يقدم عليها تشريعا أو نظاما مهما كان مصدره.');
M(12, 163, 'قال تعالى: ﴿فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا فِي أَنفُسِهِمْ ……﴾:', ['حرجا مما قضيت', 'غلا للذين آمنوا', 'حاجة مما أوتوا', 'ليس مما سبق'], 'قال تعالى: ﴿فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في أنفسهم حرجا مما قضيت ويسلموا تسليما﴾ (النساء: 65).');
M(12, 163, 'قال تعالى: ﴿فَإِن تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى ……﴾:', ['الله والرسول', 'العلماء والأمراء', 'أهل الذكر', 'ليس مما سبق'], 'قال تعالى: ﴿يا أيها الذين آمنوا أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم فإن تنازعتم في شيء فردوه إلى الله والرسول...﴾ (النساء: 59).');

// تاسعاً: إنزاله مكانته ﷺ بلا غلو ولا تقصير
M(12, 163, 'من حقوق النبي ﷺ على أمته: إنزاله مكانته:', ['بلا غلو ولا تقصير', 'بالغلو فيه محبة له', 'بالتقصير في مدحه خشية الغلو', 'ليس مما سبق'], 'تاسعا: إنزاله مكانته ﷺ بلا غلو ولا تقصير.');
M(12, 163, 'النبي ﷺ:', ['جميع ما سبق', 'أفضل الأنبياء والمرسلين', 'سيد الأولين والآخرين', 'صاحب المقام المحمود والحوض المورود'], 'فهو عبد لله ورسوله، وهو أفضل الأنبياء والمرسلين، وهو سيد الأولين والآخرين، وهو صاحب المقام المحمود، والحوض المورود.');
M(12, 163, 'النبي ﷺ مع علو منزلته:', ['بشر لا يملك لنفسه ولا لغيره ضرا ولا نفعا إلا ما شاء الله', 'يعلم الغيب كله ولا يخفى عليه شيء', 'يملك النفع والضر لمن دعاه بعد موته', 'ليس مما سبق'], 'ولكنه مع ذلك بشر لا يملك لنفسه ولا لغيره ضرا ولا نفعا إلا ما شاء الله.');
M(12, 164, 'قال تعالى: ﴿قُل لَّا أَمْلِكُ لِنَفْسِي نَفْعًا وَلَا ضَرًّا إِلَّا مَا شَاءَ اللَّهُ ۚ وَلَوْ كُنتُ أَعْلَمُ الْغَيْبَ ……﴾:', ['لاستكثرت من الخير وما مسني السوء', 'لأخبرتكم بما تأكلون وما تدخرون', 'ما أصابني حزن ولا هم', 'ليس مما سبق'], 'قال تعالى: ﴿... ولو كنت أعلم الغيب لاستكثرت من الخير وما مسني السوء إن أنا إلا نذير وبشير لقوم يؤمنون﴾ (الأعراف: 188).');
M(12, 164, 'قال ﷺ: «لا تطروني كما أطرت النصارى ……»:', ['ليس مما سبق', 'يحيى بن زكريا', 'موسى بن عمران', 'زكريا عليه السلام'], 'الصحيح: ابن مريم؛ قال ﷺ: (لا تطروني كما أطرت النصارى ابن مريم).');

// عاشراً: نشر دعوته ﷺ
M(12, 164, 'من حقوق النبي ﷺ نشر دعوته؛ يقول ﷺ: «بلّغوا عني ولو ……»:', ['آية', 'حديثا', 'كلمة', 'ليس مما سبق'], 'عاشرا: نشر دعوته ﷺ: يقول ﷺ: (بلغوا عني ولو آية).');

// الحادية عشرة: موالاة أوليائه، وبغض أعدائه ﷺ
M(12, 164, 'قوله تعالى: ﴿لَّا تَجِدُ قَوْمًا يُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ يُوَادُّونَ مَنْ حَادَّ اللَّهَ وَرَسُولَهُ﴾ استدل به الكتاب على حق:', ['موالاة أوليائه وبغض أعدائه ﷺ', 'نشر دعوته ﷺ', 'الصلاة والسلام عليه ﷺ', 'ليس مما سبق'], 'الحادية عشرة: موالاة أوليائه، وبغض أعدائه ﷺ: قال تعالى: ﴿لا تجد قوما يؤمنون بالله واليوم الآخر يوادون من حاد الله ورسوله...﴾ (المجادلة: 22).');
M(12, 164, 'من موالاة النبي ﷺ موالاة أصحابه، ومن ذلك:', ['الإمساك عما شجر بينهم', 'الخوض فيما شجر بينهم', 'الثناء على بعضهم دون بعض', 'ليس مما سبق'], 'ومن موالاته: موالاة أصحابه ومحبتهم، وبرهم، ومعرفة حقهم، والثناء عليهم، والاقتداء بهم، والاستغفار لهم، والإمساك عما شجر بينهم.');
M(12, 164, 'من موالاة النبي ﷺ تجاه آل بيته:', ['محبتهم وموالاتهم والذب عنهم وترك الغلو فيهم', 'محبتهم والغلو فيهم ورفعهم فوق منزلتهم', 'ترك الحديث عنهم والإمساك عن ذكرهم', 'ليس مما سبق'], 'وكذلك محبة آل بيته وموالاتهم والذب عنهم، وترك الغلو فيهم.');
M(12, 165, 'قال ﷺ: «لا تسبوا أصحابي، فلو أن أحدكم أنفق مثل …… ذهبا ما بلغ مُدّ أحدهم ولا نصيفه»:', ['ليس مما سبق', 'الأرض', 'الكعبة', 'جبل ثور'], 'الصحيح: أُحُد؛ قال ﷺ: (لا تسبوا أصحابي، فلو أن أحدكم أنفق مثل أحد، ذهبا ما بلغ مد أحدهم، ولا نصيفه).');

// الدروس المستفادة
M(12, 165, 'من الدروس المستفادة أن الطريق الصحيح لأداء حقوق النبي ﷺ هو:', ['ما كان عليه سلف هذه الأمة من الصحابة فمن بعدهم', 'ما يستحسنه كل مسلم بحسب اجتهاده', 'ما جرت به عادات الناس في كل بلد', 'ليس مما سبق'], 'أن الطريق الصحيح لأداء هذه الحقوق هو ما كان عليه سلف هذه الأمة من الصحابة الكرام فمن بعدهم.');
M(12, 165, 'من الدروس المستفادة أن الواجب على المسلم تجاه حقوق النبي ﷺ:', ['معرفتها وتعليمها والذب عنه ﷺ', 'معرفتها دون تعليمها لغيره', 'تركها للعلماء خاصة', 'ليس مما سبق'], 'أن الواجب على المسلم معرفة هذه الحقوق وتعليمها، والذب عنه ﷺ.');

window.QUESTIONS=Q;
